INSERT INTO `_koKR_stage_quest_template_locale` (`ID`, `LogTitle`, `QuestDescription`, `LogDescription`, `AreaDescription`, `QuestCompletionLog`, `PortraitGiverText`) VALUES
(1, NULL, NULL, NULL, NULL, '칸테타드에게 가야합니다.', NULL),
(6, NULL, NULL, NULL, NULL, '엘윈 숲의 북녘골 수도원에 있는 부관 윌렘에게 가야 합니다.', NULL),
(7, NULL, NULL, NULL, NULL, '엘윈 숲의 북녘골 수도원에 있는 치안대장 맥브라이드에게 가야 합니다.', NULL),
(8, '도적의 거래', '이보시오! 감당하기 힘들만큼 많은 실성한 좀비와 거미들을 상대로 싸워온 젊은이의 청 하나 들어주지 않으시겠소?$B$B여기 이 편지를 브릴에 있는 여관주인에게 가져가야 하는데… 이름이 리니 뭐라고 하더군. 성이야 몰라도 상관없소.$B$B어쨌든 그 여관은 세상을 헤쳐나가려는 역병의 희생자들이 모여있는 아담하고 아늑한 곳이지. 필요하면 휴식을 취하기에도 좋은 장소라오. 한번 다녀와 보시오. 돌아오면 수고비는 넉넉히 주겠소.', '티리스팔 숲에 있는 여관주인 리니에게 평범한 편지를 가져가야 합니다.', NULL, NULL, NULL),
(9, NULL, NULL, NULL, NULL, '서부 몰락지대의 살딘 농장에 있는 농부 살딘에게 가야 합니다.', NULL),
(10, '슈섕크 탈출', '이런 끔찍한 일이! 내 수석 조수이자 전 후임측량사였던 슈섕크를 여기서 남동쪽에 있는 사막으로 보냈었소. 우리가 모래지옥 협곡이라고 부르는 곳인데… 그러니까, 그 친구가 실종되어 버리고 말았소. 마지막으로 받은 보고에 의하면 그곳에 이상한 곤충들이 수도 없이 나타났다고 하오. 그렇다면, 벌써 사막의 주요 구역이 두 군데나 점령당한 걸까?$B$B모래지옥 협곡으로 가서 슈섕크를 찾아 주시오, 제발! 아니면 그의 측량 장비만이라도… 남은 거라고는 그것뿐일지도 모르겠소이다.', '후임측량사 슈섕크가 어떻게 되었는지 알아보고 가젯잔에 있는 선임측량사 피즐도저에게 데려오거나 그의 측량 장비라도 찾아서 가져가야 합니다.', NULL, '타나리스의 가젯잔에 있는 선임측량사 피즐도저에게 가야 합니다.', NULL),
(11, NULL, NULL, NULL, NULL, '엘윈 숲의 숲 가장자리에 있는 부관 레이너에게 가야 합니다.', NULL),
(12, NULL, NULL, NULL, NULL, '서부 몰락지대의 감시의 언덕에 있는 그라이언 스타우트맨틀에게 가야 합니다.', NULL),
(13, NULL, NULL, NULL, NULL, '서부 몰락지대의 감시의 언덕에 있는 그라이언 스타우트맨틀에게 가야 합니다.', NULL),
(14, NULL, NULL, NULL, NULL, '서부 몰락지대의 감시의 언덕에 있는 그라이언 스타우트맨틀에게 가야 합니다.', NULL),
(15, NULL, NULL, NULL, NULL, '엘윈 숲의 북녘골 수도원에 있는 치안대장 맥브라이드에게 가야 합니다.', NULL),
(16, NULL, NULL, NULL, NULL, '그늘숲에 있는 제라드 틸러에게 가야 합니다.', NULL),
(17, '울다만에서 재료 찾기', '자홍버섯이라는 식물이 새로이 발견되었다는 얘기를 들었다오. 자홍버섯은 울다만 발굴현장에서 군생하고 너무 깊숙이 탐험하지 않아도 되는 지역 내에 긴 굴 입구에서 찾을 수 있다오. 난 그 버섯이 연금술에 사용할 잠재적인 가치가 있는지 연구하고 싶소. 그래서 당신의 도움이 필요하다오.$B$B자홍버섯을 찾아서 나에게 12개만 가져다주시오. 버섯송이에 가까이 가면 포자에서 독이 발산되니 조심하시오.$B$B날 위해 이 일을 맡아주시오. 돌아오면 내 당신을 격려하는 의미에서 유명한 나의 복원의 비약을 한 꾸러미 주겠소이다!', '텔사마에 있는 가크 힐터치에게 자홍버섯 12개를 가져가야 합니다.', NULL, '모단 호수의 텔사마에 있는 가크 힐터치에게 가야 합니다.', NULL),
(18, NULL, NULL, NULL, NULL, '엘윈 숲의 북녘골 계곡에 있는 부관 윌렘에게 가야 합니다.', NULL),
(19, NULL, NULL, NULL, NULL, '붉은마루 산맥의 호숫골에 있는 치안대장 매리스에게 가야 합니다.', NULL),
(20, NULL, NULL, NULL, NULL, '붉은마루 산맥의 호숫골에 있는 치안대장 매리스에게 가야 합니다.', NULL),
(21, '메아리 광산 전투', '일전에 당신이 조사한 결과를 볼 때 메아리 광산에 있는 코볼트 녀석들을 없애야 할 거 같습니다. 당신이 광산으로 돌아가서 코볼트를 제거하는 일을 도와주십시오.$B$B지체할 시간이 없습니다. 저런 상태로 코볼트들이 방치되면 방치될수록 녀석들이 북녘골 깊숙이 터전을 마련하게 될 테니 말입니다.', '코볼트 일꾼 8마리를 처치한 다음 북녘골 수도원에 있는 치안대장 맥브라이드에게 가야 합니다.', NULL, '엘윈 숲의 북녘골 수도원에 있는 치안대장 맥브라이드에게 가야 합니다.', NULL),
(22, NULL, NULL, NULL, NULL, '서부 몰락지대의 살딘 농장에 있는 살마 살딘에게 가야 합니다.', NULL),
(26, '귀중한 교훈', '$N, 나는 지금까지 아주 기쁜 마음으로 그대가 발전하는 모습을 지켜봐 왔소. 확실히 그대는 소중한 자연의 수호자로 성장해 가고 있소.$B$B우리는 세나리우스의 축복으로 여러 가지 동물의 형상을 취할 수 있게 되었지. 이제 그중 하나에 대해 자세히 배워야 할 때가 되었소. 바로 수중 세계를 자유자재로 제어할 수 있는 상이오. 이것을 배우려면 달숲에 있는 밤의 안식처으로 가서, 세나리온 의회의 일원인 덴드리트 스타블레이즈와 얘기해 보시오. 그가 자세히 가르쳐 줄 거요.', '달숲, 밤의 안식처에 있는 덴드리트 스타블레이즈와 대화해야 합니다.', NULL, NULL, NULL),
(27, '꼭 배워야 할 교훈', '나는 지금까지 죽 그대가 발전하는 모습을 아주 기쁜 마음으로 지켜봐 왔네. 확실히 그대는 소중한 자연의 수호자로 성장해 가고 있군.$B$B이제 세나리우스의 축복으로 우리가 그 형상을 취할 수 있게 된 여러 가지 동물의 상 중 하나에 대해 더 자세히 배워야 할 때가 되었네. 바로 수중 형상을 통달하는 것이지. 이를 배우려면 달숲에 있는 밤의 안식처으로 가서 그곳에 있는 세나리온 의회의 일원인 덴드리트 스타블레이즈와 얘기해 보시게. 그가 더 자세히 가르쳐 줄 걸세.', '달숲의 밤의 안식처에 있는 덴드리트 스타블레이즈와 대화해야 합니다.', NULL, NULL, NULL),
(28, '엘룬아라 호수의 시험', '첫 번째 시험으로, 엘룬아라 호수의 깊은 곳을 뒤져 제단 구슬을 찾으십시오. 제단 구슬은 금방 그 효력이 다하니 서둘러서 레물로스의 제단으로 가져가야 합니다. 제단에서 구슬을 사용한 다음, 그곳에 있는 타자리와 얘기를 나누십시오. 그녀는 달숲에서 가장 신임받는 관리인 중 한 명입니다.$B$B이번 임무는 제한된 시간 내에 완료해야 하는데다, 구슬을 찾는 다른 드루이드들과 경쟁을 벌이게 될 수도 있으니 각오를 단단히 하셔야 할 겁니다. 그대의 정신과 신체의 민첩성이 바로 성공의 열쇠가 될 겁니다.$B$B그럼, 행운을 빌겠습니다, $N.', '엘룬아라 호수에서 제단 구슬을 찾은 후, 달의 숲 북서부에 있는 레물로스의 제단으로 가져가야 합니다. 그곳에 이르면 제단 구슬을 사용하십시오.$B$B그런 다음 제단에 있는 타자리와 대화해야 시험이 끝납니다.', '호수의 시련을 완료하세요.', '달숲의 레물로스의 제단에 있는 타자리에게 가야 합니다.', NULL),
(29, '엘룬아라 호수의 시험', '첫 번째 시험으로, 엘룬아라 호수의 깊은 곳을 뒤져 제단 구슬을 찾도록 하십시오. 제단 구슬은 그 효력이 금방 다하니 서둘러서 레물로스의 제단으로 가져가십시오. 제단에서 구슬을 사용한 다음, 그곳에 있는 타자리와 얘기를 해보십시오. 달숲에서 가장 신뢰받는 관리인 중 한 명이죠.$B$B이번 임무는 제한된 시간 내에 완료해야 하는데다가, 구슬을 찾는 다른 드루이드들과 경쟁을 벌이게 될 수도 있으니, 각오를 단단히 하시기 바랍니다. 당신의 정신과 신체의 민첩성이 바로 성공의 열쇠가 될 겁니다.$B$B그럼 행운을 빌겠습니다, $N.', '엘룬아라 호수에서 제단 구슬을 찾은 후 달의 숲 북서부에 있는 레물로스의 제단으로 가져가야 합니다. 그곳에 이르면 제단 구슬을 사용하십시오.$B$B그런 다음 제단에 있는 타자리와 대화를 하면 이 시험을 통과하게 됩니다.', '호수의 시련을 완료하세요.', '달숲의 레물로스의 제단에 있는 타자리에게 가야 합니다.', NULL),
(30, NULL, NULL, NULL, NULL, '달숲의 밤의 안식처에 있는 덴드리트 스타블레이즈에게 가야 합니다.', NULL),
(31, '바다표범 변신', '그대는 젊은 드루이드가 바다표범으로 변신하기 위해 배워야 할 교훈을 모두 얻었습니다. 이제 썬더 블러프에 있는 상급 드루이드, 투락 룬토템에게 다시 가보십시오. 그에게 이 펜던트를 보여 주면 그대가 가르침을 받을 준비가 됐다는 걸 믿어 의심치 않을 겁니다. 그에게 물과 하나가 되는 법을 배우면, 그대의 이번 훈련은 끝이 나는 것입니다.$B$B젊은 드루이드여, 안녕히… 훗날을 기약합시다.', '썬더 블러프로 돌아가 투락 룬토템에게 바다표범의 펜던트를 보여 줘야 합니다.', NULL, '완성된 펜던트를 달의 숲, 나이트헤이븐에 있는 덴드리트 스타블레이즈에게 가져가십시오.', NULL),
(32, '실리시드의 전조', '여기 보고서를 받으시오. 이 보고서는 이런 일에 대해 실제로 잘 아는 사람에게 가져가는 것이 좋겠소.$B$B질지빈 드럼로어라는 트롤 학자를 알고 있는데 아제로스 생태계 고유의 생물들을 연구하며 많은 시간을 보내고 있소. 게다가 역사학에도 조예가 깊다오. 이 보고서를 그에게 전하면 이 위협이 정확히 무엇인지 그리고 그것을 막을 방법이 있는지 알 게 될 테지. 분명 도움을 줄 것이오. 이번 일에는 우리가 만날 수 있는 모든 이의 도움이 필요하오.$B$B내가 마지막으로 들은 소식에 의하면 질지빈은 오그리마의 골목길 2층에 있는 집에 살고 있다고 합디다.', '오그리마에 있는 질지빈 드럼로어에게 보고서를 가져가야 합니다.', NULL, NULL, NULL),
(33, NULL, NULL, NULL, NULL, '엘윈 숲의 북녘골 계곡에 있는 이건 펠트스키너에게 가야 합니다.', NULL),
(34, NULL, NULL, NULL, NULL, '붉은마루 산맥의 호숫골에 있는 마티 제인로즈에게 가야 합니다.', NULL),
(38, NULL, NULL, NULL, NULL, '서부 몰락지대의 살딘 농장에 있는 살마 살딘에게 가야 합니다.', NULL),
(39, '토마스의 보고 전달', '더그한 치안대장님께 말라카이와 롤프의 죽음을 말씀드려 주십시오. 그리고 엘윈 숲 동쪽에 있는 멀록들을 견제하기엔 현재 병력만으로는 무리라고 보고해 주시기 바랍니다.$B$B이쪽에 충분한 병력을 배치할 만큼 상황이 여의치 않다는 것은 알지만 더그한님께서 이 지역에 희망이 되어 줄 누군가를 보내주시리라 믿습니다.', '황금골에 있는 치안대장 더그한에게 보고해야 합니다.', NULL, NULL, NULL),
(46, NULL, NULL, NULL, NULL, '엘윈 숲에 있는 경비병 토마스에게 가야 합니다.', NULL),
(47, NULL, NULL, NULL, NULL, '엘윈 숲의 황금골에 있는 말더듬이 레미에게 가야 합니다.', NULL),
(48, '달콤한 황색 맥주', '남쪽 땅 그곳을 휘감는 덩굴 $B$B그 아래 깊은 곳에 흐르는 샘물 $B$B빛의 성스러운 딸을 닮은 그 순수 $B$B내게로 가져다주오 신성한 샘물을', '그림부즈 썬더브루에게 신성한 샘물을 가져가야 합니다.', NULL, '서부 몰락지대의 비수 언덕에 있는 그림부즈 썬더브루에게 가야 합니다.', NULL),
(49, '달콤한 황색 맥주', '황색은 내 평생 사랑의 색조 $B$B하늘에 물드는 마지막 황혼을 닮았네 $B$B내 사랑이 열매 맺도록 가져다주오 $B$B보리와 호밀 그리고 옥수수 부대를', '그림부즈 썬더브루에게 보리, 호밀, 옥수수 부대를 가져가야 합니다.', NULL, '서부 몰락지대의 비수 언덕에 있는 그림부즈 썬더브루에게 가야 합니다.', NULL),
(50, '달콤한 황색 맥주', '녹이고 녹여, 섞고 또 섞어 $B$B아무도 모를 우리만의 비법 $B$B튼튼한 금속으로 증류기를 만드세 $B$B진은을 구해 주오, 이 노래를 마칠 수 있도록', '그림부즈 썬더브루에게 진은 주괴를 가져가야 합니다.', NULL, '서부 몰락지대의 비수 언덕에 있는 그림부즈 썬더브루에게 가야 합니다.', NULL),
(51, '달콤한 황색 맥주', '아직은 여과 안 된 신선한 증류주 $B$B경작을 기다리는 농토와 같네 $B$B숯 한 묶음을 만들어야지 $B$B이번에 필요한 건 플라타너스 가지 하나', '그림부즈 썬더브루에게 플라타너스 가지 하나를 가져가야 합니다.', NULL, '서부 몰락지대의 비수 언덕에 있는 그림부즈 썬더브루에게 가야 합니다.', NULL),
(52, NULL, NULL, NULL, NULL, '엘윈 숲에 있는 경비병 토마스에게 가야 합니다.', NULL),
(53, '달콤한 황색 맥주', '감미로운 액체는 아기 눈물처럼 맑고 $B$B여러 해가 지나면 깊고 아름다운 황색이 되네 $B$B하지만 이 술에 흠뻑 취하기 전에 $B$B참나무 숯으로 맥주통을 만들어야지', '그림부즈 썬더브루에게 참나무 숯 한 묶음을 가져가야 합니다.', NULL, '서부 몰락지대의 비수 언덕에 있는 그림부즈 썬더브루에게 가야 합니다.', NULL),
(55, '모벤트 펠', '모벤트 펠은 까마귀 언덕 묘지가 내려다보이는 동쪽의 언덕 위에 있는 자신의 집에 숨어 있습니다. 이제 이 땅에서 그의 시대는 곧 끝나게 될 겁니다…$B$B모벤트 파멸의 불꽃을 사용하여 그에게 대항하십시오. 불꽃은 그를 보호하고 있는 마법을 무력하게 할 겁니다.$B$B그를 처치하여 우리를 사악한 손길로부터 구해 주시기 바랍니다. 내 복수를 해 주시고 그늘숲의 영웅이 되십시오!', '모벤트 파멸의 불꽃을 사용하여 모벤트 펠을 처치하고 스벤의 야영지에 있는 스벤에게 모벤트 파멸의 불꽃을 돌려줘야 합니다.', NULL, '그늘숲의 고요의 강둑에 있는 스벤 요르겐에게 가야 합니다.', NULL),
(56, NULL, NULL, NULL, NULL, '그늘숲의 어둠골에 있는 사령관 알시아 이본로크에게 가야 합니다.', NULL),
(57, NULL, NULL, NULL, NULL, '그늘숲의 어둠골에 있는 사령관 알시아 이본로크에게 가야 합니다.', NULL),
(58, NULL, NULL, NULL, NULL, '그늘숲의 어둠골에 있는 사령관 알시아 이본로크에게 가야 합니다.', NULL),
(60, NULL, NULL, NULL, NULL, '엘윈 숲의 황금골에 있는 윌리엄 페슬에게 가야 합니다.', NULL),
(62, NULL, NULL, NULL, NULL, '엘윈 숲의 황금골에 있는 치안대장 더그한에게 가야 합니다.', NULL),
(63, '물의 부름', '공동묘지 서쪽, 은빛소나무 숲의 해변을 따라가다 보면 역병 때문에 황폐해진 제단이 있을 거예요. 그곳 정령들은 이제 우리 종족과 말도 섞지 않는답니다. 타락한 하급 물의 현신을 해치우고 연못을 정화하는 것이 당신의 임무예요.$B$B그 정령에게 얻은 현신의 팔보호구와 브린이 만들어준 물병에 남아 있는 순수한 물을 가져가서 화로 위에 올려놓으세요. 그러면 하급 물의 현신을 소환해 정화할 수 있을 거예요.$B$B임무를 완수하면 그 증거를 가져오세요. 그러면 답례로 토템을 드리죠.', '은빛소나무 숲에서 타락한 하급 물의 현신을 처치하고 영원의 샘 제단 위에 타락한 현신의 팔보호구와 얼마 남지 않은 순수한 물을 함께 올려놓아야 합니다.', NULL, '은빛소나무의 숲 북부 해안가에 있는 영원의 샘 제단으로 가야 합니다.', NULL),
(64, NULL, NULL, NULL, NULL, '서부 몰락지대의 얀센 농장에 있는 농부 펄브라우에게 가야 합니다.', NULL),
(66, '스탈반의 전설', '내 손녀 알리사가 큰 위험에 처해 있다는 끔찍하고 불길한 기운을 느꼈네. 그래서 카드로 점을 쳐 보았더니 죽음이 보였어.$B$B난 오랫동안 어두운 최면 상태에 빠져 있다가 이 끔찍한 수수께끼의 단서를 얻을 수 있었다네. 이름이 떠올랐어, 스탈반이라는 이름이 말이야.$B$B마을회관에서 서기관을 찾아서 이 스탈반이라는 인물에 대해 좀 더 알아보도록 하게. 우리 모두의 운명이 위태로워.', '어둠골 마을회관에서 서기관 달트리를 찾아야 합니다.', NULL, NULL, NULL),
(68, '스탈반의 전설', '낡은 트렁크 안에서 먼지투성이의 부치지 않은 편지를 발견했습니다.', '어둠골에 있는 서기관 달트리에게 먼지투성이의 부치지 않은 편지를 가져가야 합니다.', NULL, NULL, NULL),
(70, '스탈반의 전설', '아! 스탈반이라는 이름이 이제야 생각나는군요.$B$B오래전 폭풍이 몰아치던 날 밤에 전령이 와서는 하룻밤 묵을 곳을 찾았었지요. 그런데 자정이 거의 다 되었을 때쯤 그 사람이 비명을 지르며 계단을 뛰어 내려왔답니다. 얼굴은 두려움에 하얗게 질려 있었고 말입니다. 그리고 잠옷을 입은 채 폭우 속으로 사라졌어요.$B$B위층 상자 안에 편지도 그대로 둔 채로 말이에요. 그 뒤로 편지를 찾으러 오지도 않았고. 그 편지들 중 하나는 스탈반이라는 사람이 스톰윈드의 대운하로 보내는 것이었어요. 뭐, 원하신다면 편지를 가져가셔도 됩니다.', '상자에서 스탈반의 배달되지 않은 편지를 입수해 스톰윈드의 대운하에 있는 누군가에게 전해야 합니다.', NULL, '스톰윈드에 있는 관리인 폴좀과 대화해야 합니다.', NULL),
(72, '스탈반의 전설', '아버지는 내가 이 일을 맡기 훨씬 전에 토지 관리인이셨소. 아버지는 대학살이 있은 후 그 피비린내 나는 걸 다 치워야 했단 말이오. 하지만 그건 문제가 아니라오.$B$B플린트리지 신용조합의 마지막 자금이 바닥나 버렸었지. 이제는 가문의 마지막 재산까지 경매에 내놓아야 할 판이었소. 괘씸한 세금 도둑들 때문이지. 더 알고 싶은 게 있다면 저 뒤에 상자에 들어 있는 쓸모없는 것들이나 마음껏 살펴보시오. 뭐, 뭔가 알아내게 될지도 모를 일이니…', '뒤에 있는 짐 꾸러미에서 단서를 찾아야 합니다.', NULL, NULL, NULL),
(74, '스탈반의 전설', '상자 안에는 케케묵은 가족 유품들, 가족 초상화 하나, 사냥 트로피 몇 개, 낡은 책 몇 권 등 여러 가지 물건이 있습니다. 상자의 맨 아래쪽에 있는 도자기 항아리 밑에서 찢어진 일지 페이지를 발견합니다.', '발견한 찢어진 일지 페이지에 다음 단서가 들어 있습니다.', NULL, NULL, NULL),
(75, '스탈반의 전설', '내가 이곳으로 왔을 때 위층에 있는 상자 안에 양피지 문서 꾸러미가 있었다네. 처음 도착했을 때 그 문서들을 한번 보긴 했지만 눈이 어두워진 후로는 보려고 한 적이 없지.$B$B이 장님에 가까운 늙은이에겐 힘든 일이니, 직접 위층의 상자에서 스탈반이라는 자에 대해 더 알아보는 데 도움이 될 만한 것이 있나 찾아보게나. 젊은이에게 도움이 될 만한 색 바랜 일지 페이지가 있을 걸세. 그걸 가져오면 내가 할 수 있는 한 도와 주도록 하겠네.', '치안대장 해거드가 위층의 상자에서 색 바랜 일지 페이지를 가져다 달라고 했습니다.', NULL, '엘윈 숲의 동쪽계곡 벌목지에 있는 치안대장 해거드에게 가야 합니다.', NULL),
(76, NULL, NULL, NULL, NULL, '엘윈 숲의 황금골에 있는 치안대장 더그한에게 가야 합니다.', NULL),
(77, '까다로운 임무', '내게 드란 드로퍼스가 찾는 리플의 원래 포장 재료가 있소. 말톤 아버지는 맘에 안 들지만 그에게 줄 리플을 포장하는 걸 도와주겠소. 단 리플을 두 병 더 가져와 준다면 말이오. 굼벵이 바위굴 근처의 버려진 호드 기지에 가면 상자가 있는데 그 속에 리플이 들어 있소.$B$B아주 힘든 임무가 될 거요. 폐허에는 지독한 수액괴물들이 들러붙어 있거든. 소문을 듣자 하니 우두머리 수액괴물이 지배한다고 하오. 그거야 어쨌든 리플을 구해오면 포장을 해주리다.', '굼벵이 바위굴의 버려진 호드 기지 근처에서 상자에 든 동부 내륙지 벌꿀 리플 10병을 회수해야 합니다.', NULL, '동부 내륙지의 신디거의 야영지에 있는 길버라딘 선체이서에게 가야 합니다.', NULL),
(78, '스탈반의 전설', '자넬 도와줄 만한 사람을 알고 있네. 내가 스톰윈드 경비병을 지휘하던 시절에 우리는 어둠골에 있는 진홍 까마귀 선술집에서 술을 마시곤 했지. 선술집주인 스미츠는 그 지역에서 일어나는 일이라면 모르는 게 없었다네. 그에게 이 일지를 보여주고 뭔가 알고 있는지 물어보게나.', '그늘숲의 어둠골에 있는 선술집주인 스미츠에게 색 바랜 일지 페이지를 가져가야 합니다.', NULL, NULL, NULL),
(79, '스탈반의 전설', '난 지난 몇 년 동안 이 스탈반이라는 인물의 이야기를 추적해 다녔지요. 몇 년 전 귀족들이 학살당했을 당시에도 나는 해거드 씨와 함께 조사를 나갔답니다. 그때 이 낡은 보고서들을 찾았지만 이 필체가 숲 속의 그 미치광이의 것인 줄은 전혀 몰랐군요. 당신이 찾아낸 증거들이 그의 유죄를 입증한 셈입니다. 이걸 즉시 이본로크 사령관께 가져가 당신이 발견한 사실들을 알려 드리세요.', '사령관 알시아 이본로크에게 진흙투성이의 일지 페이지를 가져가야 합니다.', NULL, NULL, NULL),
(80, '스탈반의 전설', '난 오랫동안 그 스탈반이란 녀석을 주시해 왔소. 만약 이 일지를 녀석이 작성했다면 이로써 녀석의 죄가 분명히 입증되는 것이오.$B$B지금까지 마을 등기부를 관리해 오고 있는 서기관 달트리는 필체 감정 전문가의 수준이라고 할 수 있소. 그에게 이 일지를 보여 주고 이 필체가 등록된 서명의 필체와 일치하는지 확인해 보도록 하시오.', '서기관 달트리에게 피투성이의 일지 페이지를 보여 줘야 합니다.', NULL, NULL, NULL),
(81, '리플 배달', '드란에게 가져갈 리플을 술통에 안전하게 잘 담았는지, 또 그 사람이 부탁했던 병도 몇 개 따로 챙겨 뒀는지 한 번 더 확인했소. 드란을 좋아해서 한 일은 아니오. 소중한 리플이 흔들리면 맛이 없어지니까… 감사는 접어 두시오.$B$B자, 오그리마의 고물상에 있는 드란 드로퍼스에게 이 술통을 가져다주시오. 그리고 부탁이니, 나 대신 말톤에게 안부 좀 전해 주시오. 좋은 술을 준비해두었으니 술친구가 생각나면 언제든 주저 말고 찾아오라고 말이오.', '오그리마에 있는 드란 드로퍼스에게 술통을 가져가야 합니다.', NULL, NULL, NULL),
(82, NULL, NULL, NULL, NULL, '타나리스의 가젯잔에 있는 연금술사 페슬저그에게 가야 합니다.', NULL),
(83, NULL, NULL, NULL, NULL, '엘윈 숲의 동쪽계곡 벌목지에 있는 사라 팀버레인에게 가야 합니다.', NULL),
(86, NULL, NULL, NULL, NULL, '엘윈 숲의 스톤필드 농장에 있는 보모 버니스 스톤필드에게 가야 합니다.', NULL),
(87, NULL, NULL, NULL, NULL, '엘윈 숲의 스톤필드 농장에 있는 보모 버니스 스톤필드에게 가야 합니다.', NULL),
(88, NULL, NULL, NULL, NULL, '엘윈 숲의 스톤필드 농장에 있는 스톤필드 부인에게 가야 합니다.', NULL),
(89, NULL, NULL, NULL, NULL, '붉은마루 산맥의 호숫골에 있는 현장감독 오슬로에게 가야 합니다.', NULL),
(90, NULL, NULL, NULL, NULL, '그늘숲의 어둠골에 있는 주방장 그루얼에게 가야 합니다.', NULL),
(91, NULL, NULL, NULL, NULL, '붉은마루 산맥의 호숫골에 있는 집행관 코나처에게 가야 합니다.', NULL),
(92, NULL, NULL, NULL, NULL, '붉은마루 산맥의 호숫골에 있는 주방장 브리아나에게 가야 합니다.', NULL),
(93, '갈색 게살 케이크', '작은 비밀을 하나 알려 드릴까요? 갈색 게살 케이크는 사실 거미 다리로 만든 거랍니다! 좀 메스껍다는 건 알지만 톡 쏘는 맛이 훌륭하고 씹는 맛도 일품이거든요! 끈끈한 거미 다리를 가져다주시면 케이크를 몇 개 구워 드리도록 하죠.$B$B북쪽에 있는 언덕과 강 사이에 서식하는 그물독거미가 최고의 재료라고 합니다.', '끈끈한 거미 다리 6개를 모아 어둠골에 있는 주방장 그루얼에게 가져가야 합니다.', NULL, '그늘숲의 어둠골에 있는 주방장 그루얼에게 가야 합니다.', NULL),
(94, '감시의 눈동자', '내 경쟁자인 모건스라는 강력한 악의 마법사가 붉은마루 산맥의 일갈라의 탑에 살고 있다네. 난 아조라의 눈으로 그자를 몰래 감시할 수 있는 방법을 찾아내어 이제 멀리서도 그를 볼 수가 있게 되었네.$B$B그러나 그의 생각을 연구하려면… 도움이 좀 더 필요하다네.$B$B나를 도와 줄 생각이 있다면 내 아조라의 조각상을 일갈라의 탑으로 가져가 탑 근처의 오래된 사자상 위에 올려놓아 주게나.$B$B그게 끝나면 아조라의 힘은 모건스의 차후 계획을 예견해 줄 수 있을 걸세.', '아조라의 조각상을 붉은마루 산맥에 있는 일갈라의 탑 근처의 오래된 사자상으로 가져가야 합니다.', NULL, NULL, NULL),
(96, '물의 부름', '이 조각을 받게. 그리고 저들에게 생명을 주게.$B$B생명을 주고 깨닫게. 물은 곧 생명이요… 타락은 생명의 끝이라는 것을!$B$B자, 가서 물의 힘으로 생명을 보호하게.', '불모의 땅, 타이더스 계단에 있는 이슬렌 워터시어에게 물의 조각을 가져가야 합니다.', NULL, NULL, NULL),
(97, '스탈반의 전설', '필체가 일치한다는 사실을 즉시 이본로크 사령관께 전해 주십시오! 사령관님의 의혹이 사실로 밝혀졌다고요!', '사령관 이본로크 경에게 필체가 일치한다는 소식을 보고해야 합니다.', NULL, NULL, NULL),
(98, '스탈반의 전설', '스탈반 미스트맨틀은 타락한 삶을 살았소. 그자의 손에 선량한 사람들이 희생됐고, 그자가 수없이 많은 범죄를 저질렀다는 건 의심의 여지도 없지. 지금 이 미치광이가 어둠골을 위협하고 있지만 또 어떤 추악한 계획을 세우고 있는지는 아무도 모르오. $C. 마을 바로 북쪽에 있는 그의 오두막으로 가서 스탈반을 없애버리도록 하시오!$B$B그리고 임무를 완수한 후에는 에바 부인에게 가서 미스트맨틀 가문의 반지를 보여 주도록 하시오. 결국 그녀의 예지력 덕분에 이런 소름끼치는 사실을 밝혀낼 수 있었던 거니까 말이오. 그리고 그녀 덕분에 어둠골도 더 안전해졌소.', '스탈반 미스트맨틀을 처치하고 에바 부인에게 미스트맨틀 가문의 반지를 보여 줘야 합니다.', NULL, '그늘숲의 어둠골에 있는 에바 부인에게 가야 합니다.', NULL),
(99, NULL, NULL, NULL, NULL, '은빛소나무 숲의 공동묘지에 있는 달라 돈위버에게 가야 합니다.', NULL),
(100, '물의 부름', '주문을 다 외우자 눈부신 빛이 뿜어져 나옵니다. 물방울이 불꽃에 닿는 소리가 희미해지고 주위의 타락한 정령들이 죽어가면서 온몸의 감각이 마비되는 것 같습니다.', '은빛소나무 숲의 북부 해안가에 있는 하급 물의 현신과 대화해야 합니다.', NULL, NULL, NULL),
(101, NULL, NULL, NULL, NULL, '그늘숲의 어둠골에 있는 에바 부인에게 가야 합니다.', NULL),
(102, NULL, NULL, NULL, NULL, '서부 몰락지대의 감시의 언덕에 있는 정찰대장 다누빈에게 가야 합니다.', NULL),
(103, '불꽃을 지키는 자', '등대지기의 가족이 죽던 밤은 정말 끔찍했지. 내 눈앞에서 늙은 거먹눈 멀록이 공격을 주도하는데 나는 아무것도 하지 못하고 보고만 있었소. 후회하고 있지만 이미 엎질러진 물은 되돌릴 수 없으니 어쩌겠소. 지금은 대해를 항해 중인 선원들의 생명이 걱정이오. 배가 해안선의 거대한 암초에 너무 가까이 접근했소. 그리고 등대의 불꽃을 지키는 사람이 없으니 이제는 내가 그 책임을 져야 하오.$B$B내가 횃불을 밝힐 수 있도록 허수아비 괴물들을 처치하고 기름 주머니 5개를 구해다 주시오.', '서부 몰락지대 등대에 있는 선장 그레이슨에게 기름 주머니 5개를 가져가야 합니다.', NULL, '서부 몰락지대의 서부 몰락지대 등대에 있는 선장 그레이슨에게 가야 합니다.', NULL),
(104, '해안의 위협', '암초에 배가 침몰해 내 목숨을 잃었을 때는 죽은 후에도 이렇게 산 자들과 함께 지낼 수 있으리라고는 상상도 못했소. 내가 죽던 그날 밤 늙은 거먹눈 멀록이 등대지기의 가족들을 위협하여 쫓아내는 바람에 등대가 꺼져 있었지. 그들은 나중에 다시 돌아와 횃불을 밝혔지만 늙은 거먹눈 멀록이 약한 멀록들을 선동해 다시 등대를 습격하고 말았소. 등대지기의 가족들은 내 눈앞에서 힘없이 죽어갔지.$B$B해변에서 늙은 거먹눈 멀록을 보거든 처치해 버리고 놈의 비늘 하나를 내게 가져다주시면 내 보상하도록 하겠소.', '서부 몰락지대 등대에 있는 선장 그레이슨에게 늙은 거먹눈 멀록의 비늘을 가져가야 합니다.', NULL, '서부 몰락지대의 서부 몰락지대 등대에 있는 선장 그레이슨에게 가야 합니다.', NULL),
(105, NULL, NULL, NULL, NULL, '티리스팔 숲의 보루에 있는 고위집행관 데링턴에게 가야 합니다.', NULL),
(108, '[미완성] 신비한 보상', NULL, NULL, NULL, NULL, NULL),
(110, '곤충 기관 분석', '당분간 나는 슈섕크의 업무를 정리하고 또… 그의 측량 장비를 살펴보려고 하오. 어째선지 그 곤충들로 인해 더 피해를 보게 될 것 같군.$B$B연금술사 페슬저그에게 가서 내가 보냈던 곤충 기관을 조사했나 알아봐 주시오. 결과물이 준비됐으면 내게 가져와 주시오.', '가젯잔에 가서 연금술사 페슬저그를 만나 곤충 기관의 분석이 끝났는지 알아봐야 합니다.', NULL, NULL, NULL),
(112, NULL, NULL, NULL, NULL, '엘윈 숲의 황금골에 있는 윌리엄 페슬에게 가야 합니다.', NULL),
(113, '곤충 기관 분석', '즉시 이 보고서를 선임측량사 피즐도저에게 보여주어야 합니다. 사실… 글을 읽을 줄 아는 자라면 누구에게든 보여주어야 해요. 그만큼 도움의 손길이 절실한 중대사입니다. 이 심각한 위협은 그대로 방치할 경우 타나리스와 가젯잔뿐만 아니라 칼림도어 전체를 집어삼킬 거예요. 그게 다 뭐야, 아예 아제로스를 통째로 휩쓸어 버릴 수도 있어요. 그 세력은 사그라질 기미가 전혀 보이지 않으니까…$B$B피즐도저에게 이 보고서의 사본을 만들어 달라고 하세요. 그래서 모두에게 알려야 해요. 이 위협에 대해서는 모두 알아야만 합니다!', '가젯잔에 있는 선임측량사 피즐도저에게 곤충 분석 보고서를 가져가야 합니다. 연금술사 페슬저그가 요청한 대로 피즐도저로부터 보고서의 사본을 꼭 받아야 합니다.', NULL, NULL, NULL),
(115, NULL, NULL, NULL, NULL, '붉은마루 산맥의 호숫골에 있는 치안대장 매리스에게 가야 합니다.', NULL),
(116, NULL, NULL, NULL, NULL, '붉은마루 산맥의 호숫골에 있는 바텐더 다니엘스에게 가야 합니다.', NULL),
(117, NULL, NULL, NULL, NULL, '서부 몰락지대의 비수 언덕에 있는 그림부즈 썬더브루에게 가야 합니다.', NULL),
(119, '베르너에게 돌아가기', '좋습니다, 내 그에게 편자 50개를 주도록 하지요…$B$B자, 여기 상자에 넣어 포장했으니 가지고 가면 됩니다! 베르너에게 거래하게 되어 기쁘다는 말과 함께 꼭 상자에 붙여 놓은 쪽지를 읽으라고 전해주세요!', '붉은마루 산맥의 호숫골에 있는 베르너 오스구드에게 편자 상자를 전해야 합니다.', NULL, NULL, NULL),
(121, '스톰윈드로의 전갈', '내가 전하의 답변을 기다리는 동안 자네는 이 편지를 집정관 솔로몬에게 전달하게. $B$B자, 그럼 해산하도록!', '호숫골의 집정관 솔로몬에게 장군 마커스 조나단의 답장을 전달해야 합니다.', NULL, NULL, NULL),
(122, NULL, NULL, NULL, NULL, '붉은마루 산맥의 영원고요 호수에 있는 베르너 오스구드에게 가야 합니다.', NULL),
(124, NULL, NULL, NULL, NULL, '붉은마루 산맥의 호숫골에 있는 베르너 오스구드에게 가야 합니다.', NULL),
(125, NULL, NULL, NULL, NULL, '붉은마루 산맥의 영원고요 호수에 있는 현장감독 오슬로에게 가야 합니다.', NULL),
(126, NULL, NULL, NULL, NULL, '붉은마루 산맥의 영원고요 호수에 있는 베르너 오스구드에게 가야 합니다.', NULL),
(127, NULL, NULL, NULL, NULL, '붉은마루 산맥의 호숫골에 있는 항구주임 바렌에게 가야 합니다.', NULL),
(128, NULL, NULL, NULL, NULL, '붉은마루 산맥의 호숫골에 있는 경비병 하우에게 가야 합니다.', NULL),
(129, '공짜 점심', '제 부탁 하나 들어주시겠어요? 경비병 파커의 점심을 준비해 놓았는데 지금 순찰 중이에요. 파커는 키가 크고 강한 스톰윈드 경비병이니까 자기 몸을 지킬 수 있지만, 저같이 힘없는 마을 사람이 나가기엔 밖은 너무 위험하답니다.$B$B그러니까 이 점심을 저 대신 배달해 주고 오시면 점심 한 끼를 공짜로 대접할게요! 파커는 그늘숲으로 가는 도로를 따라 순찰하고 있을 겁니다.', '어둠골로 가는 도로를 순찰하고 있는 경비병 파커의 도시락을 가져가야 합니다.', NULL, NULL, NULL),
(131, '나팔수선화 배달', '자, 꽃다발이 완성됐어요. 특별히 제가 제일 좋아하는 나팔수선화로 만들었답니다!', '달시에게 나팔수선화 꽃다발을 가져가야 합니다.', NULL, NULL, NULL),
(133, '구울 허수아비', '마을에서 떨어진 외딴곳에 살고 있어 보호를 받을 수 없는데도 구울이나 언데드에게 잡아먹히지 않은 게 신기하지 않나! 사실 어제만 해도 뼈만 남은 시체 무리가 내 집 벽을 치는 소리가 들렸다네.$B$B구울을 퇴치할 수 있는 허수아비 같은 걸 만들어야겠어. 허수아비를 만들려면 구울 갈비뼈가 필요하네. 구울 갈비뼈는 굶주린 시체나 뼈만 남은 시체, 걸신들린 시체, 썩어버린 시체, 역병 걸린 시체 녀석들에게서 구할 수 있다네.$B$B날 위해 구울 갈비뼈를 구해다 준다면 사례를 하도록 하지.', '구울 갈비뼈 7개를 모아 통나무집에 있는 애버크롬비에게 가져가야 합니다.', NULL, '그늘숲의 까마귀 언덕 묘지에 있는 애버크롬비에게 가야 합니다.', NULL),
(134, NULL, NULL, NULL, NULL, '그늘숲의 까마귀 언덕 묘지에 있는 애버크롬비에게 가야 합니다.', NULL),
(135, '데피아즈 결사단', '와일리가 석공 길드에 대해서도 썼는데, 이게 무슨 의미일까? 뭐, 실수로 잘못 적은 것일 수도 있겠지만. 데피아즈단이 석공 길드와 관계가 있다고? 이에 대해 확실히 알 만한 사람은 스톰윈드 SI:7의 단장인 마티아스 쇼밖에 없네. 그에게 와일리의 쪽지를 보여 주고 아는 게 있는지 알아보게나. 쇼를 찾는 게 어렵다면, 구 시가지의 병영에 가보도록 하게나.', '스톰윈드에 있는 마티아스 쇼에게 와일리의 쪽지를 가져가야 합니다.', NULL, NULL, NULL),
(137, NULL, NULL, NULL, NULL, '스톰윈드의 영웅의 계곡에 있는 장군 마커스 조나단에게 가야 합니다.', NULL),
(138, '샌더스 선장의 숨겨진 보물', '보물의 단서에는 다음과 같이 쓰여 있습니다. ≪제법이군 그래, 친구! 이제 정동쪽을 향해 갈 차례요. 동쪽 절벽 위의 길을 따라 동쪽으로 가시오. 길가에서 낡은 굴뚝의 잔해를 발견하면 다음 단서가 들어 있는 낡은 통을 발견할 것이오.≫', '다음 단서를 얻기 위해 굴뚝 잔해 근처에서 낡은 통을 찾아야 합니다.', NULL, NULL, NULL),
(139, '샌더스 선장의 숨겨진 보물', '발견한 통을 살피던 중에 또 다른 양피지 문서를 발견했습니다. 여기에는 다음과 같이 적혀 있습니다. ≪이제 여기에서 북쪽으로 가야 하오. 해안 절벽의 외딴 풍차 옆에 있는 빈 단지가 보일 때까지 곧장 가도록 하시오. 단지를 잘 살펴보면 단서를 발견할 수 있을 것이오.≫', '다음 단서를 찾기 위해 풍차 옆에 있는 빈 단지를 살펴봐야 합니다.', NULL, NULL, NULL),
(140, '샌더스 선장의 숨겨진 보물', '그가 적어 놓은 대로, 낡은 단지 안 깊은 곳에 샌더스의 보물에 대한 또 다른 단서가 들어 있습니다. 잉크를 쏟은 자국이 있고 종이에서는 위스키 냄새가 나지만 다음과 같은 내용을 읽을 수 있습니다. ≪이제 내 위스키 단지를 찾았으니 보물도 거의 다 찾았다고 할 수 있소! 서쪽으로 간 다음 해변으로 내려가시오. 바다에 이르면 계속 앞으로 가시오! 보물 상자가 있는 섬이 보일 때까지 서쪽으로 계속 헤엄쳐 가시오.≫', '보물을 얻기 위해 샌더스 선장의 보물 상자를 찾아 열어야 합니다.', NULL, NULL, NULL),
(141, '데피아즈 결사단', '석공 길드는 에드윈 밴클리프라는 자가 운영하고 있네. 밴클리프는 1차 대전쟁 중 오크족이 파괴해 버린 스톰윈드의 재건을 책임졌던 인물이지. 재건 사업이 완료된 후, 밴클리프와 그의 동료는 자신들에 대한 왕의 대우에 강한 불만을 가지고 있었네. 이 사실만으로도 어느 정도 짐작이 가지.$B$B자세한 내용은 이 보고서에 썼으니 즉시 서부 몰락지대의 그라이언 스타우트맨틀 경께 전하게!', '서부 몰락지대의 그라이언 스타우트맨틀에게 쇼의 보고서를 가져가야 합니다.', NULL, NULL, NULL),
(142, NULL, NULL, NULL, NULL, '서부 몰락지대의 감시의 언덕에 있는 그라이언 스타우트맨틀에게 가야 합니다.', NULL),
(145, '어둠골로의 전갈', '염치없으나 다시 당신에게 도움을 청해야겠소. 이본로크 경에게 그늘숲의 정예 병력인 어둠의 순찰대를 파병하여 호숫골의 방어를 도와 달라는 탄원서를 작성하였소. 무엇보다도 이 서신을 그에게 빨리 전달하는 것이 중요하오. 한순간이라도 긴장의 끈을 놓지 마시오. 이본로크 경은 그늘숲의 중심에 있는 어둠골이라는 도시의 시장이오. 절대 길을 벗어나지 않도록 주의하시오.', '집정관 솔로몬이 어둠골에 있는 이본로크 경에게 탄원서를 전달해 달라고 했습니다.', NULL, NULL, NULL),
(147, NULL, NULL, NULL, NULL, '엘윈 숲의 동쪽계곡 벌목지에 있는 치안대장 맥크리에게 가야 합니다.', NULL),
(150, NULL, NULL, NULL, NULL, '붉은마루 산맥의 영원고요 호수에 있는 항구주임 바렌에게 가야 합니다.', NULL),
(151, NULL, NULL, NULL, NULL, '서부 몰락지대의 얀센 농장에 있는 베르나 펄브라우에게 가야 합니다.', NULL),
(152, NULL, NULL, NULL, NULL, '서부 몰락지대의 서부 몰락지대 등대에 있는 선장 그레이슨에게 가야 합니다.', NULL),
(153, NULL, NULL, NULL, NULL, '서부 몰락지대의 감시의 언덕에 있는 정찰병 갈리안에게 가야 합니다.', NULL),
(154, '유령의 빗 돌려주기', '싫어!!!!!$B$B자, 이 빗을 가지고 어서 가버려요!$B$B난 괴물일 뿐이야. 누구도 다시는 날 아름답다고 생각하지 않을 거야!', '어둠골의 에바 부인에게 유령의 머리빗을 가져가야 합니다.', NULL, NULL, NULL),
(155, '데피아즈 결사단', '그래, 스타우트맨틀이 나를 보호한답시고 당신같이 허약한 $R|1을;를; 보냈단 말이지? 쳇, 당신 잘하는 게 좋을 거요. 보아하니 친구들도 좀 더 부르는 게 좋을 거 같군.$B$B우리 거래에 대해서는 잘 알고 있겠지? 당신은 나를 지켜 주고, 나는 데피아즈단의 은신처로 당신을 안내하고. 데피아즈단이 내 목을 노리고 있으니 내게서 잠시라도 한눈팔면 안 되오, 명심하라고! 그들이 내가 당신과 같이 있는 걸 본다면 날 죽이려 들거요.$B$B당신과 친구들이 준비되면 알려 주시오.', '데피아즈 결사단의 비밀 은신처까지 데피아즈단 변절자를 호위해야 합니다. 데피아즈단의 변절자가 밴클리프와 그의 동료가 숨어 있는 곳까지 안내한 이후에 그라이언 스타우트맨틀에게 돌아가 그 위치를 알려야 합니다.', '데피아스 배신자를 호위하여 밴클리프가 어디에 숨어 있는지 알아내세요.', '서부 몰락지대의 감시의 언덕에 있는 그라이언 스타우트맨틀에게 가야 합니다.', NULL),
(156, NULL, NULL, NULL, NULL, '그늘숲의 어둠골에 있는 선술집주인 스미츠에게 가야 합니다.', NULL),
(160, '시장에게 보내는 편지', '이 편지를 어둠골의 시장인 엘로 이본로크에게 전하게.$B$B그와는 오랜 친구 사이지… 아, 그리고 이 편지를 전하면 자네가 날 위해 해준 일에 대해 나만큼이나 기뻐할 거야. 하하하하!', '어둠골의 시장 엘로 이본로크 경에게 엘로에게 보내는 편지를 전해야 합니다.', NULL, NULL, NULL),
(161, '어둠의 전조', '내 느낌이 맞는다면 이건 일종의 폭약 가루인 것 같군. 무엇인지 확실히 알아내려면 폭파 전문가에게 분석을 맡겨야 하네.$B$B이 일을 할 수 있는 사람은 한 명뿐이네. 애실런 스톤스머크라는 폭파전문가인데, 동쪽에 있는 모그로쉬 소굴에 있는 오우거들의 동태를 파악하는 임무를 맡았었지. 모그로쉬 소굴 쪽으로 가서 그를 찾아 이 가루의 성분이 무엇인지 자문을 좀 구해보게나.', '선임기술자 힌더바이르가 이상한 향기의 가루를 저습지의 모그로쉬 소굴에 있는 폭파 전문가 애실런 스톤스머크에게 전달해 달라고 했습니다.', NULL, NULL, NULL),
(162, '실리시드의 출현', '이 보고서는 이런 일에 대해 잘 아는 사람에게 가져다주는 게 좋겠소.$B$B그라시나 스피릿마이트라는 나이트 엘프 학자를 알고 있는데 그녀는 아제로스 생태계의 생물들을 연구하며 많은 시간을 보내고 있소. 게다가 역사학에도 해박하지. 이 위협이 정확히 무엇인지 알아내고 또 이걸 막을 방법을 알아내려면 그녀에게 이 보고서를 가져가 도움을 청하시오.$B$B내가 마지막으로 들은 소식으로는, 다르나서스에 있는 달의 신전에 산다고 합디다.', '다르나서스에 있는 그라시나 스피릿마이트에게 곤충 분석 보고서를 가져가야 합니다.', NULL, NULL, NULL),
(166, NULL, NULL, NULL, NULL, '서부 몰락지대의 감시의 언덕에 있는 그라이언 스타우트맨틀에게 가야 합니다.', NULL),
(167, NULL, NULL, NULL, NULL, '스톰윈드에 있는 빌더 시슬네틀에게 가야 합니다.', NULL),
(168, NULL, NULL, NULL, NULL, '스톰윈드에 있는 빌더 시슬네틀에게 가야 합니다.', NULL),
(169, NULL, NULL, NULL, NULL, '붉은마루 산맥의 호숫골에 있는 집정관 솔로몬에게 가야 합니다.', NULL),
(170, NULL, NULL, NULL, NULL, '던 모로의 눈마루 골짜기에 있는 발리르 프로스트해머에게 가야 합니다.', NULL),
(171, NULL, NULL, NULL, NULL, '스톰윈드에 있는 보육원 원장님 나이팅게일에게 가야 합니다.', NULL),
(173, NULL, NULL, NULL, NULL, '그늘숲의 어둠골에 있는 칼로에게 가야 합니다.', NULL),
(174, '별 관측', '나는 나의 노움 친구 코그가 별을 관측하는 장치를 만드는 작업을 도와 주기로 했다오. 이 장치가 완성되면 숲 속에서 일어나고 있는 심상치 않은 변화를 설명해 줄 진실을 알아낼 수 있을 것이오.$B$B코그의 설계도에 따르면 숙련된 기술자가 만든 청동관이 첫 번째 재료라고 하오. 내게 청동관을 하나 가져다주시오.', '어둠골의 빅토리 프리즘안트라스가 청동관을 가져다 달라고 했습니다.', NULL, '그늘숲의 어둠골에 있는 빅토리 프리즘안트라스에게 가야 합니다.', NULL),
(176, NULL, NULL, NULL, NULL, '엘윈 숲의 황금골에 있는 치안대장 더그한에게 가야 합니다.', NULL),
(177, NULL, NULL, NULL, NULL, '그늘숲의 어둠골에 있는 빅토리 프리즘안트라스에게 가야 합니다.', NULL),
(179, NULL, NULL, NULL, NULL, '던 모로의 눈마루 골짜기에 있는 스텐 스타우트암에게 가야 합니다.', NULL),
(180, NULL, NULL, NULL, NULL, '붉은마루 산맥의 호숫골에 있는 집정관 솔로몬에게 가야 합니다.', NULL),
(181, '별 관측', '이제 한 가지 재료만 더 있으면 장치가 완성되는군. 코그의 설계도에 따르면 마지막 재료로 렌즈 같은 것이 필요하다고 쓰여있소. 장치에 사용할 만큼 큰 렌즈를 하나 알고 있긴 한데, 손에 넣기가 쉽지 않을 것이오.$B$B그늘숲 남쪽에 있는 언덕에 짜르크불이라는 오우거가 살고 있다오. 짜르크불이 쓰고 있는 외눈안경을 렌즈로 사용하면 될 거 같은데… 내게 좀 가져다주지 않겠소?', '그늘숲 남쪽의 오우거 언덕에서 짜르크불을 찾아 오우거의 외눈안경을 어둠골에 있는 빅토리에게 가져가야 합니다.', NULL, '그늘숲의 어둠골에 있는 빅토리 프리즘안트라스에게 가야 합니다.', NULL),
(182, NULL, NULL, NULL, NULL, '던 모로에 있는 그렐린 화이트비어드에게 가야 합니다.', NULL),
(183, NULL, NULL, NULL, NULL, '던 모로의 눈마루 골짜기에 있는 탈린 킨아이에게 가야 합니다.', NULL),
(185, NULL, NULL, NULL, NULL, '북부 가시덤불의 네싱워리 원정대에 있는 아제크 루아크에게 가야 합니다.', NULL),
(186, NULL, NULL, NULL, NULL, '북부 가시덤불의 네싱워리 원정대에 있는 아제크 루아크에게 가야 합니다.', NULL),
(187, NULL, NULL, NULL, NULL, '북부 가시덤불의 네싱워리 원정대에 있는 아제크 루아크에게 가야 합니다.', NULL),
(188, NULL, NULL, NULL, NULL, '북부 가시덤불의 네싱워리 원정대에 있는 아제크 루아크에게 가야 합니다.', NULL),
(189, NULL, NULL, NULL, NULL, '가시덤불 골짜기의 무법항에 있는 케복에게 가야 합니다.', NULL),
(190, NULL, NULL, NULL, NULL, '북부 가시덤불 의 네싱워리 원정대에 있는 얼가딘 경에게 가야 합니다.', NULL),
(191, NULL, NULL, NULL, NULL, '북부 가시덤불의 네싱워리 원정대에 있는 얼가딘 경에게 가야 합니다.', NULL),
(192, NULL, NULL, NULL, NULL, '북부 가시덤불의 네싱워리 원정대에 있는 얼가딘 경에게 가야 합니다.', NULL),
(193, NULL, NULL, NULL, NULL, '북부 가시덤불의 네싱워리 원정대에 있는 얼가딘 경에게 가야 합니다.', NULL),
(194, NULL, NULL, NULL, NULL, '북부 가시덤불의 네싱워리 원정대에 있는 헤멧 네싱워리 2세에게 가야 합니다.', NULL),
(195, NULL, NULL, NULL, NULL, '북부 가시덤불의 네싱워리 원정대에 있는 헤멧 네싱워리 2세에게 가야 합니다.', NULL),
(196, NULL, NULL, NULL, NULL, '북부 가시덤불의 네싱워리 원정대에 있는 헤멧 네싱워리 2세에게 가야 합니다.', NULL),
(197, NULL, NULL, NULL, NULL, '북부 가시덤불의 네싱워리 원정대에 있는 헤멧 네싱워리 2세에게 가야 합니다.', NULL),
(198, '병사 토르센을 위한 보급품', '흠, 사실 당신에게 부탁할 일이 있긴 한데요. 저 북쪽에 있는 부관 도렌 님과 그의 부하들이 우리가 보내 줄 정기 보급품을 기다리고 있어요.$B$B트롤 녀석들의 공격 때문에 아직 보내지 못했는데 누군가 맡아 줄 이가 필요해요. 도렌 님의 야영지는 길을 따라 북서쪽으로 그늘숲에서 가시덤불 골짜기로 들어오는 입구에 있어요. 보급품을 병사 토르센에게 전해주세요. 만약 토르센이 야영지에 없다면 거기서 남쪽을 정찰하고 있을 거예요. 당신이 보급품을 가져다주면 그가 보급품을 관리할 거예요.$B$B실패할 경우에는 보급품을 모두 변상해야 한다는 사실을 잊지마세요.', '병사 토르센에게 고블린의 잡다한 보급품을 전달해야 합니다.', NULL, '가시덤불 골짜기의 병사 토르센에게 보고해야 합니다.', NULL),
(199, '어둠의 전조', '이상한 향기가 나는 가루의 견본을 얻었습니다.', '선임기술자 힌더바이르에게 돌아가 발견한 단서를 보여 줘야 합니다.', NULL, NULL, NULL),
(200, '사서 헤로드', '쿠르젠이 토르센의 비밀에 대해 알고 있다면 분명 우리 중에 첩자가 있는 거요. 반드시 이 비밀이 어떻게 새어 나갔는지 밝혀내야 하오!$B$B쿠르젠의 야영지 내에는 사서 헤로드라는 자가 토르센의 연락책이었소. 헤로드는 쿠르젠의 병참장교로서 쿠르젠 주둔지의 모든 운영 상황에 대해 알고 있소. 당신이 헤로드의 쪽지나 기록을 가져온다면 토르센이 발각된 경위를 알아낼 수 있을 거요.$B$B우리가 쿠르젠의 부대에 속해 있을 당시 그 사서의 사무실은 야영지 내의 유일한 2층짜리 건물의 맨 위층에 있었소. 헤로드의 기록은 아마 아직 거기에 있을 것이오.', '사서 헤로드의 기록을 찾아야 합니다.', NULL, '가시덤불 골짜기에서 사서 헤로드의 기록을 찾아야 합니다.', NULL),
(201, NULL, NULL, NULL, NULL, '가시덤불 골짜기의 무법항에 있는 크라젝에게 가야 합니다.', NULL),
(202, NULL, NULL, NULL, NULL, '가시덤불 골짜기의 반란군 야영지에 있는 부관 도렌에게 가야 합니다.', NULL),
(203, NULL, NULL, NULL, NULL, '가시덤불 골짜기의 반란군 야영지에 있는 하사관 요화에게 가야 합니다.', NULL),
(204, NULL, NULL, NULL, NULL, '가시덤불 골짜기의 반란군 야영지에 있는 하사관 요화에게 가야 합니다.', NULL),
(205, '트롤의 마법', '$g형제:자매;께서 입수한 전설들을 연구할 동안 사악한 트롤의 마법 도구를 모아 주셨으면 합니다. 남쪽 먼 곳에 두 번째 트롤 부족인 백골가루 부족의 땅으로 가십시오. 그리고 그들 부족의 의술사들과 비술사들에게서 백골가루 우상을 구해서 가져오도록 하시기 바랍니다.', '반란군 야영지에 있는 수사 니메츠에게 백골가루 우상 4개를 가져가야 합니다.', NULL, '가시덤불 골짜기의 반란군 야영지에 있는 수사 니메츠에게 가야 합니다.', NULL),
(206, '마이조스', '쿠르젠이 죽었을지 모르지만 그를 악의 세력으로 몰아넣은 자는 아직 살아 있습니다! 이번 연구를 통해 몇 가지 알아낸 것이 있는데 가시덤불 골짜기 동쪽 산 내의 오우거 소굴에 마이조스라는 오우거 마법사가 살고 있습니다. 마이조스는 정신을 지배하는 마법을 사용한다고 알려져 있는데, 나는 그 오우거가 쿠르젠을 타락시켰다고 확신하고 있습니다.$B$B마이조스를 살려두면 다른 이들에게까지 악한 영향력을 행사할 테고, 제2의 쿠르젠이 나타날 수도 있을 겁니다.$B$B그러니 녀석을 처치하고 녀석이 다른 이를 타락시키는 데 사용하는 마음의 눈을 가져오십시오.', '반란군 야영지에 있는 수사 니메츠에게 마음의 눈을 가져가야 합니다.', NULL, '가시덤불 골짜기의 반란군 야영지에 있는 수사 니메츠에게 가야 합니다.', NULL),
(207, NULL, NULL, NULL, NULL, '가시덤불 골짜기의 반란군 야영지에 있는 수사 니메츠에게 가야 합니다.', NULL),
(208, NULL, NULL, NULL, NULL, '북부 가시덤불의 네싱워리 원정대에 있는 헤멧 네싱워리 2세에게 가야 합니다.', NULL),
(209, NULL, NULL, NULL, NULL, '가시덤불 골짜기의 무법항에 있는 케복에게 가야 합니다.', NULL),
(210, NULL, NULL, NULL, NULL, '가시덤불 골짜기의 무법항에 있는 크라젝에게 보고해야 합니다.', NULL),
(211, '리치의 최후', '이제 안돌할을 공격해 그곳을 지배하는 리치를 몰아낼 때가 왔소!$B$B도시의 폐허 안쪽에 권력을 잡고 있는 소환사 아라즈라는 리치가 있소. 도시 가운데 유적들 주위에는 리치를 경호하는 스컬지들이 깔려 있고, 그의 직속 수행원들은 정말 위협적인 존재들이라오. 친구들을 많이 데리고 가야 그와 대등하게 맞설 기회를 잡을 수 있을 거요.$B$B$N, 가서 리치를 처치하고 그 증거로 아라즈의 성물함 조각을 가져오도록 하시오!', '서부 역병지대의 서리바람 야영지에 있는 사령관 아쉬람 발러피스트에게 아라즈의 성물함 조각을 가져가야 합니다.', NULL, '서부 역병지대의 서리바람 야영지에 있는 사령관 아쉬람 발러피스트에게 가야 합니다.', NULL),
(212, '식은 음식', '저의 가장 유명한 요리 중 하나는 라임 드레싱을 곁들인 얼린 바실리스크 요리입니다. 그런데 문제는… 바실리스크 고기는 신선하게 유지하는 것이 불가능한데 오늘 저녁 왕의 만찬에 이 요리를 올려야 한다는 겁니다!$B$B그러니까 얼음눈바실리스크를 죽이고 그 즉시 얼린 바실리스크 다리를 빨리 가져다주시면 왕의 만찬으로 보답하겠습니다!$B$B얼음눈바실리스크는 북서쪽 가시덤불 골짜기의 해변 모래 언덕을 따라 돌아다닌다고 합니다. 그러니까 여행을 좀 해야 할 겁니다. 서두르세요!', '얼음눈바실리스크를 처치하고 얼린 바실리스크 다리를 얻은 다음 고독한 은둔자 선술집에 있는 앵거스 스턴에게 가져가야 합니다.', NULL, '스톰윈드의 고독한 은둔자 선술집에 있는 앵거스 스턴에게 가야 합니다.', NULL),
(213, NULL, NULL, NULL, NULL, '가시덤불 골짜기의 무법항에 있는 케복에게 가야 합니다.', NULL),
(214, NULL, NULL, NULL, NULL, '서부 몰락지대에 있는 정찰병 리엘에게 가야 합니다.', NULL),
(215, '정글의 비밀', '날 구해 줘서 고맙습니다. 좀 의아해 보이는 모양인데 설명해 드리도록 하지요.$B$B도렌 부관님께서 내게 쿠르젠의 부대에 잠입하여 놈들을 염탐하고 반란군에게 꼭 필요한 정보를 가져오라고 명하셨습니다. 그래서 쿠르젠 주둔지에 침투해 들어갈 기회를 엿보다가 지금이 기회다 싶어 실행에 옮기고 있던 참이었습니다. 그런데 내가 또 잘못 생각했던 모양입니다. 다시 한번 구해 주어 고맙습니다.$B$B이 임무는 일급비밀이니 누구에게도 말해선 안 됩니다. 하지만 도렌 부관님을 만나 보면 설명해 주실 겁니다.', '반란군 야영지에 있는 부관 도렌과 대화해야 합니다.', NULL, '가시덤불 골짜기의 반란군 야영지에 있는 부관 도렌과 대화해야 합니다.', NULL),
(216, NULL, NULL, NULL, NULL, '잿빛 골짜기의 헬스크림 감시초소에 있는 카랑 아마카르에게 가야 합니다.', NULL),
(217, '결정적인 공격', '제 계획이 성공했어요. 모단 호수에 있는 트로그들은 그로머그라는 우두머리의 명령을 따르는 것 같아요. 그렇지만 이 녀석 옆에는 내셔와 브롤러라는 우수한 경호원 둘이 항상 붙어 다녀서 매우 철저하게 경호를 하고 있더군요.$B$B가능하다면 동굴 안에 있는 그로머그와 두 경비병의 암살 임무를 맡아 주세요. 어서 가세요! 저는 이것들을 풀어내고 곧 당신을 다시 만날게요.', '트로그의 우두머리인 그로머그와 그의 경호원인 내셔와 브롤러를 처치하고 텔사마에 있는 경비대장 루겔퍼스에게 보고해야 합니다.', NULL, NULL, NULL),
(218, NULL, NULL, NULL, NULL, '던 모로에 있는 그렐린 화이트비어드에게 가야 합니다.', NULL),
(219, '교전 중 실종', '드디어 얼라이언스 동지를 만나게 되었군!$B$B제발… 나 좀 도와 주게…$B$B사악한 오크들이 우리 연대를 제압하여 대부분의 병사들이 목숨을 잃었네. 난 머리에 큰 충격을 입고 그 자리에서 의식을 잃고 말았지. 깨어나니 이 동굴에 갇혀 있더군. 아직 상처가 심해 탈출할 수가 없다네. 제발… 날 좀 도와주게. $B$B어서 마을로 되돌아가 치료를 받아야 해… 제발… 자네가 유일한 희망일세…', '하사관 키샨이 붉은마루 산맥으로 돌아갈 수 있도록 보호해야 합니다.', '키샨 상병을 레드리지로 호송하십시오.', '붉은마루 산맥의 호숫골에 있는 치안대장 매리스에게 가야 합니다.', NULL),
(220, '물의 부름', '이슬렌이 한 가지 임무를 더 준 다음 토템을 상으로 줄 거예요. 그게 어떤 임무든 내가 주는 물병이 꼭 필요할 거예요.$B$B이제 그녀를 찾아가세요. 우린 언젠가 다시 만나게 될 거예요.', '불모의 땅, 타이더스 계단에 있는 이슬렌 워터시어에게 가득 찬 순수한 물을 가져가야 합니다.', NULL, NULL, NULL),
(221, NULL, NULL, NULL, NULL, '그늘숲의 어둠골에 있는 칼로에게 가야 합니다.', NULL),
(222, NULL, NULL, NULL, NULL, '그늘숲의 어둠골에 있는 칼로에게 가야 합니다.', NULL),
(223, '숲 속의 늑대인간', '여기 있습니다. 이 편지를 대장 카레빈께 가져가십시오.$B$B<재빨리 색 바랜 양피지 문서를 건네주는 칼로>$B$B당신 같은 사람이 몇 명만 더 있으면 수적으로 어둠의 순찰대를 능가할 수 있을 겁니다! 그러면 아마 지금 몇 안 되는 인원으로 힘겹게 수행하고 있는 이 임무를 수월하게 완수할 수 있을 것입니다.', '조나단 카레빈에게 칼로의 쪽지를 가져가야 합니다.', NULL, NULL, NULL),
(224, '왕국 수호', '폐하의 이름으로 수많은 병사들이 최전방에서 치열한 전투를 벌이고 있소. 게다가 트로그놈들이 틈만 보이면 굴을 파고 쏟아져 나오는 상황이오. 트로그는 이미 아이언포지의 안녕을 위협하는 심각한 골칫거리가 되었소이다.$B$B트로그의 위협을 막으려면 당신과 같은 용감한 모험가의 도움이 필요하다오. 가루바위 트로그 6마리와 가루바위 정찰병 6마리를 처치하고 돌아와 보고해 주시오. 트로그들은 남쪽에 산으로 들어가는 길 주변에서 찾을 수 있을 것이오.', '남쪽 경비탑의 산악경비대 코블플린트가 가루바위 트로그와 가루바위 정찰병을 각각 6마리씩 처치해 달라고 했습니다.', NULL, NULL, NULL),
(225, '오래된 무덤', '이 오래된 무덤의 비석에는 다음과 같은 글이 새겨져 있습니다.$B$B모건 래디모어$B$B<좀 더 자세히 살펴보면 무덤 위의 흙이 최근 파헤쳐졌으며 상당한 양의 흙이 옮겨졌다는 사실을 확인할 수 있습니다…>', '어둠골의 시라 본인디와 대화해야 합니다.', NULL, NULL, NULL),
(226, NULL, NULL, NULL, NULL, '그늘숲의 고요의 강둑에 있는 라스에게 가야 합니다.', NULL),
(227, '모건 래디모어', '<책장 선반에서 가죽 표지의 책을 찾아내며>$B$B더 자세히 알고 싶다면 알시아님께 물어보십시오. 최근 그의… 문제를… 처리한 게 알시아님이니 말입니다.', '어둠골의 사령관 알시아 이본로크와 대화해야 합니다.', NULL, NULL, NULL),
(228, '모르라딤', '우리 정찰병의 보고에 따르면 모르라딤은 묘지 옆의 낯설고 굽은 길을 따라 그늘숲 여기저기를 돌아다니고 있다고 하오. 우린 그를 언덕 위의 집을 지나서 묻었는데, 당신 그 집이 어디 있는지 알고 있소?$B$B행운을 빌어 주는 것밖에는 내가 도울 수 있는 일이 없는 것 같군.', '모르라딤을 처치한 다음 그의 해골을 어둠골의 사령관 알시아 이본로크에게 가져가야 합니다.', NULL, '그늘숲의 어둠골에 있는 사령관 알시아 이본로크에게 가야 합니다.', NULL),
(229, '살아남은 딸', '전에 이 얘기도 했어야 했는데… 흠, 어떻게 얘기해야 하나…$B$B모건 래디모어는 자기 가족이 모두 죽었다고 생각했었는지 모르지만, 실은 사라 래디모어라고 그의 딸이 지금 순찰대원으로 일하고 있소. 그녀는 항상 아버지의 죽음…과 관련된 일들 때문에… 많은 어려움을 겪어 왔지. 그러니 당신이 가서 이 소식을 알려 주는 게 좋을 것 같소.', '어둠골의 순찰대원 사라 래디모어와 대화해야 합니다.', NULL, NULL, NULL),
(232, '연금술사 진게의 심부름', '왕립 연금술 학회에서 당신의 도움을 필요로 하고 있습니다. 내 계획대로라면 우리 둘 다 득을 볼 수 있을 것이니 잘 들으세요.$B$B옆방에 있는 연금술사 키버는 좀… 정신이 이상…할진 몰라도 그의 연구는 똑똑한 연구자의 손에 맡기면 좋은 결과를 얻을 수 있을 겁니다. 다행히도 내가 바로 그런 연구자랍니다. 이 구입주문서를 푸른달 골동품점의 주인, 알렉산드로 루카에게 가져다주세요. 그러면 그가 분석 도구를 하나 줄 것이니 그걸 받으면 내게 가져오세요. 그러면 그때 당신의 임무를 더 자세히 설명해 주도록 하겠습니다.', '언더시티에 있는 알렉산드로 루카에게 진게의 구입주문서를 가져가야 합니다.', NULL, NULL, NULL),
(233, '눈마루 골짜기 편지 배달', '흠… 이 부탁을 들어줄지는 모르겠지만. 시간이 없어서 오늘 들어온 편지 뭉치를 배달 못했네.$B$B어디 보자, 받는 사람이 탈린 킨아이 앞으로 되어 있군. 탈린 킨아이는 여기서 서쪽 길을 따라 내려가다 보면 나오는 얼어붙은 호수 옆에서 야영을 하고 있을 걸세.$B$B나 대신 편지를 좀 배달해주겠나?', '눈마루 골짜기에 있는 탈린 킨아이에게 편지 뭉치를 전달해야 합니다.', NULL, NULL, NULL),
(236, NULL, NULL, NULL, NULL, '겨울손아귀 호수에 있는 공성 전문가 스타우트핸들에게 가야 합니다.', NULL),
(237, NULL, NULL, NULL, NULL, '모단 호수의 왕의 계곡에 있는 산악경비대 그래블고에게 가야 합니다.', NULL),
(238, '연금술사 진게의 심부름', '자, 분석 도구가 준비되었소이다. 분명 연금술사 진게님께서는 최대한 빨리 이걸 받고 싶어하실 것이오. 지체하지 말고 어서 가져다 드리고 이 도구의 비용은 학회의 계산서에 첨부하겠다고 전해 주시오. 아, 내 안부도 함께 전해 주구려.$B$B자, 거기 그냥 그렇게 서 있지 말고 어서 가시오. 심부름꾼의 삶이란 항상 움직여 다녀야 하는 것 아니겠소?', '언더시티에 있는 연금술사 진게에게 휴대용 분석 도구를 가져가야 합니다.', NULL, NULL, NULL),
(242, '<미사용>', '트롬카, $C 친구. 지체하고 있을 시간이 없네. 용아귀 오크들이 여기로부터 남쪽에 있는 계곡에 진을 치고 있다네.$B$B녀석들은 대족장님의 명을 어겼기 때문에 우리에게는 선택의 여지가 없네. 더는 호드의 이름에 먹칠을 하지 못하도록 녀석들을 제거하는 수밖에.', '용아귀 약탈자 8명, 용아귀 해골감시자 3명, 그리고 용아귀 지휘관 1명을 처치해야 합니다.', NULL, '[미사용] 트루엑에게 가야 합니다.', NULL),
(244, '놀 침략자', '안녕하십니까. 전 이 도로를 순찰하는 임무를 맡고 있습니다. 아직까진 별 탈 없었는데 며칠 전 북쪽과 동쪽에서 놀 야영지를 목격했습니다.$B$B놀이 병력을 소집하고 있다는 것을 호숫골에 알려야 합니다! 호숫골의 펠던님께 이 사실을 보고해 주시기 바랍니다. 대의원님께서 정찰병 임금 정도는 지급해 주실 테니 걱정하지 마시고요.$B$B펠턴님은 주로 호숫골 다리의 남쪽 지역을 순찰하고 계십니다.', '붉은마루 산맥의 호숫골 남쪽 다리에 있는 부관 펠던에게 보고해야 합니다.', NULL, NULL, NULL),
(245, '거미의 위협', '안녕하십니까, $C|1이여;여;. 서쪽 변방에 들끓는 거미들을 본 적 있습니까? 우리만으로 다리 여덟 달린 그 괴물들을 처치하기에는 버겁지만 그렇다고 해서 어둠골에서 멀리 떨어진 이곳까지 지원군을 보내기에는 사령관님께서 지휘하시는 병력이 턱없이 부족합니다.$B$B이런 부탁을 해서 미안하지만, 놈들을 좀 처치해 주지 않으시겠습니까? 큰 보상을 약속할 수는 없지만, 그 고약한 벌레들을 처리해 준다면 사례는 분명히 밝히도록 하겠습니다.$B$B아, 그리고 한 가지 충고하지요. 녀석들의 독액을 조심하시기 바랍니다.', '새끼 그물독거미 15마리를 처치한 후 그늘숲에 있는 순찰대원 도즈에게 보고해야 합니다.', NULL, '그늘숲에 있는 순찰대원 도즈에게 가야 합니다.', NULL),
(246, NULL, NULL, NULL, NULL, '붉은마루 산맥의 호숫골에 있는 부관 펠던에게 가야 합니다.', NULL),
(247, '사냥 대성공', NULL, NULL, NULL, NULL, NULL),
(249, NULL, NULL, NULL, NULL, '엘윈 숲의 아조라의 탑에 있는 테오크리투스에게 가야 합니다.', NULL),
(250, '어둠의 전조', '우리 댐의 안전을 걱정해 주는 이가 있다니 얼마나 반가운지 모르겠네. 처음엔 탄돌 교각이 파괴되더니 다음엔 던 모드르가 약탈당하고… 검은무쇠 드워프의 다음 목표는 분명 댐일 거야. 불행히도 내 상관인 감독관님을 포함해서 방어 병력 대부분이 얼라이언스 최전선에 배치되어 있는 상황이네.$B$B그래서 자네의 도움이 절실히 필요해. 며칠 전 검은무쇠 공병들이 댐의 동쪽 사면을 굴착하는 것을 보았네. 그 지역을 정찰하고 뭔가 수상한 것이 있으면 가져다주게.', '댐의 동쪽 사면 근처를 정찰하고 검은무쇠 드워프의 음모를 밝힐만한 단서를 찾아 선임기술자 힌더바이르에게 가져가야 합니다.', NULL, NULL, NULL),
(251, '애버크롬비의 편지 번역', '자네가 가져온 이 편지를 시라 본인디에게 가져가게. 그는 고대 언어와 예술에 능통한 친구지. 이 마을에서 이걸 번역할 수 있는 사람이 있다면 그 뿐일 걸세.', '시라 본인디에게 엘로에게 보내는 편지를 가져가야 합니다.', NULL, NULL, NULL),
(252, '엘로 이본로크 경에게 편지 전달', '오, 이런! 이 편지에 쓰인 내용이 사실이라면 애버크롬비가 뭔가 대단히 사악한 짓을 저지른 게 틀림없습니다.$B$B이 번역된 편지를 서둘러 시장님께 전해주시기 바랍니다. 벌써 우리 마을에 불길한 기운이 찾아드는 것 같으니 서두르세요!', '엘로 이본로크 경에게 번역된 편지를 가져가야 합니다.', NULL, NULL, NULL),
(253, '장의사의 신부', '아이들 사이에서 전해지는 이야기에는 장의사라는 인물이 등장하네. 그는 원래는 착한 연금술사였지만 아내 엘리자가 죽자 미쳐 버렸지. 그는 아내를 부활시키기 위해 흑마법을 사용하여 자기 심장을 죽은 아내의 몸에 넣었다네.$B$B엘리자가 되살아나긴 했지만… 장의사는 저주를 받아 인육에 굶주려 하는 그녀를 다시 묻을 수밖에 없었다네.$B$B그의 심장은 곧 그의 힘이지. 장의사의 아내 무덤에서 심장을 찾아 박동이 멎기 전에 내게 가져오게. 그러면 그의 힘을 빼앗을 수 있을 걸세.', '엘리자의 무덤을 찾아 그녀의 몸에서 장의사의 심장을 찾아 엘로 이본로크 경에게 가져가야 합니다.', NULL, '그늘숲의 어둠골에 있는 엘로 이본로크 경에게 가야 합니다.', NULL),
(254, '무덤 파기', NULL, NULL, NULL, NULL, NULL),
(256, NULL, NULL, NULL, NULL, '모단 호수에 있는 집정관 블런트노즈에게 가야 합니다.', NULL),
(257, '사냥꾼의 허세', '당신이 이 용감한 다릴만큼 뛰어나다고 생각하나요? 어림없는 소리! 뭐, 그래도 도전은 언제나 환영이랍니다. 자, 그럼 내기 하나 할까요? 결국 당신이 능력 부족이라는 사실만 확인하게 되겠지만 말이죠. 실패하더라도 너무 상심하진 말아요.$B$B이곳 모단 호수 지역엔 대머리수리 떼가 둥지를 틀고 있죠. 그걸 몇 마리 잡아와 보시는 게 어떨까요? 당신이 성공한다면 제 활이나 총을 드리죠.$B$B<거만하게 쳐다보는 다릴>$B$B뭐, 당신이 손해 볼 건 없겠죠?', '산악대머리수리 8마리를 처치한 후 원정순찰대 오두막에 있는 풋내기 다릴에게 가야 합니다.', NULL, NULL, NULL),
(258, '사냥꾼의 도전', '또? 보아하니 첫 번째 도전을 통과했다고 신이 난 모양이군요. 하지만 그건 자랑삼아 떠벌릴 일도 못됩니다.$B$B그럼 이번엔 산돼지 사냥을 한번 맡겨보도록 하겠습니다. 눈마루 골짜기 멧돼지와는 차원이 다를 테니 조심하는 게 좋을 겁니다.$B$B실패하더라도 너무 상심할 필요는 없습니다. 행여나 성공해 돌아오면 입고 있는 셔츠라도 벗어 드릴 수 있습니다.$B$B제 몸에 난 이 상처에 대해 얘기한 적 있던가요? 2년 전이었는데…', '덩치 큰 산돼지 10마리를 처치한 후 원정순찰대 오두막에 있는 풋내기 다릴에게 가야 합니다.', NULL, NULL, NULL),
(259, '[미사용]', NULL, NULL, NULL, NULL, NULL),
(260, '<미사용>', '이런 얘기를 하면 틀림없이 자네도 다른 이들처럼 내가 터무니없는 전설에 집착하는 미치광이라고 생각할 게야. 사람들이 뭐라고 하는지 나도 다 아니까 부인하지 않아도 되네. 오래된 드워프 전설에 의하면 모단 호수 깊은 곳에 거대한 괴물이 산다고 하네. 나는 오랜 세월 동안 녀석을 추적하기 위해 노력했고 마침내 거의 찾을 뻔했었지만 안타깝게도 이젠 나이가 너무 들어 버린 것 같네, 허허. 모단 호수에서 그 괴물을 사냥해 볼 생각이 있으면 내게 트레샤돈 이빨과 발톱을 좀 가져오게나.$B$B<토마신이 신비스럽게 미소 짓습니다.>', '트레샤돈 이빨 5개와 트레샤돈 발톱 5개를 모아 켈트 토마신에게 가져가야 합니다.', NULL, '모단 호수에 있는 켈트 토마신에게 가야 합니다.', NULL),
(261, NULL, NULL, NULL, NULL, '잊혀진 땅의 나이젤의 야영지에 있는 수사 안톤에게 가야 합니다.', NULL),
(263, '왕국 수호', '많은 산악경비원들이 당신을 매우 실력 있는 친구라고 칭찬하더군. 여긴 당신과 같은 용감한 $R|1이;가; 절실히 필요하다오. 예비 사단은 전방으로 배치되어 가고 여긴 우리뿐이라오. 그러니 트로그를 상대로 한 싸움은 나아질 기미도 보이지 않을 수밖에… 하지만 이제 자네 같은 유능한 $C|1이;가; 왔으니 실력을 보여 주시오.$B$B가서 가루바위 주술사 8마리와 가루바위 뼈다귀싸움꾼 8마리를 처치해주시오. 남쪽에 있는 산의 동굴 주변에서 그들을 찾을 수 있을 것이오. 어디, 명성이 사실인지 한번 보도록 하겠소. 트로그 사냥꾼.', '남쪽 경비탑의 산악경비대 월뱅이 가루바위 주술사 8명과 가루바위 뼈다귀싸움꾼 8명을 처치해 달라고 했습니다.', NULL, NULL, NULL),
(265, '계속되는 조사', '자, 이 책을 도로 가져가게. 그대가 꼭 그 사람을 찾게 되길 빌어 줌세. 다른 마을 주민에게 물어보면 또 다른 단서를 얻을지도 몰라.$B$B그리고 한 가지 더… 이 책을 쓴 사람은 어둠골 외부 사람이지만 책 자체는 이곳에서 구입한 것이야.', '다른 마을 주민에게서 의문의 남자에 대한 정보를 알아봐야 합니다.', NULL, NULL, NULL),
(266, '여관에서의 조사', '자, 책 여기 있습니다. 그리고 조사가 잘 이뤄지길 바랍니다.$B$B여관에 가서 더 알아보는 건 어떻습니까? 당신이 찾는 사람이 이 마을에서 지냈다면 누군가 여관에서 그를 보았을 가능성이 있을 테니까 말입니다.', '여관에서 의문의 남자에 대한 정보를 얻어야 합니다.', NULL, NULL, NULL),
(267, '트로그의 위협', '당신도 지금 트로그가 드워프의 땅에 위협이 되고 있다는 것을 알고 있겠지요? 현재 아이언포지 예비 사단이 얼라이언스 최전선에 배치된 상황이라 이 지역을 방어할 병력이 부족한 상태입니다. 제가 지휘하는 연대는 이 마을을 지키는 것이 임무라, 언덕에 숨어있는 저 괘씸한 트로그놈들을 처리하고 싶어도 섣불리 나설 수 없는 노릇이지요.$B$B저 괘씸한 트로그놈들을 처리해야겠는데… 당신이 이번 임무를 맡아서 트로그놈들에게 뜨거운 맛을 보여주시겠습니까? 그리고 증거물로 트로그의 단단한 이빨 8개를 가지고 오십시오.', '남쪽 경비탑에 있는 경비대장 루겔퍼스에게 트로그의 단단한 이빨 8개를 가져가야 합니다.', NULL, NULL, NULL),
(268, '스벤에게 돌아가기', '당신이 발견한 건 반밖에 못 쓴 겁니다. 스벤의 농장에서 도망칠 때 두고 올 수밖에 없어서…$B$B자, 이 완성된 일지를 스벤에게 가져다주시기 바랍니다. 그의 농장에서 일어난 일을 전부 다 기록해 놓았습니다.$B$B이 일지가 지난 몇 주 동안 나와 함께한 유일한 친구였지만, 이 책을 포기해야만 분노에 눈먼 스벤과 마주치는 것을 피할 수 있다면 두말할 필요 없이 내놓도록 하죠!', '완성된 지터스의 일지를 가지고 스벤에게 가야 합니다.', NULL, NULL, NULL),
(269, '지혜의 추구', '스톰윈드로 가서 빛의 대성당에 있는 파딩 주교님과 대화해 보시기 바랍니다. 그분께 지터스의 일지를 보여 주고 모벤트 펠을 상대하겠다고 얘기하십시오.$B$B스톰윈드는 어둠골을 저버렸지만 주교께서는 인도적이고 매우 지혜로운 분이시니 당신이 우리를 구할 수 있도록 도와 주실 겁니다.$B$B당신의 임무는 위험천만하지만 서둘러 주시기 바랍니다. 시간이 지날수록 그늘숲의 그림자는 점점 커져 가고 있습니다.', '스톰윈드에 있는 주교 파딩에게 완성된 지터스의 일지를 보여 줘야 합니다.', NULL, NULL, NULL),
(272, NULL, NULL, NULL, NULL, '달숲의 밤의 안식처에 있는 덴드리트 스타블레이즈에게 가야 합니다.', NULL),
(273, NULL, NULL, NULL, NULL, '모단 호수의 대호수에 있는 훌다르와 대화해야 합니다.', NULL),
(274, '어둠의 전조', '자, 너무 늦기 전에 힌더바이르에게 이 혼합물을 가져가시오. 검은무쇠 놈들은 일을 늦출 생각이 없으니, 우리도 빨리 움직여야 하오.', '애실런 스톤스머크가 모단 호수에 있는 선임기술자 힌더바이르에게 중화 혼합물을 전해 달라고 했습니다.', NULL, NULL, NULL),
(275, NULL, NULL, NULL, NULL, '저습지의 녹지대에 있는 신록수호자 레시엘에게 가야 합니다.', NULL),
(276, '파괴의 손길', '이끼가죽 놀들은 저습지에서 오랫동안 평화롭게 지내왔지만 요즘 그 수가 너무 늘어나고 있다. 이들은 늪의 덤불과 꽃들을 짓밟고 그 고약한 도끼로 수없이 많은 나무를 땔감으로 베어내고 있다.$B$B그 놀은 더 이상 이 땅과 조화를 이루지 못하고 있으니 저습지를 지키려면 놀의 숫자를 줄여야만 할 것이다.$B$B이끼가죽 놀 15마리와 이끼가죽 싸움꾼 10마리를 처치하라. 남쪽에 있는 알가즈라는 드워프 관문 근처에 놈들이 있을 것이다. 임무를 완수하고 내게 돌아오너라.', '이끼가죽 놀 15마리와 이끼가죽 싸움꾼 10마리를 처치한 다음 저습지에 있는 신록수호자 레시엘에게 가야 합니다.', NULL, '저습지의 녹지대에 있는 신록수호자 레시엘에게 가야 합니다.', NULL),
(277, '화재 예방', '이끼가죽 놀들이 저습지의 나무를 베어 불을 지피는 데 사용하고 있다. 이제 더 이상 두고 볼 수만은 없는 일!$B$B이끼가죽 놀들이 불을 붙이는 데 사용하는 조잡한 부싯돌을 빼앗아 오라. 이끼가죽 놀과 이끼가죽 싸움꾼을 제외한 모든 이끼가죽 일족이 부싯돌을 지니고 있다.', '신록수호자 레시엘에게 조잡한 부싯돌 9개를 가져가야 합니다.', NULL, '저습지의 녹지대에 있는 신록수호자 레시엘에게 가야 합니다.', NULL),
(279, NULL, NULL, NULL, NULL, '저습지의 메네실 항구에 있는 칼 보란에게 가야 합니다.', NULL),
(280, '어둠의 전조', '오늘 검은무쇠 폭도들이 큰 통을 가지고 댐 쪽으로 헤엄쳐 가는 걸 목격했네. 이른 아침이라 그들을 막을 산악경비원은 아무도 없었어! 놈들이 댐 밑바닥에 시포리움을 설치한 건 아닌지 걱정되는군. 만약 그랬다면 곧 폭발할지도 몰라.$B$B너무 늦기 전에 이 혼합물을 놈들이 가져다 놓은 통 안의 것과 섞어야 하네. 서둘러야 해!', '선임기술자 힌더바이르가 댐 밑바닥으로 헤엄쳐 가서 화약통에 중화 혼합물을 넣어 섞어 달라고 했습니다.', NULL, NULL, NULL),
(281, '뱃짐 되찾기', '얼마 전에 상선 눈먼 공주호가 멀록의 습격을 받았습니다. 다행히 배는 무사했지만 놈들이 이 배에 실려 있던 짐을 강탈해 가 버렸습니다. 그 뱃짐 중에는 귀중한 테레나스 메네실의 조각상도 있습니다. 그 조각상을 좀 되찾아 주십시오.$B$B해안가의 멀록 소굴에서 상자나 통 등 잃어버린 짐으로 보이는 것들을 찾아보고, 그 조각상을 찾으면 내게 가져오시기 바랍니다.', '해안가의 멀록 소굴에서 상자와 통을 찾아야 합니다.', NULL, NULL, NULL),
(282, '그렐린의 보고서', '원래는 수습생을 시켜 세니르 형에게 보고서를 전달하려 했는데 좀 더 믿음직한 사람이 좋을 것 같아서 말입니다. 당신한테 부탁해도 될까요?$B$B흠, 카라노스로 가려면 앤빌마 동쪽에 있는 터널을 가로질러 가야 합니다… 터널 입구에 가면 산악경비대원인 탈로스가 있을 테니 그와 얘기를 나눠 보십시오. 아마 지금쯤 터널 안엔 트로그들이 잔뜩 진을 치고 있을 겁니다. $B$B앤빌마로 가다가 동쪽 방향의 길을 따라 가면 터널이 나올 겁니다. 탈로스는 그 입구 근처에 있을 겁니다.', '산악경비대 탈로스와 대화해야 합니다.', NULL, NULL, NULL),
(283, '어둠의 전조', '통에서 작은 소리가 납니다.', '중화 혼합물의 효과가 나타나는 것 같습니다. 선임기술자 힌더바이르에게 돌아가 이 기쁜 소식을 알려 줘야 합니다.', NULL, NULL, NULL),
(284, '계속되는 수색', '멀록의 소굴을 계속 뒤져 나가지만 메네실 조각상의 흔적은 보이지 않습니다.$B$B북쪽과 북동쪽에 있는 근처의 멀록 소굴 두 곳 중 한 곳에 단서가 있을지도 모릅니다.', '메네실 조각상을 찾아야 합니다.', NULL, NULL, NULL),
(285, '다른 소굴 수색', '이 멀록 소굴을 샅샅이 조사했지만 아무것도 발견하지 못했습니다.$B$B하지만 다음에 찾게 될 단서는 매우 유용할 것이라고 확신합니다.$B$B북쪽에 있는 소굴 중 하나에는 반드시 메네실 조각상이 있을 것입니다!', '멀록 소굴에서 메네실 조각상을 계속 찾아봐야 합니다.', NULL, NULL, NULL),
(286, '조각상 돌려주기', '흙 속에서 통을 꺼내 열자 깨끗한 지푸라기에 쌓여 있는 은빛 조각상이 나옵니다. 조각상은 해머를 높이 들고 있는 긴 머리의 젊은 성기사의 모습입니다.$B$B이것은 메네실 조각상이 분명합니다! 이제 메네실 항구의 칼 보란에게 돌아가야 합니다.', '저습지의 메네실 항구에 있는 칼 보란에게 메네실 조각상을 가져가야 합니다.', NULL, NULL, NULL),
(287, NULL, NULL, NULL, NULL, '카라노스에 있는 세니르 화이트비어드에게 가야 합니다.', NULL),
(288, '제 3함대', '난 쿨 티라스 제 3함대의 주력함이었던 파도의 여왕호의 일등항해사였지. 마지막 항해에서 붉은용들의 공격을 받아 전멸하고 말았던 비운의 함대 말이야. 함대를 공격한 그 용들은 오크 놈들이 조종하는 거였어!$B$B용이 뿜어내는 불기운을 버틸 재간이 없었던 함대는 결국 불탄 채로 난파되어 이 해안으로 떠내려 오게 된 거지. 전 함대를 통틀어 내가 유일한 생존자야.$B$B아, 그 생각을 하니 또 머리가 지끈거리는군! 마음을 달래고 얘기를 계속하려면 술을 한 잔 더 걸쳐야겠어.', '일등항해사 피츠시몬즈에게 벌꿀술을 한 병 사 줘야 합니다.', NULL, '저습지의 메네실 항구에 있는 일등항해사 피츠시몬즈에게 가야 합니다.', NULL),
(289, NULL, NULL, NULL, NULL, '저습지의 메네실 항구에 있는 일등항해사 피츠시몬즈에게 가야 합니다.', NULL),
(290, '저주 풀기', '내 동료의 저주를 풀고 그들을 모두 자유롭게 하려면 바로 그… 그것… 우리 배에 실었던 그걸 찾아내서 정화해야 해! 그게 무엇인지는 모르지만 할린도르 선장이 애지중지하던 금고에 안전하게 보관되어 있었어.$B$B난파된 용감무쌍호에 떠도는 우리 늙은 선장이 계속 꿈에 나타나고 있어. 그에게서 열쇠를 찾아내 용감무쌍호의 금고를 좀 열어 줘.$B$B그리고 그 저주받은 물건을 꺼내서 마을에 있는 사제, 글로린 스틸브라우에게 가져다줬으면 해.', '할린도르 선장을 처치한 후 용감무쌍호의 금고 열쇠를 구해야 합니다.그 열쇠를 사용하여 용감무쌍호의 잠긴 금고를 열어야 합니다.', NULL, '저습지에 있는 용감무쌍호의 잠긴 금고를 찾아야 합니다.', NULL),
(292, '팔레스의 눈', '금고를 열자 기분 나쁜 빛을 발하는 더러워진 수정구가 들어 있습니다. 피츠시몬즈가 말하던 보물, 팔레스의 저주받은 눈입니다.$B$B팔레스의 저주받은 눈을 메네실 항구에 있는 드워프 사제 글로린 스틸브라우에게 가져가십시오. 그리고 그에게 팔레스의 눈에 걸려 있는 저주를 풀어 달라고 부탁해야 합니다.', '저습지의 메네실 항구에 있는 글로린 스틸브라우에게 팔레스의 저주받은 눈을 가져가야 합니다.', NULL, NULL, NULL),
(294, NULL, NULL, NULL, NULL, '저습지의 웰가르의 발굴현장에 있는 오머 아이언브레이드에게 가야 합니다.', NULL),
(295, '오머의 복수', '자, 이제 저 끔찍한 랩터들에게 수많은 피를 흘리게 한 대가가 얼마나 큰 것인지 깨닫도록 해야 할 때요. 바로 저 아래쪽으로 가면 갈퀴발톱 줄무늬랩터와 무쇠턱 줄무늬랩터들이 무리 지어 있소. 이 고약한 짐승들을 각각 10마리씩 처치해 주시오!', '웰가르의 발굴현장에 있는 오머 아이언브레이드가 갈퀴발톱 줄무늬랩터 10마리, 무쇠턱 줄무늬랩터 10마리를 처치해 달라고 했습니다.', NULL, '저습지의 웰가르의 발굴현장에 있는 오머 아이언브레이드에게 가야 합니다.', NULL),
(296, '오머의 복수', '당신이 없는 동안 저 짐승들 중 한 놈이 다른 놈들과 다르다는 사실을 발견했소. 이놈은 다른 놈들보다 크고 훨씬 더 사나웠소이다. 아무래도 놈이 무리를 이끌면서 발굴 현장을 어지럽히고 다니는 우두머리인 것 같소.$B$B이번이 내가 부탁하는 마지막 임무가 될 거요. 살투스란 녀석은 죄가 막중하니 정의의 이름으로 처치해 주시오! 내게 놈이 죽었다는 증거로 놈의 발톱 하나를 가져다주시오.', '웰가르의 발굴현장에 있는 오머 아이언브레이드가 살투스를 처치한 후 발톱을 가져다 달라고 했습니다.', NULL, '저습지의 웰가르의 발굴현장에 있는 오머 아이언브레이드에게 가야 합니다.', NULL),
(298, '발굴 상황 보고서', '텔사마에 발굴 상황에 대한 보고를 해야 하오. 화약 지원 요청도 해야 하고 말이오. 보고서는 여기 있소. 이걸 텔사마의 연락 담당인 예른 혼헬름에게 갖다주시겠소?$B$B매우 중대한 일이오. 힘든 일은 아니니 꼭 좀 부탁하겠소!', '텔사마의 예른 혼헬름에게 아이언밴드의 상황 보고서를 가져가야 합니다.', NULL, NULL, NULL),
(299, '드러난 과거', '저 랩터들의 침략이 있기 직전에 고아즈석이라는 큰 석판을 발견했다네. 석판의 내용은 모두 4부분으로 나뉘어 있네. 그 내용을 보면 ≪신성한 계획≫과 ≪운명의 예언≫에 대해 말하고 있다네.$B$B시간이 별로 없네. 내가 직접 가서 저 짐승들을 상대하기엔 너무 늙었지만 자네는 강하고 젊지 않은가.$B$B발굴현장을 정리하고 사라진 4개의 석판 조각을 찾아 주게나. 그 석판 조각들은 각각 아도스, 모드르, 골름, 네루라고 한다네. 고대 유물이나 흙이 팬 곳에서 찾아보면 될 거야. 의문을 풀 수 있도록 내게 그 석판 조각들을 가져다주게!', '발굴조사단장 웰가르가 발굴현장을 정리하고 사라진 아도스 조각, 모드르 조각, 골름 조각, 네루 조각을 가져다 달라고 했습니다.', NULL, '저습지의 웰가르의 발굴현장에 있는 발굴조사단장 웰가르에게 가야 합니다.', NULL),
(303, NULL, NULL, NULL, NULL, '저습지의 던 모르드에 있는 모틀리 가마슨에게 가야 합니다.', NULL),
(304, NULL, NULL, NULL, NULL, '저습지의 던 모드르에 있는 결의의 롱브레이드에게 가야 합니다.', NULL),
(306, '발굴단을 찾아서', '우리는 굉장히 희귀한 유물을 발굴하고 있었는데, 이 거대한 뼈들이 나오기 시작한 거예요. 정말 끔찍했어요!$B$B그런데 우리가 무슨 일이 일어나고 있는지 알아채기도 전에 줄무늬랩터들이 발굴현장을 공격해 왔어요. 그래서 많은 사람이 목숨을 잃었죠.$B$B우리의 용감한 오머가 발굴조사단장님과 저의 목숨을 구해 줬어요. 오머가 엄호해 준 덕분에 안전한 곳으로 도망칠 수 있었죠. 이젠 여기 갇힌 신세이고 우리가 힘들게 발굴한 것들도 다 버려져 있답니다.$B$B자, 이 편지를 남편 타렐에게 전해 주세요. 편지에 이곳 상황을 자세히 설명해 놨어요.', '저습지의 메네실 항구에 있는 타렐 록위버에게 메린의 편지를 가져가야 합니다.', NULL, NULL, NULL),
(308, '맥주를 좋아하는 야벤', NULL, NULL, NULL, '던 모로에 있는 야벤 썬더브루에게 가야 합니다.', NULL),
(312, NULL, NULL, NULL, NULL, '던 모로의 브루날 마을에 있는 툰드라 맥그란에게 가야 합니다.', NULL),
(313, NULL, NULL, NULL, NULL, '던 모로의 카라노스에 있는 대장 타란에게 가야 합니다.', NULL),
(314, NULL, NULL, NULL, NULL, '앰버스틸 목장에 있는 루드라 앰버스틸에게 가야 합니다.', NULL),
(315, NULL, NULL, NULL, NULL, '던 모로의 카라노스에 있는 레욜트 발리브루에게 가야 합니다.', NULL),
(316, '[미사용]', NULL, NULL, NULL, '시험용 다람쥐에게 가야 합니다.', NULL),
(317, NULL, NULL, NULL, NULL, '던 모로의 툰드리드 언덕에 있는 조종사 벨로우피즈에게 가야 합니다.', NULL),
(319, NULL, NULL, NULL, NULL, '던 모로의 찬바람 골짜기에 있는 레욜트 발리브루에게 가야 합니다.', NULL),
(322, '신성한 무기', '스톰윈드에 있는 드워프 지구에 라이트포지 철을 잘 다루는 그리만트 엘모어라는 드워프 대장장이가 있네.$B$B자네가 찾은 주괴를 제련하여 상자에 넣어 두었으니 그걸 그리만트에게 가져가 자네 얘길 해 보게나. 이런 일은 기꺼이 도와줄 친구니까 자네를 위해 무기를 만들어 줄 것이야. 모벤트 펠도 무서워할 만큼의 강력한 무기를!', '스톰윈드에 있는 그리만트 엘모어에게 라이트포지 주괴가 든 상자를 가져가야 합니다.', NULL, NULL, NULL),
(323, NULL, NULL, NULL, NULL, '그늘숲의 고요의 강둑에 있는 스벤 요르겐에게 가야 합니다.', NULL),
(324, '사라진 주괴', '물에 젖은 상자에 라이트포지 주괴가 하나 있는 것으로 보아 멀록들이 나머지 주괴를 훔쳐 간 것이 분명합니다. 난파된 창공의 물수리호 부근에서 멀록 약탈꾼들을 처치하고 사라진 라이트포지 철을 찾아야 합니다.', '라이트포지 주괴 5개를 모은 다음 저습지에 있는 글로린 스틸브라우에게 가야 합니다.', NULL, '저습지의 메네실 항구에 있는 글로린 스틸브라우에게 가야 합니다.', NULL),
(326, '<미사용>', NULL, NULL, NULL, '가야 합니다.', NULL),
(327, '<미사용>', NULL, NULL, NULL, NULL, NULL),
(328, NULL, NULL, NULL, NULL, '가시덤불 골짜기에 있는 헤로드의 금고를 찾아야 합니다.', NULL),
(329, '드러나는 첩자의 정체', '금고의 귀중한 물건들 중에는 진흙투성이의 휘갈겨 쓴 쪽지가 있습니다. 알아보기 힘들긴 하지만 병사 토르센의 여행 계획인 것 같습니다. 거기에는 정찰 경로, 접촉할 대상, 그리고 반란군의 임무를 완수하기 위한 시간 계획 등이 적혀 있습니다. 계획서에는 ''-M''이라는 한 글자로 된 서명이 있습니다.$B$B이 쪽지를 작성한 것이 누구든지 간에 토르센과 매우 가까운 사이었음이 분명합니다. 또한 그자가 바로 반란군 야영지 내의 배반자일 것입니다.', '반란군 야영지에 있는 부관 도렌에게 진흙투성이 쪽지를 가져가야 합니다.', NULL, '가시덤불 골짜기의 반란군 야영지에 있는 부관 도렌에게 보고해야 합니다.', NULL),
(330, '정찰 일정', '당신이 찾아 준 쪽지에 ≪-M≫이라고 서명이 되어 있는데… 누구를 말하는 건지 모르겠소.$B$B하지만… 쪽지에 따르면 이자가 지난주에 토르센과 함께 정찰을 했다는 것을 알 수 있군그래. 그러니 지난주에 토르센과 함께 정찰 임무를 수행한 자가 배반자일 거요!$B$B하사관 세스먼에게 가 보시오. 그가 정찰 일정을 관리하니 토르센과 함께 임무를 수행한 자가 누군지 말해 줄 수 있을 거요.', '하사관 세스먼과 대화해야 합니다.', NULL, '가시덤불 골짜기의 반란군 야영지에 있는 하사관 세스먼과 대화해야 합니다.', NULL),
(331, '도렌에게 보고하기', '도렌 부관님께서 이 정찰 정보를 보고하라고 하셨나요?', '부관 도렌과 대화해야 합니다.', NULL, '가시덤불 골짜기의 반란군 야영지에 있는 부관 도렌과 대화해야 합니다.', NULL),
(335, NULL, NULL, NULL, NULL, '스톰윈드에 있는 검은발톱 자데스에게 가야 합니다.', NULL),
(336, '귀족을 위한 술', '위쇼크 경도 모든 사람과 마찬가지로 약점이 있소. 술을 무척 좋아한단 말이지. 그러고 보면 그 작자의 위선도 참 대단해. 낮에는 이 선술집의 문을 닫게 하려고 노력하면서 밤에는 이곳 위층에서 술을 퍼마신단 말이야. 게다가 계산은 절대 안 하지. 자, 어디 보자. 내가 특별히 준비한 술, 검은발톱 스타우트 맥주를 맘에 들어 할까? 이거 꽤 독한 술이라오.$B$B이 술을 위쇼크 경에게 가져다주고 얼마나 좋아하는지 살펴보시오. 그 늙은 바보 녀석은 주로 왕국 민원실 근처에서 정처 없이 서성거린다오.', '왕국 민원실에 있는 보울즈 K. 위쇼크 경에게 검은발톱 스타우트 맥주를 줘야 합니다.', NULL, NULL, NULL),
(338, NULL, NULL, NULL, NULL, '가시덤불 골짜기의 네싱워리 원정대에 있는 바닐 스톤팟에게 가야 합니다.', NULL),
(339, NULL, NULL, NULL, NULL, '가시덤불 골짜기의 네싱워리 원정대에 있는 바닐 스톤팟에게 가야 합니다.', NULL),
(340, NULL, NULL, NULL, NULL, '가시덤불 골짜기의 네싱워리 원정대에 있는 바닐 스톤팟에게 가야 합니다.', NULL),
(341, NULL, NULL, NULL, NULL, '가시덤불 골짜기의 네싱워리 원정대에 있는 바닐 스톤팟에게 가야 합니다.', NULL),
(342, NULL, NULL, NULL, NULL, '가시덤불 골짜기의 네싱워리 원정대에 있는 바닐 스톤팟에게 가야 합니다.', NULL),
(346, '수사 크리스토프에게로', '자, 책의 사본을 다 완성했습니다. 이게 ''철강의 중요성'' 원본이니 받으세요. 인내심을 가지고 기다려 줘서 정말 고맙습니다. 아참, 밀턴 씨에게는 시간이 오래 걸려서 미안하다고 전해 주십시오.', '대성당 광장에 있는 수사 크리스토프에게 돌아가서 ''철강의 중요성''을 전달해야 합니다.', NULL, NULL, NULL),
(347, '레스밴 광석', '레스밴 광석은 이 광석을 처음 발견한 바트 레스밴의 성을 따서 이름을 붙인 걸세. 용해할 경우 철처럼 단단하지는 못하지만 어둡고 탁한 색을 내기 때문에 잉크로 사용하는 서기들이 종종 있지. 이곳 북쪽에 있는 레스밴 동굴로 가면 찾을 수 있을 걸세.$B$B평소에는 비축해 놓은 것이 몇 개 있었지만 최근에는 오크의 공격에 대비하느라 채취할 시간이 없었지. 게다가… 지금은 레스밴 동굴에 붉은마루 놀도 살고 있고 붉은마루 노역꾼들이 그 광석을 캐고 있다네.$B$B그러니까 필요하다면 직접 가서 가져오는 수밖에 없다네.', '레스밴 광석 5개를 모아서 북녘골 도서관에 있는 수사 팩스턴에게 가져가야 합니다.', NULL, '엘윈 숲의 북녘골 수도원에 있는 수사 팩스턴에게 가야 합니다.', NULL),
(348, NULL, NULL, NULL, NULL, '가시덤불 골짜기의 무법항에 있는 핀 피즈라켓에게 가야 합니다.', NULL),
(349, '가시덤불 골짜기의 열병', '임시 텍스트 02 - 설명', '임시 텍스트 02 - 로그', NULL, '가시덤불 골짜기에 있는 의술사 운바그와에게 가야 합니다.', NULL),
(350, '오랜 친구 찾기', '그 마르존 녀석이 데피아즈 단원과 접촉하고 있었을 테니 라스코발과 연관이 있을 걸세…$B$B밴클리프와 스레드가 죽었으니 라스코발을 법대로 처리하기가 어렵게 됐어. 그들의 증언 없이는 자네 증거도 아무 소용이 없으니까 말이야. 더군다나 라스코발은 귀족이고 고위 인사와 관계도 두텁지. 법 위에 사는 녀석이야.$B$B다른 데서 도움을 받아야 할 것 같아. 정말 내키진 않지만 우리를 도와줄 만한 자가 있네. 이 도시의 상업 지구에 있는 트리아스를 찾아보게.', '스톰윈드에 있는 엘링 트리아스와 대화해야 합니다.', NULL, NULL, NULL),
(352, '[미사용]', 'Great Mammoda. 어마어마한 덩치에 칼날 같은 발톱과 이빨을 가진 괴물이었네. 나는 방심하다 당했지만, 경계를 늦추지 않았다 해도 결과는 별반 다르지 않았을 걸세. 한 대 퍽하고 맞았을 뿐인데 앞이 캄캄하더군. 사람들은 지금 내가 걸을 수 있는 게 다행이라고들 한다네…$B$B뭐, 이 오래된 이야기도 별로 재미는 없군, 그렇지 않나? 아무튼 말이야, 만약 자네가 Lady of the Loch와 맞설 생각이 있으면…', NULL, NULL, NULL, NULL),
(354, NULL, NULL, NULL, NULL, '티리스팔 숲의 브릴에 있는 콜만 파딩에게 가야 합니다.', NULL),
(355, '세브렌과의 대화', '$C님께서 아가만드 가문의 유골을 가져다준 덕분에 이제 복수의 욕망은 채워졌습니다. 하지만 아가만드 제분소는 저뿐만 아니라 모든 포세이큰들에게 위협이 되고 있습니다.$B$B아가만드 가문을 상대로 이룬 $C님의 공적을 집정관 세브렌 님께 말씀드렸더니 만나 보고 싶어하십니다. 그분께 가 보시기 바랍니다.', '브릴에 있는 집정관 세브렌과 대화해야 합니다.', NULL, NULL, NULL),
(356, '후방 경비', '역병지대로부터 티리스팔을 방어하는 보루 수비대의 경계 태세가 철통 같긴 하지만, 간혹 스컬지가 몰래 경계를 통과하기도 하네.$B$B정면의 적만 상대하면 뒤에서 공격을 당하거나 수비대에게 보급로가 차단당할 수 있다는 문제가 있어.$B$B서쪽으로 순찰을 나가 눈에 띄는 스컬지를 모두 처치해 주게. 특히 발니르 농장이 이 침략자들의 본거지가 되어 버린 것 같으니 그곳에 있는 스컬지들을 처치해 주고.', '피투성이 좀비 8마리와 떠도는 영혼 8마리를 처치해야 합니다.', NULL, '티리스팔 숲의 브릴에 있는 고위집행관 데링턴에게 가야 합니다.', NULL),
(357, NULL, NULL, NULL, NULL, '티리스팔 숲에 있는 베소르 아이스샤드에게 가야 합니다.', NULL),
(358, NULL, NULL, NULL, NULL, '티리스팔 숲의 브릴에 있는 집정관 세브렌에게 가야 합니다.', NULL),
(359, '포세이큰의 의무', '동쪽에 있는 죽음경비병 초소로부터 최근 상황에 대한 보고를 받아야 하네.$B$B스컬지 병력이 보루를 빠져나와 티리스팔로 들어왔는지가 내 관심거리일세. 역병지대 변두리에 대한 경계를 유지하지 않으면 스컬지가 이 지역에 근거지를 구축할지도 몰라!$B$B길을 따라 남쪽으로 이동한 후 세 갈래 길에서 동쪽 길로 가면 초소가 나오네. 죽음경비병 리니아와 이야기를 나눠보면 필요한 정보를 들을 수 있을 거야.', '죽음경비병 리니아와 대화해야 합니다.', NULL, NULL, NULL),
(361, '배달되지 않은 편지', '아가만드가의 장남인 그레고르 아가만드가 쓴 편지입니다. 수신자가 이베트 파딩으로 되어 있지만 아직 배달되지 못한 것이 분명해 보입니다.', '이베트 파딩을 찾아서 투르만 아가만드가 쓴 편지를 전달해야 합니다.', NULL, NULL, NULL),
(362, NULL, NULL, NULL, NULL, '티리스팔 숲의 브릴에 있는 콜만 파딩에게 가야 합니다.', NULL),
(363, '각성의 시간', '제때 깨어나서 반갑구려. 다른 이들과 함께 불 속에 던져 넣으려던 참이었는데 회복했군$B$B나는 죽음의 종소리 마을의 무덤을 관리하고 있는 모르도라고 하오. 이제 당신은 더는 리치 왕의 노예가 아닌 포세이큰의 일원으로 다시 태어났소.$B$B언덕 아래쪽으로 내려가다 보면 성당이 나올 거요. 거기에 있는 어둠의 사제 사비스 님과 얘기해 보시오. 그분이 포세이큰의 일원이 된 자로서 알아야 할 얘기를 자세히 들려주실 것이오.$B$B이 무덤을 벗어나려거든, 계단을 올라가 지상으로 나가시오. 나가서 길을 따라 내려가면 사비스 님이 계신 성당을 찾을 수 있소.', '어둠의 사제 사비스와 대화해야 합니다.', NULL, NULL, NULL),
(364, '넋 나간 좀비', '첫 번째 포세이큰이 무덤 밖으로 기어나왔을 때부터 우리는 지금 리치 왕의 스컬지 군대와 전쟁 중이라네. 놈들은 마법으로 소환된 언데드, 북쪽의 사악한 짐승들, 그리고 고통받는 유령들로 이루어진 군대야.$B$B리치 왕은 얼어붙은 왕좌에 더는 앉아있지 않지만, 그의 노예들이 마을 북쪽 지역을 침범했네. 반드시 놈들을 말살시켜야 해. 설사 그들이 우리의 옛 형제, 자매들이었을지 몰라도 이젠 리치 왕의 노예일 뿐일세.', '넋 나간 좀비 5마리와 흉측한 구울 5마리를 처치해야 합니다.', NULL, '티리스팔 숲의 죽음의 종소리 마을에 있는 어둠의 사제 사비스에게 가야 합니다.', NULL),
(365, NULL, NULL, NULL, NULL, '티리스팔 숲의 브릴에 있는 연금술사 요한에게 가야 합니다.', NULL),
(366, '마법책 반납', '오래전 군터와 나, 그리고 지금은 스컬지 강령술사가 된 까마귀발톱 쑤울은 달라란에 있는 마법사 학회인 키린 토에서 함께 공부하는 사이였네.$B$B군터와 나는 모두 역병에 휘말렸었는데, 난 그가 죽었거나 리치 왕 수하의 귀족이 되었겠거니 생각하고 있었지. 그가 자유로운 몸이라는 사실을 알게 되어 기쁘군.$B$B그를 반드시 우리 편으로 끌어들여야 하네. 이 마법책을 그 친구가 보면 나 역시 리치 왕으로부터 자유로운 몸이라는 걸 그에게 보여 주도록 책에 주문을 걸어 놓았네. 그가 마법책을 본 후엔 우리에게 동참했으면 좋겠군.', '군터의 은거지로 가서 군터의 마법책을 돌려줘야 합니다.', NULL, NULL, NULL),
(367, '새로운 역병', '실바나스 여왕님께서 왕립 연금술 학회 총회를 소집하셨소. 어둠의 여왕님께서는 우리의 지식과 새로 발견된 마법을 결합하면, 아서스를 파멸로 이끌 방법을 찾을 수 있을 거라 믿고 계시오. 그래서 우리에게 아제로스에 알려진 그 어떤 병보다도 치명적인 새로운 역병을 만들어내라고 명령하셨지. 이 새로운 역병은 아서스의 스컬지 군대를 파멸로 이끌게 될 것이오.$B$B연구해 보니 새로운 역병을 만드는 데 짐승의 피가 핵심적인 요소가 될 수도 있을 것 같더군. 내 이론을 시험해 볼 수 있도록 암흑사냥개 피 5병을 가져다주시오.', '브릴에 있는 연금술사 요한이 암흑사냥개 피 5병을 가져다 달라고 했습니다.', NULL, '티리스팔 숲의 브릴에 있는 연금술사 요한에게 가야 합니다.', NULL),
(368, '새로운 역병', '당신이 재료를 모아 오는 동안 몇 가지 실험을 해 봤는데 이 새로운 역병을 퍼뜨리기 위해선 몇 가지 재료가 더 필요하다는 걸 알게 됐소. 운 나쁘게 실험용으로 발탁된 녀석들 몇 명을 독살하는 건 쉬운 일이지만 온 세상에 역병을 퍼뜨리는 건 좀 더 복잡하단 말이지.$B$B북쪽이나 서쪽에 있는 해안으로 가면 멀록들이 있을 것이니 그들을 처치하고 썩은지느러미 비늘 5개를 가져다주시오.', '브릴에 있는 연금술사 요한이 티리스팔 숲에 있는 썩은지느러미 비늘 5개를 가져다 달라고 했습니다.', NULL, '티리스팔 숲의 브릴에 있는 연금술사 요한에게 가야 합니다.', NULL),
(369, NULL, NULL, NULL, NULL, '티리스팔 숲의 브릴에 있는 연금술사 요한에게 가야 합니다.', NULL),
(370, NULL, NULL, NULL, NULL, '티리스팔 숲의 브릴에 있는 집행관 자이건드에게 가야 합니다.', NULL),
(371, NULL, NULL, NULL, NULL, '티리스팔 숲의 브릴에 있는 집행관 자이건드에게 가야 합니다.', NULL),
(372, '붉은십자군과의 전쟁', '붉은십자군이 파올의 안식처를 지나 티리스팔 북쪽, 그러니까 여기서 북동쪽에 있는 폐허가 된 탑에서 공격해 오고 있네. 정보에 의하면 대장 멜라케라는 무자비한 사령관이 이 사악한 부대를 지휘하고 있다고 하는군.$B$B이 임무 역시 자네가 좀 맡아줬으면 하네. 어둠의 여왕 폐하의 이름으로 멜라케와 그의 두 경호원을 처치해 주게.', '브릴 마을에 있는 집행관 자이건드가 대장 멜라케와 붉은십자군 경호원 2명을 처치해 달라고 했습니다.', NULL, '티리스팔 숲의 브릴에 있는 집행관 자이건드에게 가야 합니다.', NULL),
(374, NULL, NULL, NULL, NULL, '티리스팔 숲의 브릴에 있는 죽음경비병 버제스에게 가야 합니다.', NULL),
(375, NULL, NULL, NULL, NULL, '티리스팔 숲의 브릴에 있는 그레첸 데드마에게 가야 합니다.', NULL),
(376, '저주받은 존재', '제가 맡은 일은 부상당한 전사들을 돌보거나, 갑옷과 의복을 짓거나, 어둠의 사제 사비스 님이 필요로 하시는 모든 일을 돕는 거랍니다.$B$B보아하니 당신도 그분을 도와… 좀비들을 처치하게 될 것 같군요. 제 생각엔 틀림없이 당신을 보호해줄 방어 장비가 필요할 테니 도와 드리도록 하죠. 그런데 재료가 되는 짐승 앞발과 날개가 다 떨어져서 말이에요. 좀 구해다 주시면 갑옷을 만들어 드릴게요. 남쪽으로 가면 늑대와 박쥐들이 많이 있을 거예요.', '승냥이 앞발 4개와 그늘박쥐 날개 4개를 획득해야 합니다.', NULL, '티리스팔 숲의 죽음의 종소리 마을에 있는 수련사제 엘레스에게 가야 합니다.', NULL),
(377, NULL, NULL, NULL, NULL, '그늘숲의 어둠골에 있는 원로 밀스타이프에게 가야 합니다.', NULL),
(378, NULL, NULL, NULL, NULL, '저습지 의 던 모드르에 있는 모틀리 가마슨에게 가야 합니다.', NULL),
(379, '갈증 해소', '동력원이 필요하다면야 내가 도와줄 수 있지. 내게 필요한 게 뭔지 아나? 바로 마실 거야! 내게 사막유랑단 물주머니 5개를 가져오면 당신에게 4711-FTZ를 주지.$B$B어디… 그 사막유랑단 물주머니들을 어디서 찾을 수 있을 것 같나? 동쪽에 있는 사막유랑단 유목민 한 명에게 가서 하나 달라고 해 보시지. 그리고 그 결과를 내게 알려달라고.', '가젯잔에 있는 선임기술자 빌지위즐에게 사막유랑단 물주머니 5개를 가져가야 합니다.', NULL, '타나리스의 가젯잔에 있는 선임기술자 빌지위즐에게 가야 합니다.', NULL),
(380, NULL, NULL, NULL, NULL, '티리스팔 숲의 죽음의 종소리 마을에 있는 집행관 아렌에게 가야 합니다.', NULL),
(381, NULL, NULL, NULL, NULL, '티리스팔 숲의 죽음의 종소리 마을에 있는 집행관 아렌에게 가야 합니다.', NULL),
(382, '붉은십자군 전령', '브릴에 계신 내 상관께서 보내신 소식에 따르면 붉은십자군 중 한 명이 붉은십자군 수도원에서 이곳 죽음의 종소리 마을로 파견됐다고 하네. 정보에 따르면 그 전령이 중요한 정보를 가지고 있다고 하는데 우리가 아는 건 여기까지야.$B$B이 일은 자네가 적임자야. 그 전령을 찾아내 지니고 있는 정보를 내게 가져오도록 하게.', '붉은십자군 야영지에 있는 전령 메븐 코갈을 처치한 다음 입수한 정보를 집행관 아렌에게 가져가야 합니다.', NULL, '티리스팔 숲의 죽음의 종소리 마을에 있는 집행관 아렌에게 가야 합니다.', NULL),
(383, '중요한 정보', '이 정보를 브릴에 있는 내 상관이신 자이건드 집행관님께 보내야 하네. 이 정도 정보라면 붉은십자군에 결정적인 타격을 줄 수 있을 거야. 이곳 죽음의 종소리 마을에서도 자네의 도움이 필요하긴 하지만 말이야… 자이건드 님께 이 정보를 전달할 자도 필요하고, 그분이 자네한테 더 적합한 임무를 맡겨 주실 거라 믿네.$B$B죽음의 종소리 마을을 나가 북쪽으로 길을 따라가게. 티리스팔로 접어들면 곧 교차로가 나오는데 거기서 동쪽으로 돌아 계속 동쪽 길을 따라가도록 해. 길을 따라가다 보면 버려진 장원을 지나가게 될 거야.', '브릴에 있는 집행관 자이건드에게 붉은십자군 문서를 전달해야 합니다.', NULL, NULL, NULL),
(384, NULL, NULL, NULL, NULL, '던 모로의 아지랑이 마루에 있는 라그나르 썬더브루에게 가야 합니다.', NULL),
(385, '악어 사냥', '많은 사냥꾼들이 악어를 사냥하기 위해 이곳 모단 호수로 모여든다네. 악어 껍질은 옷이나 갑옷 등에 쓰이고 그 고기도 아주 잘 팔리거든.$B$B우리도 악어를 거래하긴 하지만 많은 양은 아니라네. 악어가 워낙 사나운데다가 요즘에는 호수 안의 섬 곳곳에 틀어박혀 지내서 말이야. 그렇다고 포기는 말게. 이 짐승과 싸워 보는 건 좋은 경험이 된다네.$B$B어때, 한번 해 보겠나?', '원정순찰대 오두막에 있는 마렉 아이언하트에게 악어 고기 5개와 악어 껍질 6장을 가져가야 합니다.', NULL, NULL, NULL),
(386, NULL, NULL, NULL, NULL, '붉은마루 산맥의 호숫골에 있는 경비병 베르턴에게 가야 합니다.', NULL),
(387, '폭동 진압', '폭동이 일어났네! 이를 진압해야 하니 제발 날 좀 도와 주게. 지하감옥이 죄수들 손에 넘어갔다는 소문이 바깥으로 퍼지기라도 하면 난 분명히 해고되고 말걸세! 생각만 해도 끔찍한 일이야. 하지만 지금 중요한 건 우선 죄수들의 항복을 받아내 스톰윈드를 안전하게 보호하는 것이네.$B$B폭동에 대한 대가는 죽음뿐! 이 일탈자들의 일부를 처단해 주게! 그러면 이곳을 다시 통제할 수가 있을걸세.', '스톰윈드에 있는 교도소장 델워터가 지하감옥에서 복역수 10명, 무기징역수 8명, 반역자 8명을 처치해 달라고 했습니다.', NULL, '스톰윈드에 있는 교도소장 델워터에게 가야 합니다.', NULL),
(388, NULL, NULL, NULL, NULL, '스톰윈드의 구 시가지에 있는 니코바 라스콜에게 가야 합니다.', NULL),
(390, '[미사용]', NULL, NULL, NULL, NULL, NULL),
(391, NULL, NULL, NULL, NULL, '스톰윈드에 있는 교도소장 델워터에게 가야 합니다.', NULL),
(393, '과거의 그림자', '이제 더 알려드릴 단서가 없습니다. 그러나 도움이 될 만한 사람을 한 명 알지요. 더구나 그 사람은 내게 빚을 진 일이 하나 있어서… 흠, 지금은 그런 얘기를 할 때가 아니군요. 어쨌든 구 시가지에 있는 병영에서 SI:7의 단장 마티아스 쇼를 찾아가 보십시오. 쇼는 도시에서 일어나는 대부분의 비밀스럽고 음흉한 일에 관련되어 있답니다.$B$B쇼가 모르면 아무도 모르는 겁니다.', '스톰윈드에 있는 단장 마티아스 쇼에게 스레드의 방문객에 대한 봉인된 인상서를 전해야 합니다.', NULL, NULL, NULL),
(394, '잔인한 자의 최후', '구 시가지로 가서 쇼 단장을 찾으시기 바랍니다. 가서 당신이 라스코발의 위협을 제거한 사실과 그가 꾸몄던 음모를 알아냈다는 소식을 전하도록 하십시오. 마티아스는 스톰윈드 시민 중에 영웅이 또 있다는 사실을 알면 자랑스러워할 겁니다.$B$B그 친군 틀림없이 당신을 왕자님이나 다른 귀족과 만나게 해줄 것입니다. 단 술은 너무 많이 마시지 마세요. 귀족들은 이 도시를 자기들 마음대로 통치할 수 있다고 생각하지만 귀족들이 어찌하지 못하는 일들도 있는 것이지요.', '스톰윈드에 있는 마티아스 쇼와 대화해야 합니다.', NULL, NULL, NULL),
(395, '결사단의 종말', '아, 자네가 떠나 있는 동안 알렉스턴이 왔다 갔다는 걸 깜빡했군. 자네와 얘기를 하고 싶다고 하더군. 분명히 데피아즈 결사단의 사태에 대해서 귀족들께 보고하려고 하는 것일게야.$B$B한 가지 조언을 하도록 하지. 누군가 내게 묻거든 모든 것을 자세히 설명해 주도록 하겠네. 물론 자네가 라스코발 경을 처치했다는 것만 빼고 말이야. 날 믿게나. 이런 일에는 이골이 난 사람이라네.$B$B그리고 자네… 트리아스에 대한 얘기는… 아무에게도 하지 말게나.', '스톰윈드에 있는 바로스 알렉스턴과 대화해야 합니다.', NULL, NULL, NULL),
(396, '국왕 알현', '국왕께 보낼 보고서를 준비했습니다. 지금까지 당신이 발견한 것들을 고려해 볼 때 당신이 이 보고서를 전할 적임자라고 생각합니다. 걱정하지 마십시오, 국왕께서도 분명히 스톰윈드의 백성으로서 의무를 다한 당신을 칭찬하실 테니까 말입니다.$B$B알현 일정이 곧 잡혀 있으니 서두르는 게 좋겠습니다. 스톰윈드 왕궁까지는 약간 머니 말입니다.', '스톰윈드 왕궁으로 가서 알렉스턴의 데피아즈 결사단에 대한 보고서를 국왕 바리안 린에게 전달해야 합니다.', NULL, NULL, NULL),
(397, '수고의 대가', '위쇼크 경이 술을 맛있게 먹었다고 하는군, 흐흐.$B$B그동안 수고 많았소. 당신 덕분에 스톰윈드의 흑마법사들이 방해받지 않고 계속 하던 일을 할 수 있게 되었소. 수고한 대가로 특별한 선물을 준비해 두었지. 내 하인, 즈기에게 얘기해서 선물을 받아 가도록 하시오.', '검은발톱 자데스의 하인인 즈기와 대화하여 보상을 받아야 합니다.', NULL, NULL, NULL),
(398, NULL, NULL, NULL, NULL, '티리스팔 숲의 브릴에 있는 집행관 자이건드에게 가야 합니다.', NULL),
(399, NULL, NULL, NULL, NULL, '스톰윈드에 있는 바로스 알렉스턴에게 가야 합니다.', NULL),
(401, '시라의 번역 기다리기', '편지를 거의 다 번역했습니다. 잠시 후에 다시 찾아오면 끝나 있을 겁니다.', '잠시 기다렸다가 시라 본인디와 다시 대화해야 합니다.', NULL, NULL, NULL),
(402, '분주한 시라', '미안합니다. 지금 마을 상황이 좋지 않다 보니 다른 할 일이 너무 많아서 말입니다. 나중에, 우리가 그때까지 아무 일이 없다면, 번역을 끝내 드리도록 하죠.', '나중에 다시 시라를 찾아와 시간 여유가 있는지 확인해야 합니다.', NULL, NULL, NULL),
(403, '썬더브루 맥주통', NULL, NULL, NULL, NULL, NULL),
(404, '더러운 임무', '스컬지가 티리스팔 숲에 침투하여 브릴 서쪽 지역에 있는 오래된 다리 근처를 완전히 오염시켰네.$B$B그곳으로 가서 썩어 문드러진 망자와 심하게 훼손된 시체들을 눈에 띄는 대로 처치한 다음 내게 부패한 발톱을 가져오게. 그리하면 죽음경비병들로부터 보상이 있을 것이네.', '브릴에 있는 죽음경비병 딜링거에게 부패한 발톱 7개를 가져가야 합니다.', NULL, '티리스팔 숲의 브릴에 있는 죽음경비병 딜링거에게 가야 합니다.', NULL),
(406, '[미사용]', NULL, NULL, NULL, NULL, NULL),
(407, '오염된 농장', '당신이 가져온 호박들은 겉으론 그냥 호박이지. 하지만 북쪽에서 전진해 오는 아서스의 진군을 막아내고, 남쪽에서 점점 늘어나고 있는 인간의 수를 줄이려면 우리 언데드의 잠재된 능력을 모두 발휘해야 하오.$B$B약간의 재주만 발휘하면 평범한 호박을 어둠의 여왕님의 위대한 계획에 큰 도움이 되는 재료로 만들 수 있소. 방금 이 호박에 내 최신 처방을 했으니 이제 꽤 쓸만한 물건이 될 것이오.$B$B아직 붉은십자군 광신도 중 한 명이 포로로 잡혀서 교수대끝 선술집 지하실에 갇혀 있을 거요. 이 호박을 그 얼간이에게 가져다주시오.', '사로잡힌 붉은십자군 광신도에게 줄무늬 호박을 가져가야 합니다. 교수대끝 선술집 지하실에 갇혀 있습니다.', NULL, NULL, NULL),
(408, NULL, NULL, NULL, NULL, '티리스팔 숲의 브릴에 있는 집정관 세브렌에게 가야 합니다.', NULL),
(409, '동맹의 증거', '자네가 리치 왕의 부하가 아니라고 주장하고 있는데다, 베소르가 이 책에 불어넣은 마법이 그 말이 사실임을 증명해 주는군. 하지만 자네가 스컬지의 적이라는 것을 증명해야 믿을 수 있을 것 같군.$B$B이 섬 남쪽 끝에 또 다른 조그만 섬이 있는데 그곳에 오래된 피투성이의 제단이 있네. 강력한 스컬지 요원, 릴리스 네파라가 사용하는 것이지.$B$B여기 있는 상자에서 부름의 양초를 가지고 가서 제단 위에 이 양초를 올려놓고 불을 붙이면 릴리스가 깨어날 걸세. 릴리스를 처치하면 자네가 리치 왕의 졸개가 아니라는 것을 믿어 주지.', '부름의 양초를 얻어야 합니다.릴리스 네파라를 소환하여 처치해야 합니다.그 후에 섬에 있는 군터에게 돌아가도록 하십시오.', NULL, '티리스팔 숲의 붉은십자군 전초기지에 있는 군터 아카누스에게 가야 합니다.', NULL),
(410, '잠든 망령', NULL, NULL, NULL, '서부 역병지대에 있는 릴리스의 제단으로 가야 합니다.', NULL),
(411, '회개한 마술사의 귀환', '이 지옥의 보석을 내 오랜 친구인 베소르에게 가져다주게. 이것으로 내가 그와 교신할 수 있게 될 걸세. 아.. 그에게 할 말이 무척 많군.', '언더시티에 있는 베소르 아이스샤드에게 지옥의 보석을 가져가야 합니다.', NULL, NULL, NULL),
(412, NULL, NULL, NULL, NULL, '카라노스에 있는 라즐 스프리스프로켓에게 가야 합니다.', NULL),
(415, '레욜트의 새 술', '브루날 마을의 레욜트 발리브루가 자네를 찾고 있다네. 요즘 만들고 있는 새로운 술에 대해 이야기하고 싶은 모양이더군. 뭐라더라… 자네가 도와 줄 수 있을 거라던데 말이야. $B$B브루날 마을로 다시 돌아가 그의 이야기를 들어 보겠나? 아마 공짜 술은 배불리 얻어 먹을 수 있을 걸세.', '레욜트 발리브루와 대화해야 합니다.', NULL, NULL, NULL),
(417, '조종사의 복수', '힐델브의 일지에는 썩은발톱의 공격을 받았다고 적혀 있습니다. 힐델브는 그 짐승을 물리치려다 심한 상처를 입은 것 같습니다.$B$B시체의 상태를 보니 썩은발톱이 나중에 다시 돌아와 그를 죽인 것 같습니다.$B$B일지에 그의 마지막 유언이 남아 있습니다.$B$B썩은발톱에게 복수를!', '썩은발톱을 처치해야 합니다.그러고 나서 놈의 발톱과 힐델브의 일지를 조종사 해머풋에게 가져다주어야 합니다.', NULL, NULL, NULL),
(418, '텔사마 선지 소시지', '이곳 텔사마에서는 식당이 항상 손님들로 북적대지요. 아이들도 들락날락 거리고, 밤에는 힘든 하루 일과를 마친 채굴꾼들로 붐비고 말이에요. 우리 집은 선지 소시지가 유명하거든요. 당신은 아직 먹어 본 적 없지요?$B$B아마 그렇겠죠. 그런데 이곳에서는 열심히 일한 사람들만이 식사할 수 있어요. 당신이 아무리 멋진 $C|1이라고;라고; 해서 예외가 될 수는 없죠.$B$B곰 엉덩이살만 가져오세요. 나머지 재료들은 다 준비되어 있거든요. 제가 말한 재료만 가져오면 나머지는 이 비드라에게 맡겨 주세요!', '텔사마에 있는 비드라 하스스토브가 곰 엉덩잇살 8개를 가져다 달라고 했습니다.', NULL, NULL, NULL),
(419, '실종된 조종사', '내 친구이자 동료 증기 전차 조종사 모리 힐델브가 언덕에서 실종됐네. 우리 둘은 좋은 화약을 만드는 데 필요한 희귀한 광석을 찾아 나섰는데, 힐델브가 전차를 가파른 언덕으로 몰고 가다가 그만 고장이 나 버렸지.$B$B그래도 힐델브는 이 산에 그 광석이 분명히 있다면서, 내게 전차를 지키라고 하고선 광석을 찾으러 갔다네.$B$B그리고 며칠이 지난뒤 그 언덕에서 짐승의 울음소리 같은 것이 들려왔었네. 모리가 강한 친구긴 하지만, 그래도 걱정이 되어서 말이야.$B$B제발, 그를 찾아 주게.', '남부 관문 전초기지에 있는 조종사 해머풋이 조종사 힐델브를 찾아달라고 했습니다.', NULL, NULL, NULL),
(420, '그렐린의 보고서', '터널 안에 있는 사나운 트로그들은 누구든 가리지 않고 공격합니다. 하지만 당신 정도라면 큰 걱정은 없을 것 같습니다.$B$B세니르씨를 만나려면 카라노스로 가야 합니다. 터널을 빠져나가서 길을 따라가다 보면 카라노스에 도착하게 될 테니 거기서 세니르를 찾아보십시오.', '그렐린의 보고서를 카라노스에 있는 세니르 화이트비어드에게 전달해야 합니다.', NULL, NULL, NULL),
(421, NULL, NULL, NULL, NULL, '은빛소나무 숲의 공동묘지에 있는 달라 돈위버에게 가야 합니다.', NULL),
(422, NULL, NULL, NULL, NULL, '은빛소나무 숲의 공동묘지에 있는 달라 돈위버에게 가야 합니다.', NULL),
(423, NULL, NULL, NULL, NULL, '은빛소나무 숲의 공동묘지에 있는 달라 돈위버에게 가야 합니다.', NULL),
(424, NULL, NULL, NULL, NULL, '은빛소나무 숲의 공동묘지에 있는 달라 돈위버에게 가야 합니다.', NULL),
(425, '포악한 이바르', '제 오빠 퀸과 저에게 은빛소나무 숲을 정찰하는 임무가 주어졌었답니다. 그리고 하드렉님께 보고하기로 되어 있었고요. 그런데 농장을 가로질러 이동하던 중에 포악한 이바르로 불리는 구울에게 공격당해 아직 본격적인 정찰을 시작하지도 못했답니다.$B$B이바르에게서 도망치긴 했지만 오빠가 심각한 부상을 입고 말았어요. 가져다주신 물약 덕분에 오빠를 치료할 수 있었지만 오빠가 완전히 회복되기 전에 이바르가 다시 올지도 모릅니다.$B$B오빠가 안전하게 회복될 수 있도록 당신이 이바르를 처치해 주세요. 이바르는 저쪽 헛간에서 공격 기회를 엿보고 있어요.', '포악한 이바르를 처치하고 이바르의 해골을 이바르 호박밭에 있는 레인 요릭에게 가져가야 합니다.', NULL, '은빛소나무 숲에 있는 레인 요릭에게 가야 합니다.', NULL),
(426, NULL, NULL, NULL, NULL, '티리스팔 숲의 브릴에 있는 죽음경비병 딜링거에게 가야 합니다.', NULL),
(427, NULL, NULL, NULL, NULL, '티리스팔 숲의 브릴에 있는 집행관 자이건드에게 가야 합니다.', NULL),
(429, NULL, NULL, NULL, NULL, '은빛소나무 숲의 공동묘지에 있는 연금술사 렌퍼럴에게 가야 합니다.', NULL),
(431, '부름의 양초', NULL, NULL, NULL, NULL, NULL),
(432, NULL, NULL, NULL, NULL, '던 모로에 있는 현장감독 스톤브라우에게 가야 합니다.', NULL),
(433, NULL, NULL, NULL, NULL, '던 모로에 있는 원로원의원 메르 스톤할로우에게 가야 합니다.', NULL),
(434, '공격!', '첩보로봇을 변장시키고 나면 안으로 들어가서 라스코발에게 말을 걸게 될 거요. 첩보로봇은 경비병들을 문제없이 통과할 수 있을 거야.$B$B당신이 내게 줄 재료를 구해오는 동안 마르존에게 거짓 정보도 좀 흘려놓고 라스코발과 다시 만날 때가 되었다고 알려놓았지.$B$B라스코발은 그의 왕실근위병을 물러가게 하고 이 정원에서 마르존을 기다릴 것이오. 데피아즈단에 대해 얘기하는 기미가 보이거든 행동을 개시하라고. 경비병들이 돌아오기 전에 두 명 다 처치해야 하오!$B$B일이 끝나면 트리아스에게 얘기하라고.', '그레골 라스코발 경과 소리없는검객 마르존이 대화를 나눌때까지 정원에서 기다려야 합니다. 대화를 들은 후, 이들을 모두 처치하고 스톰윈드에 있는 엘링 트리아스에게 가야 합니다.', '레스코바르와 마르존의 대화를 엿듣다', '스톰윈드에 있는 엘링 트리아스에게 가야 합니다.', NULL),
(435, '엘런드 경호', '밖에 있는 늑대들은 떠날 생각을 하지 않고 날 사납게 노려보고 있소. 내가 저 문으로 한 발짝이라도 내딛으면 놈들이 덤벼들 거요. 놈들은 너무 굶주린 나머지 나를 맛있는 먹잇감으로 보고 있는 것이 분명하오.$B$B동료인 레인 요릭에게 보고서를 가져다줘야 하는데, 그러려면 아무래도 누군가 날 좀 보호해 줘야 할 것 같소.$B$B당신이 날 좀 도와주겠소? 늑대들이 너무 많아서 혼자서는 힘들지도 모르니 친구들이 더 있다면 도움이 될 것이오.', '레인 요릭이 있는 곳까지 늑대들을 물리치고 엘런드를 호위해야 합니다.', '에를란드는 라네 요릭에게 도달해야 합니다.', '은빛소나무 숲에 있는 레인 요릭에게 가야 합니다.', NULL),
(436, '아이언밴드의 발굴현장', '발굴조사단장 아이언밴드가 호수 동쪽의 고대 유적지에서 발굴 작업을 지휘하고 있소. 그런데 최근 작업 진행 속도가 더뎌지고 있소. 지금까지 우리가 제공해 준 보급품의 양을 고려하면 좀 이상한 일인데…$B$B아이언밴드는 결과를 중시하는 완고하고 정직한 드워프라서… 혹시 인부들이 그에게 반발하고 있는 건 아닌지 걱정이 되는군.$B$B아이언밴드의 발굴현장으로 가서 마그마 펠휴와 이야기해 보시오. 현장의 세부사항을 관리하니까 작업 속도가 느린 이유를 알고 있을 거요. 발굴현장으로 가려면 호수 남쪽 끝을 돌아 동쪽으로 가면 되오.', '탐험가 펠휴와 대화해야 합니다.', NULL, NULL, NULL),
(437, NULL, NULL, NULL, NULL, '은빛소나무 숲의 공동묘지에 있는 고위집행관 하드렉에게 가야 합니다.', NULL),
(439, '썩은가죽 일족의 단서', '시체들 사이에서 손 하나가 밖으로 나와 있습니다. 그 손은 여성의 것으로 역병으로 인한 반점이 있지만 비교적 생기 있어 보입니다.$B$B그리고 손가락에 반지가 끼워져 있습니다. 반지를 빼내 살펴보니 다음과 같은 문구가 새겨져 있습니다.$B$B≪델리아에게≫', '공동묘지에 있는 고위집행관 하드렉에게 델리아의 반지를 가져가야 합니다.', NULL, NULL, NULL),
(441, '랠리와 언더시티', '델리아에게는 지금 언더시티에 살고 있는 랠리라는 남편이 있었네. 브릴에 살았던 델리아가 이 반지의 주인이 맞다면 랠리가 알고 있을 거야.$B$B랠리는 언더시티 상업 지구 쪽에 있다네.', '랠리에게 델리아의 반지를 가져가야 합니다.', NULL, NULL, NULL),
(442, NULL, NULL, NULL, NULL, '은빛소나무 숲의 공동묘지에 있는 고위집행관 하드렉에게 가야 합니다.', NULL),
(443, NULL, NULL, NULL, NULL, '은빛소나무 숲의 공동묘지에 있는 연금술사 렌퍼럴에게 가야 합니다.', NULL),
(446, '까마귀발톱 쑤울', '이 영액은 까마귀발톱 쑤울이라는 내 옛 동료가 만든 거라네. 대전쟁 이전에 그는 젊고 전도유망한 마법사였지만 리치 왕이 권력을 장악하자 형제들을 배신하고 스컬지와 손을 잡았지.$B$B그가 아직 살아있다는 걸 몰랐는데다가 썩은가죽 일족의 수장으로 우릴 공격하고 있던 자가 그자라니!$B$B난 그의 마법 주문에 대해 많이 알고 있으니 그 마법에 대항할 물약을 만드는 걸 도울 수 있네. 이 두루마리를 연금술사 렌퍼럴에게 다시 가져가게. 그 안에 물약을 만들기 위해 필요한 주문이 적혀 있네.', '은빛소나무 숲 공동묘지에 있는 연금술사 렌퍼럴에게 베소르의 두루마리를 가져가야 합니다.', NULL, NULL, NULL),
(447, NULL, NULL, NULL, NULL, '언더시티의 연금술 실험실에 있는 수석 연금술사 파라넬에게 가야 합니다.', NULL),
(448, '하드렉에게 보고', '펜리스 섬을 공격하기 전에 고위집행관 하드렉님께 보고하게. 그분이 다른 정보나 필요한 장비를 주실지도 모르네.', '공동묘지에 있는 고위집행관 하드렉에게 보고해야 합니다.', NULL, NULL, NULL),
(449, '죽음추적자의 보고', '아직 퀸 오빠의 상처가 완치되지는 않았지만, 최대한 빨리 고위집행관 하드렉님께 보고를 드려야 해요. 포세이큰이 은빛소나무 숲을 장악하기 위해서 매우 중요한 정보에요.', '공동묘지에 있는 고위집행관 하드렉에게 죽음추적자 보고서를 가져가야 합니다.', NULL, NULL, NULL),
(450, NULL, NULL, NULL, NULL, '은빛소나무 숲의 공동묘지에 있는 연금술사 렌퍼럴에게 가야 합니다.', NULL),
(451, NULL, NULL, NULL, NULL, '언더시티의 연금술 실험실에 있는 수석 연금술사 파라넬에게 가야 합니다.', NULL),
(452, '장작나무 마을 매복', '오, 제때에 와줬군요!$B$B곧 장작나무 원로들이 돌아올 거예요. 아루갈이 성채에 머무르는 데는 다른 이유가 있답니다. 그는 원로들을 꼭두각시로 만들어 장작나무 마을 주민들을 마음대로 조종하면서 부하로 삼고 있어요. 장작나무 마을 원로들만 없다면, 아루갈의 부하 노릇을 하고 있는 마을 주민들도 모두 풀려나게 될 거예요.$B$B하지만 혼자서 모든 원로들을 상대할 수는 없으니 당신 도움이 필요해요. 나와 함께 싸워 주실 수 있나요? 우리 함께 실바나스 여왕님의 이름으로 원로들을 처단하자고요.', '죽음추적자 페를레이아를 도와 장작나무 마을 원로원들을 처치해야 합니다.', '페를레이아가 파이어우드 의회를 처치하는 것을 도와주세요', '은빛소나무 숲의 장작나무 마을에 있는 죽음추적자 페를레이아에게 가야 합니다.', NULL),
(454, '훌다르와 미란', '이제까지는 셋이 왔다갔다하면서 화약통을 운반했는데… 이제는 일을 나눠서, 미란이 운반하고 나는 여기서 다른 통들을 지켜야 하겠군.$B$B그런데 미란 혼자 운반하는 게 걱정돼서 말이야. 미란이 준비를 마치고 출발하면 그를 경호해주지 않겠나?', '미란과 대화해야 합니다.', NULL, NULL, NULL),
(455, NULL, NULL, NULL, NULL, '저습지의 메네실 항구에 있는 발스탁 아이언조에게 가야 합니다.', NULL),
(456, NULL, NULL, NULL, NULL, '그늘 협곡에 있는 관리인 일사레인에게 가야 합니다.', NULL),
(457, NULL, NULL, NULL, NULL, '그늘 협곡에 있는 관리인 일사레인에게 가야 합니다.', NULL),
(458, '숲의 수호자', '그대를 이곳으로 이끌어 주신 엘룬께 감사를! 숲에 사는 정령들의 속삭임을 통해 이상한 소식을 들었소.$B$B신비한 숲의 수호자 타린드렐라가 그늘 협곡으로 다시 돌아왔다고 하오. 텔드랏실의 축복 전부터는 숲에서 이 드리아드의 존재를 느끼지 못했었소. 그녀가 이 땅에 돌아왔다면 필시 무언가 문제가 있는 것이 분명하오.$B$B타린드렐라를 찾아 그녀가 우리 숲에 온 이유를 알아내시오. 파수꾼의 보고에 의하면 알드랏실 남서쪽에서 그녀를 보았다고 하오.', '타린드렐라라고 알려진 드리아드를 찾아야 합니다.', NULL, NULL, NULL),
(459, NULL, NULL, NULL, NULL, '알드랏실에 있는 델리라에게 가야 합니다.', NULL),
(460, '분리된 몸과 머리', '당신은 썩은가죽 일족은 아닌 것 같으니 다행이군. 난 완전히 희망을 잃었소.$B$B난 쑤울의 수석 부관이자 경호원이었던 알라리크라고 하오. 쑤울은 끔찍한 역병에서 나를 보호하기 위해 마법을 사용했는데 그가 사용한 주문 때문에 난 살지도 죽지도 못하게 되어 버렸소. 쑤울이 망할 놈의 썩은가죽 놀을 만들어낸 후에 나를 배신한 거야!$B$B제발 나를 내 몸이 있는 곳으로 데려가 주시오. 놀들이 펜리스 요새 근처에 있는 마구간 앞에 내 몸을 묻었을 거요.', '알라리크의 머리를 그의 무덤으로 데려가야 합니다.', NULL, NULL, NULL),
(462, '[미사용]', '자네말고도 던 알가즈에 정찰병을 두 명 더 보냈지만 그중 한 명만 돌아왔소. 그 정찰병이 알아낸 사실은 이렇소.$B$B용아귀 부족이 메네실 항구로 통하는 육로를 차단하기 위해, 부관 중 하나인 마룩 웜스케일이라는 자를 알가즈로 보내 오크 병사들을 모으고 있다고 하오.$B$B따라서 즉각 놈들을 저지해야 하오. 마룩을 제거하고 메네실 항구에 있는 발스탁 아이언조에게 보고하시오.$B$B마룩의 본거지는 던 알가즈의 두 번째 터널과 세 번째 터널 사이의 연못 건너에 있는 작은 동굴이라고 하오. 던 알가즈를 지나 길을 따라 서쪽으로 가면 메네실에 다다를 수 있을 거요.', '마루크 웜스케일을 처치해야 합니다.이후 메네실 항구에 있는 발스탁 아이언조에게 보고해야 합니다. 퀘스트.', NULL, '저습지에 있는 발스탁 아이언조에게 가야 합니다.', NULL),
(464, NULL, NULL, NULL, NULL, '저습지의 메네실 항구에 있는 경비대장 스타우트피스트에게 가야 합니다.', NULL),
(466, NULL, NULL, NULL, NULL, '던 모로의 스틸그릴의 정비소에 있는 조종사 스톤기어에게 가야 합니다.', NULL),
(469, '가죽 배달', '안녕하시오!$B$B메네실 쪽으로 가는 것 같아 보이지는 않는군… 여유가 있다면 메네실에 한번 들러 보시기 바라오. 필요한 물건을 구입하는 건 물론이고 맥주 한 잔 하면서 쉬어가기에도 더할 나위 없이 좋은 곳이지.$B$B메네실 쪽으로 갈 거라면 무두장이 제임스 할로란에게 이 악어 껍질 한 묶음을 가져다주지 않겠소?$B$B내가 직접 가고 싶지만 요즘 우리 집사람 심기가 상당히 불편한 것 같아서 얼굴을 마주치기가 좀 그렇소이다.', '메네실 항구의 무두장이 제임스 할로란에게 악어 껍질 한 묶음을 전달해야 합니다.', NULL, NULL, NULL),
(470, NULL, NULL, NULL, NULL, '저습지의 메네실 항구에 있는 시다에게 가야 합니다.', NULL),
(471, NULL, NULL, NULL, NULL, '저습지의 메네실 항구에 있는 제임스 할로란에게 가야 합니다.', NULL),
(473, '경비대장 스타우트피스트에게 보고', '용아귀 오크는 알가즈뿐 아니라 다른 지역까지 공격하고 있소. 그래서 스타우트피스트 경비대장님께서 전투에 참가해 오크와 싸울 지원자들을 모집하라고 하셨소. 생각이 있다면 선장님을 만나보시오. 스타우트피스트 경비대장님은 요새 안에 계시오.', '경비대장 스타우트피스트와 대화해야 합니다.', NULL, NULL, NULL),
(474, '네크로쉬 처치', '투석기를 불태웠으니 이제 족장 네크로쉬를 찾아 처치해야 합니다.', '족장 네크로쉬를 처치해야 합니다.그런 다음 그 증거로 경비대장 스타우트피스트에게 네크로쉬의 머리카락을 가져가야 합니다.', NULL, '저습지의 메네실 항구에 있는 경비대장 스타우트피스트에게 가야 합니다.', NULL),
(478, '지도와 룬문자 펜던트', '상자에서 재빨리 펜던트를 꺼내고 뚜껑을 닫습니다.', '공동묘지에 있는 어둠의 사제 알리스터에게 룬문자 펜던트를 가져가야 합니다.', NULL, NULL, NULL),
(479, NULL, NULL, NULL, NULL, '은빛소나무 숲의 공동묘지에 있는 어둠의 사제 알리스터에게 가야 합니다.', NULL),
(480, NULL, NULL, NULL, NULL, '은빛소나무 숲의 공동묘지에 있는 어둠의 사제 알리스터에게 가야 합니다.', NULL),
(481, '달라의 분석', '저기 있는 달라 돈위버에게 펜던트를 가져가 보게. 그가 마술사들의 계획을 밝혀낼 수 있을지도 모르네.', '공동묘지에 있는 달라 돈위버에게 룬문자 펜던트를 가져가야 합니다.', NULL, NULL, NULL),
(482, '달라란의 의도', '그렇지! 내가 이걸 어떻게 지금까지 까맣게 잊고 있었지?$B$B호박색 농장에는 잠자고 있는 초원 에너지의 원천이 있기 때문에 키린 토가 일찌감치 주목하고 있던 지역 중 하나요. 마법사들은 에너지의 중심을 부활시켜 뭔가 더 큰 목적에 그 에너지를 사용하려는 게 틀림없소. 이건 절대 그냥 넘길 수 있는 문제가 아니오.$B$B그 지역의 에너지를 활성화하는 데는 엄청난 양의 마법이 필요할 테니 마술사들에게서 펜던트를 빼앗으면 놈들의 계획을 지연시킬 수 있을 것이오. 어서 이 정보를 알리스터에게 전하시오. 그럼 그가 조치를 취할 것이오.', '공동묘지에 있는 어둠의 사제 알리스터와 대화해야 합니다.', NULL, NULL, NULL),
(483, NULL, NULL, NULL, NULL, '돌라나르에 있는 아스리다스 베어맨틀에게 가야 합니다.', NULL),
(484, NULL, NULL, NULL, NULL, '저습지의 메네실 항구에 있는 제임스 할로란에게 가야 합니다.', NULL),
(486, NULL, NULL, NULL, NULL, '돌라나르에 있는 아스리다스 베어맨틀에게 가야 합니다.', NULL),
(487, NULL, NULL, NULL, NULL, '돌라나르 서쪽에 있는 파수꾼 아마라 나이트워커에게 가야 합니다.', NULL),
(488, NULL, NULL, NULL, NULL, '돌라나르 외곽에 있는 젠 파울후프에게 가야 합니다.', NULL),
(489, NULL, NULL, NULL, NULL, '돌라나르 외곽에 있는 젠 파울후프에게 가야 합니다.', NULL),
(490, '<미사용>', '다르나서스 의회의 명령에 따라 나무옹이 일족에게 현상금을 붙이겠습니다. 그들은 더 이상 숲의 친구가 아니죠. 녀석들은 타락한 나머지 우리 종족과 숲의 생명체들에게 걷잡을 수 없는 위협이 되어 버렸어요.$B$B의회의 판결에 따라 칼리다르에서 펄볼그를 제거하면 그에 대한 보상을 받게 될 겁니다. 일을 제대로 처리했다는 증거로 녀석들의 송곳니를 내게 가지고 오세요.', '다르나서스밖에 있는 샤일라 나이트브리즈가 나무옹이 송곳니 20개를 가져다 달라고 했습니다.', NULL, '텔드랏실에 있는 파수꾼 샤일라 나이트브리즈에게 가야 합니다.', NULL),
(491, '베소르에게 전할 마법봉', '쑤울은 아주 오래전에 그와 두 명의 동료가 지니고 있던 수습생 마법봉을 결합하여 마법봉을 만들었다고 말했소. 이 마법봉이 그들에겐 우정의 상징이었던 거였지만 쑤울은 그 마법봉을 하찮게 여기면서도 다른 친구들이 소유하는 것을 원치 않았지. 그래서 그는 마법봉을 훔쳐 바로 이곳 펜리스 요새에 숨겼소.$B$B자, 이 마법봉을 쑤울의 옛 친구 중 한 명인 베소르 아이스샤드에게 가져다주시오. 아마 베소르는 마법봉을 원하고 있을 것이오.', '언더시티의 마법 지구에 있는 베소르 아이스샤드에게 결합된 마법봉을 가져가야 합니다.', NULL, NULL, NULL),
(492, '새로운 역병', '경비병들 말로는 멍청한 드워프 산악경비대원 한 녀석이 잡혀 있다고 하더군. 죽음경비병들은 포로의 처분이 결정될 때까지 교수대끝 선술집 지하실에 가둬 두지.$B$B내가 특별히 준비한 이 음료를 산악경비대 포로가 얼마나 맛있게 마시는지 구경해 보지 않겠소? 이 음료로 말하자면… 음, 어둠의 여왕께서 아제로스를 위해 어떤 일을 계획하고 계신지 암시하는 것이지.', '산악경비대 포로에게 요한의 특별조제약을 전해야 합니다.', NULL, NULL, NULL),
(494, '공격 개시', '$C님, 잘 들으세요.$B$B나는 언덕마루 마을을 조사하기 위해 이곳에 파견되었습니다. 당신이 지금 즉시 타렌 제분소의 고위집행관 다살리아님께 내 보고를 전해 주어야겠습니다. 고위 집행관님께 죽음추적자 레시가 다음과 같은 전갈을 전했다고 하면 됩니다.$B$B≪서쪽에서 갈까마귀 울음소리가 손짓하고 있다.≫$B$B표지판을 잘 살펴보면서 동쪽으로 길을 따라가시기 바랍니다. 자, 어서 서두르세요! 매우 시급한 사안이니 지금 즉시 타렌 제분소로 떠나야 합니다.', '타렌 제분소로 가서 고위집행관 다살리아에게 죽음추적자 레시의 전갈을 전해야 합니다.', NULL, NULL, NULL),
(495, '의지의 왕관', '무그톨과 그의 오우거 부대가 실바나스 여왕님을 위해 의지의 왕관을 찾는 임무를 띠고 알터랙으로 떠났었지. 그런데 공교롭게 그 바보 같은 자들이 왕관을 찾아오는 대신에 소유욕에 불타오르고 말았어. 오우거들은 값져 보이는 것만 보면 사족을 못 쓰는 모양이더군.$B$B녀석의 바보 같은 행동이 결국 큰 문제를 일으키고 말았지. 의지의 왕관을 가지려는 욕심 때문에 자신의 직분을 잊고 감히 실바나스 여왕님께 대항했던 것이야.$B$B어둠의 여왕님께서는 그자를 여왕님께 반하는 자들에게 본보기로 삼으려 하고 계시다. 언덕마루의 타렌 제분소로 가서 나의 부관인 멜리사라에게 이 사태를 전하라.', '언덕마루 구릉지의 타렌 제분소에 있는 멜리사라에게 보고해야 합니다.', NULL, NULL, NULL),
(496, NULL, NULL, NULL, NULL, '언덕마루 구릉지의 타렌 제분소에 있는 연금술사 라이던에게 가야 합니다.', NULL),
(497, '<미사용>', '어릴 때 던홀드 요새에서 검투사로 크면서 보모의 딸인 타레사와 친해졌지. 그녀는 그 몹쓸 블랙무어 녀석의 여자였어.$B$B지난 일이지만, 언덕마루에서 인간들의 동태를 보고받으니 그 시절이 생각나는군. 그 지역의 조사를 위해 소규모 부대를 파견하면서, 타레사가 내게 준… 물건을 찾아오라고 지시했도다.$B$B아무런 성과가 없을 게 뻔하지만, 그래도 혹시 모르지…$B$B지금쯤 그들이 돌아왔어야 하는데 아무 소식이 없군. 그대가 타렌 제분소로 가서 조사를 해주게.', '타렌 제분소로 가서 스랄의 파견 부대가 어떻게 되었는지 알아내야 합니다.', NULL, NULL, NULL),
(498, NULL, NULL, NULL, NULL, '언덕마루 구릉지의 타렌 제분소에 있는 크루스크에게 가야 합니다.', NULL),
(499, '괴로움의 비약', '이제 이 재료들을 혼합하기만 하면 내가 괴로움의 비약이라 이름 붙인 물질이 곧 완성될 것이오.$B$B자, 보라고! 완성되었어! 이 끔찍한 구릉지에서 무료한 날들을 달래기엔 세상에 작은 고통을 선사하는 것만큼이나 좋은 일도 없지.$B$B그럼, 우리 독약의 효과를 한번 확인해 볼까? 어둠의 여왕님께서 인간과 스컬지를 위해 계획해 온 독약을 내 조수 개구리 움피에게 먹이도록 하시오.', '개구리 움피에게 괴로움의 비약을 먹여야 합니다.', NULL, NULL, NULL),
(500, NULL, NULL, NULL, NULL, '언덕마루 구릉지의 남녘해안에 있는 치안대장 레드패스에게 가야 합니다.', NULL),
(501, NULL, NULL, NULL, NULL, '언덕마루 구릉지의 타렌 제분소에 있는 연금술사 라이던에게 가야 합니다.', NULL),
(503, NULL, NULL, NULL, NULL, '알터랙 산맥의 고원에 있는 골디르에게 가야 합니다.', NULL),
(504, NULL, NULL, NULL, NULL, '언덕마루 구릉지의 남녘해안에 있는 치안대장 레드패스에게 가야 합니다.', NULL),
(505, NULL, NULL, NULL, NULL, '언덕마루 구릉지의 남녘해안에 있는 집정관 헨리 말레브에게 가야 합니다.', NULL),
(506, '블랙무어의 유산', '며칠 전, 비밀결사대의 우두머리가 날 찾아왔었네. 앨리덴 페레놀드란 자인데, 자기가 이 땅의 주인이라고 하더군. 그자는 자신에게 저항하는 오크들을 노예로 삼을 계획이라고 털어놓았네. 그의 아버지이자 스승인 저주스러운 블랙무어가 계획했던 것처럼 말이야.$B$B더 중요한 사실은 그가 엘리사라는 이름의 가녀린 부인을 함께 데려왔다는 점이야. 그녀의 목에 대족장님께서 원하시는 펜던트가 걸려 있었네.$B$B자, 이제 난 여기서 볼일을 끝낸 후에 내갈 길을 가야겠으니 어서 이 소식을 전하도록 하게.', '타렌 제분소에 있는 크루스크에게 골디르가 수집한 정보를 전해야 합니다.', NULL, NULL, NULL),
(507, NULL, NULL, NULL, NULL, '알터랙 산맥의 고원에 있는 엘리사에게 가야 합니다.', NULL),
(508, '타레사의 선물', '펜던트 말인가요? 그거라면 기꺼이 드리지요… 자, 가져가세요! 그에 대한 추억은 더 이상 간직하고 싶지 않으니까… 다만 제발 아무 소란도 일으키지 말고 가 주세요…', '언덕마루 구릉지의 타렌 제분소에 있는 크루스크에게 타레사의 펜던트를 가져가야 합니다.', NULL, NULL, NULL),
(509, NULL, NULL, NULL, NULL, '언덕마루 구릉지의 타렌 제분소에 있는 연금술사 라이던에게 가야 합니다.', NULL),
(510, '불길한 예감이 드는 계획서', '이 문서들 중에 보급품 요청 목록이 있습니다. 그 목록에는 식량, 무기, 의류 등 평범한 물품 외에도 가면, 기름, 독 등 특이한 물품이 포함되어 있습니다.$B$B하지만 가장 중요한 점은 보급품 요청이 상당히 긴급하다는 사실입니다. 이 물품은 ''남녘해안 공격 일급 작전''이라 이름 지어진 작전을 시작하기 위해 곧 사용될 예정입니다.', '남녘해안에 있는 집정관 말레브에게 불길한 예감이 드는 계획서를 가져가야 합니다.', NULL, NULL, NULL),
(511, '암호화된 편지', '탁자 위에 있는 편지 중 하나는 암호로 쓰여 있어 내용을 알 수 없습니다.', '남녘해안에 있는 현자 딥스에게 복잡하게 암호화된 편지를 가져가야 합니다.', NULL, NULL, NULL),
(512, '지휘부 처치', '비밀결사대의 지휘부가 남녘해안 함락에 혈안이 되어 걱정이네. 놈들이 계획을 실행에 옮기기 전에 놈들의 지휘부에 결정타를 안겨야 하네.$B$B북쪽 알터랙 산맥에 있는 스트란브래드의 폐허로 가 보게. 비밀결사대가 그 지역을 본거지로 삼고 있는 것 같네.$B$B그리고 예전 알터랙의 귀족들이 이 살인 집단을 이끌고 있다는 사실도 이미 밝혀졌다네. 지휘부는 아마 일반 비밀결사대 일당과 똑같은 모습을 하고 숨어 있겠지만, 놈들이 낀 인장 반지로 구별할 수 있을 걸세.$B$B그 인장 반지들을 내게 가져다주게.', '남녘해안에 있는 집정관 말레브에게 알터랙 인장 반지 7개를 가져가야 합니다.', NULL, '언덕마루 구릉지의 남녘해안에 있는 집정관 헨리 말레브에게 가야 합니다.', NULL),
(513, '죽음의 비약', '아무 낙 없이 또 하루가 지나간다고 여기던 차에 당신이 내게 멋진 진흙주둥이꽃을 가져다주었군.$B$B자, 그럼 먼저 꽃송이들을 잘 섞어 질 좋은 합성물을 만든 다음에… 언더시티에 계신 수석 연금술사 파라넬님의 부패 콜로이드 용액을 섞기만 하면 아주 재미있는 일이 일어날 것이오.$B$B자, 이 진흙주둥이 합성물을 즉시 수석 연금술사 파라넬님께 전하도록 하시오.', '언더시티에 있는 수석 연금술사 파라넬에게 진흙주둥이 합성물을 가져가야 합니다.', NULL, NULL, NULL),
(514, '스톰파이크에게 보내는 편지', '아이언포지에서 일하고 있는 내 동료가 아마 이 편지를 해독할 수 있을 거요. 아이언포지에 있는 탐험가의 전당에 있는 도서관으로 가서 발굴조사단장 스톰파이크를 만나 보시오. 그에게 내가 보냈다고 말하고 편지를 보여 주시오. 검은바위 첨탑의 북부에서 이 편지를 읽을 수 있는 이가 있다면 그건 틀림없이 그 친구밖에 없을 거요.', '아이언포지에 있는 발굴조사단장 스톰파이크에게 복잡하게 암호화된 편지를 가져가야 합니다.', NULL, NULL, NULL),
(515, NULL, NULL, NULL, NULL, '언덕마루 구릉지의 타렌 제분소에 있는 연금술사 라이던에게 가야 합니다.', NULL),
(516, NULL, NULL, NULL, NULL, '은빛소나무 숲의 공동묘지에 있는 어둠의 사제 알리스터에게 가야 합니다.', NULL),
(517, '죽음의 비약', '드디어 이 새로운 비약을 시험해 볼 준비가 됐소. 하지만 하찮은 개구리나 개에게 이 강하고 훌륭한 역병을 낭비할 필요는 없겠지? 그보다 실바나스 여왕님의 이름으로 진정한 실험의 재미를 맛보도록 하지.$B$B던 가록으로 가시오. 저 고약한 드워프들의 병영이 어디 있는지는 알고 있겠지? 놈들의 신디거 스타우트 맥주통을 훔쳐다 주시오. 그러면 나와 함께 신나는 죽음의 향연을 구경할 수 있을 것이오.', '타렌 제분소에 있는 연금술사 라이던에게 신디거 스타우트 맥주통을 가져가야 합니다.', NULL, '언덕마루 구릉지의 타렌 제분소에 있는 연금술사 라이던에게 가야 합니다.', NULL),
(518, '의지의 왕관', '무그톨과 그의 산사태 오우거들이 알터랙 폐허를 짓밟아 왔습니다. 하지만 오우거의 수를 줄이지 않고는 무그톨을 단죄하기 힘들 거예요.$B$B그러니까 먼저 놈들의 전력을 약화시킨 후에 작전을 진행해야 합니다.$B$B알았나요? 자, 어서 가보도록 하세요.', '타렌 제분소에 있는 멜리사라를 위해 산사태 싸움꾼 10마리를 처치해야 합니다.', NULL, '언덕마루 구릉지의 타렌 제분소에 있는 멜리사라에게 가야 합니다.', NULL),
(519, NULL, NULL, NULL, NULL, '언덕마루 구릉지의 타렌 제분소에 있는 멜리사라에게 가야 합니다.', NULL),
(520, '의지의 왕관', '무그톨의 부관들을 처치했으니 이제 무그톨을 처치하고 의지의 왕관을 가져오는 일만 남았군요. 틀림없이 쉽게 왕관을 내놓지는 않을 겁니다. 그 일당이 사라졌으니 아마 무그톨도 당신이 올 거라고 예상하고 있을 겁니다.$B$B무그톨을 찾아서 처치하세요. 그런 다음 그의 머리카락과 의지의 왕관을 가져오세요. 산사태 일족의 저항도 이것으로 종지부를 찍게 될 겁니다.', '무그톨을 처치하고 그 증거로 그의 머리카락과 의지의 왕관을 타렌 제분소에 있는 멜리사라에게 가져가야 합니다.', NULL, '언덕마루 구릉지의 타렌 제분소에 있는 멜리사라에게 가야 합니다.', NULL),
(521, '의지의 왕관', '이제 의지의 왕관을 언더시티에 계신 샬린드라님께 가져가기만 하면 되는군요. 그러면 실바나스 여왕님께 왕관을 전해 드릴 겁니다. 경고하겠는데 무그톨과 같은 꼴을 당하고 싶지 않다면, 사사로운 목적으로 왕관을 이용할 생각은 안 하는 게 좋을 겁니다.', '언더시티에 있는 샬린드라에게 의지의 왕관을 가져가야 합니다.', NULL, NULL, NULL),
(522, '청부업자의 계약서', '집정관 헨리 말레브 암살 계약서입니다. 이 암살 계약서는 독특한 인장 반지가 찍힌 붉은 밀랍으로 봉인되어 있습니다.', '남녘해안에 있는 집정관 말레브에게 청부업자의 계약서를 가져가야 합니다.', NULL, NULL, NULL),
(523, '바르두스 남작 심판', '자네가 발견한 계약서는 한때 알터랙 왕국의 귀족이었으나 잔인한 짓을 일삼는 냉혈한으로 알려진 바르두스 남작이 서명한 것이네. 바르두스 남작 같은 자가 배후에 있다는 건 이상할 것도 없는 일이지.$B$B자네가 그자를 찾아서 정의의 이름으로 심판을 해 주게나. 그자는 스트란브래드의 폐허나 그 북쪽의 계곡에 있는 것으로 파악되는 비밀결사대 소굴에 있을 걸세.', '바르두스 남작을 처치하고 그 증거로 그의 머리카락을 남녘해안에 있는 집정관 말레브에게 가져가야 합니다.', NULL, '언덕마루 구릉지의 남녘해안에 있는 집정관 헨리 말레브에게 가야 합니다.', NULL),
(524, '죽음의 비약', '옆 건물에 죽음경비병들이 사로잡힌 농부들을 인질로 감금해 놓고 있소. 고위집행관 다살리아님께서는 그 포로들 가운데 스톰윈드의 군사 전략가 중 하나가 숨어 있다는 것을 알아채셨지. 그런데 그 군사 전략가 녀석이 어젯밤 역병지대에서 죽은 채로 발견된 모양이오. 항상 날 배려해 주시는 다살리아님께서 이 포로들을 내 손에 맡기셨소.$B$B그러니 이제 그 농부 녀석들에게 죽음의 파티를 선사할 때요. 옛 영광이 다시 찾아온 것 같지 않소?$B$B이 오염된 맥주통을 녀석들이 수감된 방의 양탄자 위에 가져다 놓으시오. 모두 이 역병 맥주를 맛보기를!', '오염된 맥주통을 사로잡힌 농부들이 있는 방의 양탄자 위에 가져다 놓아야 합니다.', NULL, NULL, NULL),
(525, '깊어지는 의문', '편지를 해독했지만 무슨 뜻인지는 잘 모르겠군. 이 편지를 알터랙 구릉지대에 있는 도적들에게서 발견했다고 했소? 정말 이상해…$B$B이걸 남녘해안의 집정관께 가져가시오. 비록 이 편지 내용이 모호하기는 하지만 남녘해안이 알터랙에서 가장 가까운 마을이니, 혹시 위험한 일이 발생할 조짐이 있는 거라면 남녘해안의 집정관이 알고 있어야 할 테니까 말이오.', '남녘해안에 있는 집정관 말레브에게 해독된 편지를 가져가야 합니다.', NULL, NULL, NULL),
(526, '라이트포지 주괴', '그 상자에서 발견한 라이트포지 주괴 하나만으로는 쓸만한 물건은 만들 수 없네.$B$B그러니 그곳으로 다시 가서 좀 더 찾아 와야 할 거야. 아마 그 난파선 주위에 있는 멀록들이 라이트포지 주괴를 가지고 있을 걸세.', '라이트포지 주괴 5개를 모은 다음 저습지에 있는 글로린 스틸브라우에게 가야 합니다.', NULL, '저습지의 메네실 항구에 있는 글로린 스틸브라우에게 가야 합니다.', NULL),
(527, NULL, NULL, NULL, NULL, '언덕마루 구릉지의 타렌 제분소에 있는 고위집행관 다살리아에게 가야 합니다.', NULL),
(528, '언덕마루 전투', '북쪽 농장이 공격당했다는 소식으로 인간 마을 주민들이 공포에 떨고 있다더군. 아주 훌륭해.$B$B죽음추적자의 보고에 따르면 소작농들이 언덕마루 남쪽 농장으로 피난하고 있다는군. 바보 같은 놈들이 과수원으로 숨으면 안전할 거라 생각하는 모양이야.$B$B가서 놈들이 얼마나 어리석은지 일깨워 주고 오라고. 언덕마루 농장으로 돌아가서 숨어 있는 농부들을 찾아내도록 하게. 그리고 우리 어둠의 여왕님의 이름으로 놈들을 처단하도록.$B$B이상!', '언덕마루 소작농 15명을 처치한 다음 타렌 제분소에 있는 다살리아에게 돌아와 보고해야 합니다.', NULL, '언덕마루 구릉지의 타렌 제분소에 있는 고위집행관 다살리아에게 가야 합니다.', NULL),
(529, '언덕마루 전투', '예상치 못한 상황이 발생했네. 언덕마루의 인간들이 저항을 꾀하고 있는 모양이야. 마을의 대장장이가 언덕마루 주민들에게 무기를 공급하고 있는 것 같으니 모든 무기 공급선을 차단해야 하네.$B$B자네의 임무는 대장장이 베링턴을 처치하는 것이야. 놈의 수습생들도 함께 처치하고 그곳에 있는 동안 철괴 상자를 가지고 오는 것도 잊지 말도록 하게. 그 보급품은 우리가 언덕마루를 점령한 후 남녘해안 공격을 감행할 때 유용하게 사용할 수 있을 거야.', '대장장이 베링턴과 언덕마루 수습대장장이 4명을 처치해야 합니다.철괴 상자를 찾은 다음 타렌 제분소에 있는 다살리아에게 돌아와 보고하십시오.', NULL, '언덕마루 구릉지의 타렌 제분소에 있는 고위집행관 다살리아에게 가야 합니다.', NULL),
(530, NULL, NULL, NULL, NULL, '언더시티에 있는 랠리 앤드리언에게 가야 합니다.', NULL),
(531, '바이린의 복수', '그런 물건은 원정순찰대 오두막에 가지고 오지 마시오… 불결해, 오금이 저릴 정도로… 재수 없고… 역겹다고!$B$B제발 가지고 나가요. 그런 끔찍한 건 아무도 보고 싶어하지 않을 테니까. 진짜!', '원정순찰대 오두막에 있는 바이린 스위프트윈드에게 큰곰 숯검댕이의 머리를 가져가야 합니다.', NULL, NULL, NULL),
(532, '언덕마루 전투', '언덕마루 마을이 혼란에 빠졌으니 이제 곧 함락될 것이야. 하지만 구릉지에서 쓰레기 같은 인간들이 영원히 제거될 때까지 공격의 고삐를 늦춰서는 안 되네.$B$B인간들에게 압승을 거두긴 했지만 이들이 지휘부를 중심으로 재집결하여 저항을 계속하고 있어. 이들을 지휘하고 있는 집정관 번사이드와 마을 의회의 원로를 제거해야 하네. 또한 그들이 하늘같이 떠받드는 성명문인 언덕마루 선언문도 파괴해 버리고, 언덕마루 마을 기록부를 빼내 오게.', '집정관 번사이드와 언덕마루 원로 4명을 처치해야 합니다. 언덕마루 선언문을 파괴하고 언덕마루 마을 기록부를 빼내 와야 합니다. 그런 다음 타렌 제분소에 있는 다살리아에게 돌아와 보고하십시오.', NULL, '언덕마루 구릉지의 타렌 제분소에 있는 고위집행관 다살리아에게 가야 합니다.', NULL),
(533, NULL, NULL, NULL, NULL, '언덕마루 구릉지의 타렌 제분소에 있는 크루스크에게 가야 합니다.', NULL),
(534, '[미사용]', NULL, NULL, NULL, NULL, NULL),
(535, '발릭', '으… 부상으로 다 죽어가는 마당에 적까지 만나는군.$B$B어쨌든 당신은 날 죽이겠지만, 그 전에 당신네 종족이 마시는 남녘해안 스타우트 맥주를 좀 가져다준다면 당신이 원하는 정보를 주겠소.', '비밀결사대 야영지에 있는 발릭에게 남녘해안의 스타우트 맥주 한 잔을 가져가야 합니다.', NULL, '알터랙 산맥의 소페라 절벽에 있는 심복 발릭에게 가야 합니다.', NULL),
(536, '해안의 위협', '스톰윈드 근위병에서 남녘해안 같은 촌구석으로 전출되다니… 밤낮으로 항구의 비린내가 진동하는 이런 곳으로 말이오.$B$B저 늙은 대장 레드패스에 대해서는 말도 꺼내지 마시오. 나더러 멀록을 상대하라니. 하! 기가 차서… $B$B난 서부 해안에 있는 저 거대한 변종 물고기 주머니 속에 제 발로 걸어 들어갈 생각은 없단 말이오. 그래서 말인데, 당신이 나 대신 가서 놈들을 좀 처치해 준다면 정말 고맙겠소.', '남녘해안에 있는 부관 파렌 오리넬이 너덜지느러미 바다사냥꾼 10마리와 너덜지느러미 점쟁이 10마리를 처치해 달라고 했습니다.', NULL, '언덕마루 구릉지의 남녘해안에 있는 부관 파렌 오리넬에게 가야 합니다.', NULL),
(537, '어둠의 의회', '자네가 가져온 편지는 아르거스 재림회 회원인 나가즈라는 자가 작성한 것이라네. 나도 아르거스 재림회가 어떤 조직인지는 모르지만, 비밀결사대와 연합했다면 위험한 조직이 틀림없네. 자네가 편지에 언급된 나가즈와 아르거스 재림회 어둠마법사를 찾아서 처치해 주게나.$B$B비밀결사대의 세력이 가장 강한 지역인 고원을 수색해 보게. 스트란브래드 북쪽으로 가면 되네.$B$B운이 따라 준다면, 거기서 아르거스 재림회의 사절을 찾을 수 있을 게야.', '아르거스 재림회 어둠마법사 4명을 처치해야 합니다.그리고 나가즈를 처치한 증거로 그의 머리카락을 남녘해안에 있는 집정관 헨리 말레브에게 가져가야 합니다.', NULL, '언덕마루 구릉지의 남녘해안에 있는 집정관 헨리 말레브에게 가야 합니다.', NULL),
(539, '언덕마루 전투', '언덕마루 마을 기록부를 보면 청금석 광산이 얼라이언스 손에 넘어간 것으로 되어 있군. 게다가 그 광산은 얼라이언스의 무기 생산에 필요한 철 광석의 주공급원이지.$B$B언덕마루 마을에 결정적인 타격을 주긴 했지만, 여전히 얼라이언스는 청금석 광산을 철저히 방어하고 있는 실정이야.$B$B청금석 광산은 언덕마루 남쪽에 있네. 광산으로 가서 본즈라는 인간 현장감독을 처치하도록 하고 그가 지휘하는 광부들도 함께 처치해야 해. 이번 작전으로 얼라이언스에 커다란 타격을 줄 수 있을 걸세.', '현장감독 본즈와 언덕마루 광부 10명을 처치한 다음 타렌 제분소에 있는 다살리아에게 돌아와 보고해야 합니다.', NULL, '언덕마루 구릉지의 타렌 제분소에 있는 고위집행관 다살리아에게 가야 합니다.', NULL),
(540, NULL, NULL, NULL, NULL, '언덕마루 구릉지의 남녘해안에 있는 현자 딥스에게 가야 합니다.', NULL),
(541, NULL, NULL, NULL, NULL, '언덕마루 구릉지의 타렌 제분소에 있는 고위집행관 다살리아에게 가야 합니다.', NULL),
(543, NULL, NULL, NULL, NULL, '스톰윈드의 스톰윈드 왕궁에 있는 백작 레밍턴 리지웰에게 가야 합니다.', NULL),
(544, NULL, NULL, NULL, NULL, '언덕마루 구릉지의 타렌 제분소에 있는 학자 워딘 보이드글레어에게 가야 합니다.', NULL),
(545, '달라란 순찰', '달라란의 마법사들이 시가지 중심부에 거대한 마법의 반구를 만들었소. 이 난세에 자신을 보호하고자 만들었다고 하는 이도 있고, 그저 연구와 구상에 몰두하기 위한 것이라 말하는 이도 있지.$B$B나야 뭐 이유에는 관심도 없지만… 내 관심은 반구가 아니라 그 폐허가 된 도시 외곽에 귀중한 마법의 보물이 숨겨져 있을지도 모른다는 사실이야.$B$B하지만 마법사들과 그들의 하수인인 노예 바위 정령들이 그 지역을 순찰하고 있다오. 그러니 당신이 그들을 처치해서 놈들의 숫자를 줄이고 내게 다시 돌아와 주시오.', '달라란 소환사 6명과 노예 바위 정령 12마리를 처치한 다음 타렌 제분소에 있는 학자 워딘 보이드글레어에게 가야 합니다.', NULL, '언덕마루 구릉지의 타렌 제분소에 있는 학자 워딘 보이드글레어에게 가야 합니다.', NULL),
(546, '죽음의 전리품', '당신이 다살리아 님을 도와 언덕마루에 있는 인간과 전쟁을 벌였다고 들었습니다. 정말 부럽군요…$B$B인간을 처치하고, 마을을 약탈하고, 또 죄 없는 주민을 공포에 떨게 하고… 당신이 그런 재미를 보는 동안 나는 이곳 타렌 제분소에 처박혀 경비나 서고 있었단 말입니다.$B$B아마 당신은 나처럼 늙은 죽음경비병을 불쌍히 여겨 주겠지요? 보다시피 난 인간의 해골을 모으고 있습니다. 당신은 앞으로도 오랫동안 인간들과 싸우게 될 테지요. 그 긴 전투 기간 동안 해골 30개를 모아 준다면 합당한 대가를 지급하도록 하겠습니다.', '타렌 제분소에 있는 죽음경비병 삼사가 언덕마루 주민의 해골 30개를 가져다 달라고 했습니다.', NULL, '언덕마루 구릉지의 타렌 제분소에 있는 죽음경비병 삼사에게 가야 합니다.', NULL),
(547, NULL, NULL, NULL, NULL, '언덕마루 구릉지의 타렌 제분소에 있는 죽음경비병 험버트에게 가야 합니다.', NULL),
(549, NULL, NULL, NULL, NULL, '언덕마루 구릉지의 타렌 제분소에 있는 고위집행관 다살리아에게 가야 합니다.', NULL),
(550, '언덕마루 전투', '언덕마루 전투에서 보여준 자네의 용기와 불굴의 의지에 대해 추천서를 작성해 두었네. 내가 자네의 영웅적인 활약상에 대한 찬사를 아끼지 않았으니 지휘부에서도 자네를 인정해 줄 거야.$B$B자, 이 봉인된 추천서를 언더시티에 있는 브라고르 블러드피스트 님께 가져가도록 하게. 자네가 자랑스럽군!', '언더시티에 있는 브라고르 블러드피스트에게 다살리아의 봉인된 추천서를 가져가야 합니다.', NULL, NULL, NULL),
(551, '마법의 양피지', '이 양피지는 마법이 걸려 있어 판독이 불가능합니다. 그러나 양피지의 맨 위에 있는 하나의 단어는 읽을 수 있습니다.$B$B 나가즈$B$B', '언덕마루 구릉지의 남녘해안에 있는 현자 딥스에게 마법의 양피지를 가져가야 합니다.', NULL, NULL, NULL),
(552, '헬쿨라의 복수', '헬쿨라님께서 마술사로의 변신을 거의 마쳤을 때 인간 폭도 일당이 언덕에서 의식을 행하는 장소를 발견하고 그분을 잔인하게 죽여버렸습니다. 그것도 모자라 그분의 시체를 남녘해안 묘지에 묻어 버렸지 뭡니까.$B$B그분과 같은 위대한 마법사님께 그따위 짓을 하다니 절대로 용서할 수 없습니다. 그분의 수습생으로서 남녘해안 마을에 반드시 복수하고 말겠어요!$B$B복수를 위해서는 먼저 헬쿨라님의 마법봉이 필요해요. 그런데 지금은 의식을 행하는 장소를 설인이 점령해 버렸답니다. 틀림없이 놈들 중 하나가 마법봉을 가지고 있을 테니 가져다주세요.', '설인에게서 헬쿨라의 마법봉을 되찾아 타렌 제분소에 있는 수련사 사이반드에게 가져가야 합니다.', NULL, '언덕마루 구릉지의 타렌 제분소에 있는 수련사 사이반드에게 가야 합니다.', NULL),
(553, NULL, NULL, NULL, NULL, '언덕마루 구릉지의 남녘해안 무덤에 있는 헬쿨라의 무덤을 찾아야 합니다.', NULL),
(554, '스톰파이크의 판독', '암호 해독이나 판독이라면 발굴조사단장 스톰파이크만한 전문가도 없을 것이오. 당신이 발견한 양피지를 가져가 보시기 바라오. 운이 좋으면 스톰파이크가 해독할 수도 있을 테니 말이오. 스톰파이크는 지금 아이언포지에 있는 발굴조사 본부에서 연구 중이오.$B$B그를 만나면 내가 보냈다고 하시오. 최근에 내가 그에게 일거리를 많이 보내 주었다오.', '아이언포지에 있는 발굴조사단장 스톰파이크에게 마법의 양피지를 가져가야 합니다.', NULL, NULL, NULL),
(555, '독특한 거북이 비스크', '남녘해안 하면 빼놓을 수 없는 것이 바로 스톰윈드 북부 지역에서 최고를 자랑하는 요리랍니다! 저만의 비법으로 만드는 거북이 비스크도 그중 하나라 할 수 있지요. 오로지 제 요리를 맛보기 위해 멀리 어둠골에서 이곳까지 오는 이들도 있을 정도랍니다.$B$B그런데 요즘은 통 거북이 비스크를 만들 수가 없었어요. 전엔 달라란을 지나 로다미어 호수까지 가서 직접 무쇠턱거북을 사냥하곤 했는데, 지금은 너무 위험해서 원 갈 수가 있어야지요. 북쪽 지역에 있는 무쇠턱거북의 거북이 고기를 구해다 주시면 금방 거북이 비스크를 만들어 드리도록 하죠.', '남녘해안에 있는 주방장 예센에게 거북이 고기 10개를 가져가야 합니다.', NULL, '언덕마루 구릉지의 남녘해안에 있는 주방장 예센에게 가야 합니다.', NULL),
(556, '징표의 돌', '달라란 마법사들은 정령을 다루는 데 탁월한 재주가 있습니다. 그 정령들은 다른 차원에서 온 강력한 존재들입니다. 마법사들은 징표의 돌을 사용하여 정령들을 조정하고 있습니다. 학자 보이드글레어 님께서 아마 이 돌들을 좀 연구하고 싶어하실 겁니다.$B$B언덕마루 서쪽에 달라란 마법사의 땅으로 들어가서 징표의 돌을 모은 다음 내게 가져오십시오.$B$B그 지역 내에 있는 달라란 주민에게서도 돌을 얻을 수 있겠지만, 달라란보다는 안전한 로다미어 포로수용소로 가는 게 좋을 겁니다.', '타렌 제분소에 있는 관리인 벨바릴에게 닳아해진 징표의 돌 10개를 가져가야 합니다.', NULL, '언덕마루 구릉지의 타렌 제분소에 있는 관리인 벨바릴에게 가야 합니다.', NULL),
(557, NULL, NULL, NULL, NULL, '언덕마루 구릉지의 타렌 제분소에 있는 관리인 벨바릴에게 가야 합니다.', NULL),
(558, '제이나의 친필서명', '사람들이 테라모어에 계시는 제이나 프라우드무어 님은 얼라이언스 최고의 영웅 중 한 분이라던데요. 저도 이다음에 커서 얼라이언스의 영웅이 되고 싶어요!$B$B제이나 님을 아세요? 저, 부탁 한 가지만 들어주실래요? 제이나 님의 친필서명 좀 받아주실 수 있으세요? 제가 제이나 님께 음… 무슨 말씀을 드려야 할지도 모르겠고 저 같은 꼬맹이한테 시간을 내줄 만큼 한가하진 않으실 테니까요… 하지만 $g형이라면:누나라면; 들어주실 거예요! $g형:누나;도 그분 같은 모험가잖아요! $g형이라면:누나라면; 금방 서명해 주실 거예요!$B$B들어주실거죠?', '돌보고 있는 고아를 위해 테라모어로 가서 여군주 제이나 프라우드무어의 친필서명을 받아야 합니다.', NULL, '인간 고아와 대화해야 합니다. 고아가 옆에 없다면, 고아 호루라기를 사용하여 불러내야 합니다.', NULL),
(559, NULL, NULL, NULL, NULL, '언덕마루 구릉지의 남녘해안에 있는 부관 파렌 오리넬에게 가야 합니다.', NULL),
(560, '파렌의 증거물', '난 도저히 이 멀록 머리를 못 가져가겠소. 어차피 이미 이 머리들에 손을 댄 김에 당신이 나 대신 이것들을 레드패스에게 좀 전해 주지 않겠소?', '남녘해안에 있는 치안대장 레드패스에게 멀록 머리가 든 자루를 전달해야 합니다.', NULL, NULL, NULL),
(561, '파렌의 증거물', '부관 파렌 오리넬에게 이번에는 동부 해안에 출몰하고 있는 나가를 처리하는데 전념하라고 전해 주게나. 그리고 성과가 있을 때는 직접 와서 보고하라고 하게.', '남녘해안에 있는 부관 파렌 오리넬과 대화해야 합니다.', NULL, NULL, NULL),
(562, '아, 스톰윈드!', '스톰윈드 근위병 시절 내 스승이었던 분이 얼라이언스 총사령관께서 나가의 위협 때문에 염려하고 계시다는 전갈을 보내오셨소. 스승님이 들으신 바로는 이와 관련해서 능력을 발휘한 이에게는 진급이나 작게는 원하는 곳으로 보직을 변경할 기회를 준다고 하오.$B$B여기서 한 가지 작은 문제가 있긴 한데… 바로 내가 나가를 감당할 수 없다는 점이오. 술집에서 주정뱅이가 벌이는 소동을 진압하거나 싸움꾼 거지를 체포하는 것쯤이야 자신 있지만 나가는 내게 버거운 상대요. 당신이 좀 도와주시오!', '남녘해안에 있는 부관 파렌 오리넬을 위해 비수가시 바다사냥꾼 10마리와 비수가시 세이렌 10마리를 처치해야 합니다.', NULL, '언덕마루 구릉지의 남녘해안에 있는 부관 파렌 오리넬에게 가야 합니다.', NULL),
(564, NULL, NULL, NULL, NULL, '언덕마루 구릉지의 남녘해안에 있는 대런 말뷰에게 가야 합니다.', NULL),
(565, NULL, NULL, NULL, NULL, '언덕마루 구릉지의 남녘해안에 있는 바르톨로 진세티에게 가야 합니다.', NULL),
(566, NULL, NULL, NULL, NULL, '언덕마루 구릉지의 타렌 제분소에 있는 고위집행관 다살리아에게 가야 합니다.', NULL),
(567, NULL, NULL, NULL, NULL, '언덕마루 구릉지의 타렌 제분소에 있는 고위집행관 다살리아에게 가야 합니다.', NULL),
(568, '그롬골 방어', '트롬카! 그롬골에 온 것을 환영하네. 제때에 잘 도착했군. 나는 위대하신 대족장님 휘하의 주둔지 사령관으로서 이곳 정글에서 전 호드의 안전을 책임지는 영광스러운 임무를 맡고 있다네. 그런데 이곳에 서식하는 짐승 중 일부가 스토나드까지의 보급망의 안전을 지키는 우리의 임무를 방해하고 있어.$B$B자네가 그롬골 외곽에 있는 랩터의 수를 좀 줄이도록 하게. 놈들의 수를 최대한 줄인 후에는 내게 돌아와 다른 임무를 맡도록.', '그롬골 주둔지의 사령관 아그로고쉬가 채찍꼬리랩터 15마리를 처치해 달라고 했습니다.', NULL, '가시덤불 골짜기의 그롬골 주둔지에 있는 사령관 아그로고쉬에게 가야 합니다.', NULL),
(569, '그롬골 방어', '처음 이 정글에 도착했을 때 우리는 이곳 토착 종족들과 싸울 생각이 전혀 없었네. 스토나드에 보급품을 공급하는 임무가 최우선이었으니 말이지. 하지만 복잡한 문제가 발생하였다네. 이곳의 오우거 무리가 그롬골 남동쪽의 미즈자 폐허를 점령하고 말았으며, 수차례 경고를 했음에도 놈들은 우리 보급 짐마차에 매복 공격을 해 오고 있다네.$B$B호드의 명예로운 일원인 자네에게 이 비협조적인 오우거들을 처리하는 임무를 맡기도록 하지. 미즈자 폐허로 가서 놈들을 그 지역에서 몰아내도록 하게. 적어도 놈들에게 확실한 경고는 될 것이야.', '그롬골 주둔지에 있는 사령관 아그로고쉬가 모쉬오그 투사 10명과 모쉬오그 의술사 5명을 처치해 달라고 했습니다.', NULL, '가시덤불 골짜기의 그롬골 주둔지에 있는 사령관 아그로고쉬에게 가야 합니다.', NULL),
(570, '모크타르딘의 마법', '호드는 지금이라도 정글 마법의 힘을 깨닫고 이용해야 하오. 지금까지 내 마법 의식은 상당한 효과를 보아 왔지. 이제 난 아주 강력한 마법을 사용할 수 있게 되었소. 용감한 $C|1이여;여;, 당신을 위해 아주 특별한 물건을 만들어 주도록 하지.$B$B내게 그림자퓨마 발톱과 암호랑이의 송곳니를 가져오시오. 아무 송곳니나 사용할 수 있는 게 아니고, 반드시 오염되지 않은 순수한 상태의 송곳니여야 하오.$B$B이 짐승은 보통 정글 여기저기를 어슬렁거리지만 가까운 곳에서도 찾을 수 있을 테니 남동쪽의 미즈자 폐허 강 건너편으로 가 보시오.', '그롬골 주둔지에 있는 예언자 모크타르딘이 그림자퓨마 발톱 8개와 온전한 암호랑이의 송곳니를 가져다 달라고 했습니다.', NULL, '가시덤불 골짜기의 그롬골 주둔지에 있는 예언자 모크타르딘에게 가야 합니다.', NULL),
(571, NULL, NULL, NULL, NULL, '가시덤불 골짜기의 그롬골 주둔지에 있는 예언자 모크타르딘에게 가야 합니다.', NULL),
(572, NULL, NULL, NULL, NULL, '가시덤불 골짜기의 그롬골 주둔지에 있는 예언자 모크타르딘에게 가야 합니다.', NULL),
(573, '모크타르딘의 마법', '이제 마지막 재료 한 가지만 구하면 마법을 완성할 수 있소.$B$B남쪽에 서부 해안 쪽 절벽 높은 곳에 신성한 샘이 있소. 이 샘은 종교학자와 신비주의 학자들 사이에서 뜨거운 논란의 대상이 되고 있소이다. 아제로스의 모든 종족들은 그 샘물이 자기 일족을 위해 신이 주신 신령한 선물이라고 주장하지.$B$B마지막으로 부탁할 일은 바로 그 신성한 샘물을 가져다 달라는 것이오. 나가 탐험가도 그 샘물을 찾아 나섰다고 하니 조심하는 게 좋을 거요. 샘물을 가져오려면 아마 놈들과 부딪쳐야 할 거요.', '그롬골에 있는 예언자 모크타르딘이 나가 탐험가 10명을 처치하고 신성한 샘물을 가져다 달라고 했습니다.', NULL, '가시덤불 골짜기의 그롬골 주둔지에 있는 예언자 모크타르딘에게 가야 합니다.', NULL),
(574, NULL, NULL, NULL, NULL, '가시덤불 골짜기의 반란군 야영지에 있는 부관 도렌에게 가야 합니다.', NULL),
(575, '수요와 공급', '모두들 저에게 ≪예나 지금이나 남해는 물론 전 세계에서 가장 뛰어난 가죽세공꾼≫이라 말하죠. 나! 드리즐릭을 말이에요! 가장 뛰어난 가죽… 에헴, 흠. 내 가죽 제품은 아주 훌륭한 것으로 전문가들에게도 그 명성이 대단하죠.$B$B방금 전에도 땜장이 조합의 조합장이신 리들복스 님께서 즐겨 신는 엑셀시어류 장화 12짝을 주문하셨다니까요. 사실, 그 신발은 저희 집에서 제일 잘 팔리는 신발입죠.$B$B장화의 기본 형태를 잡으려면 우선 가시덤불 골짜기 북부 지역의 강가에서 악어 껍질을 구해와야 하는데 좀 구해다 주시겠어요?', '무법항에 있는 드리즐릭에게 큰 민물악어 껍질 2장을 가져가야 합니다.', NULL, '가시덤불 골짜기의 무법항에 있는 드리즐릭에게 가야 합니다.', NULL),
(576, NULL, NULL, NULL, NULL, '가시덤불 골짜기의 무법항에 있는 애꾸눈 디지에게 가야 합니다.', NULL),
(577, NULL, NULL, NULL, NULL, '가시덤불 골짜기의 무법항에 있는 드리즐릭에게 가야 합니다.', NULL),
(578, NULL, NULL, NULL, NULL, '가시덤불 골짜기의 무법항에 있는 남작 레빌가즈에게 가야 합니다.', NULL),
(579, NULL, NULL, NULL, NULL, '엘윈 숲에 있는 도니얼 토발드에게 가야 합니다.', NULL),
(580, NULL, NULL, NULL, NULL, '가시덤불 골짜기의 무법항에 있는 위스키 슬림에게 가야 합니다.', NULL),
(581, NULL, NULL, NULL, NULL, '가시덤불 골짜기의 그롬골 주둔지에 있는 님보야에게 가야 합니다.', NULL),
(582, NULL, NULL, NULL, NULL, '가시덤불 골짜기의 그롬골 주둔지에 있는 님보야에게 가야 합니다.', NULL),
(584, NULL, NULL, NULL, NULL, '가시덤불 골짜기의 그롬골 주둔지에 있는 끓고 있는 가마솥을 찾아야 합니다.', NULL),
(585, '네즐뤼크와의 대화', '<가마솥에서 들려오는 네즐뤼크의 목소리>$B$B사실이다. 나는 검은창 부족의 아이가 끌려간 곳을 알고 있다. 비록 네가 나를 이기고 내 영혼을 묶어 놓긴 했지만 대가 없이 입을 열지는 않을 것이다!$B$B우리 붉은머리 부족은 백골가루 부족과 전쟁을 치르고 있다. 내게서 원하는 정보를 얻으려면 백골가루 부족에게서 놈들의 전리품 해골 3개를 훔쳐 여기 우리가 있는 곳으로 가져와라. 그러면 난 황천에서도 함께할 노예를 얻을 수 있으니… 첫 번째는 발리아마에 있는 놈들의 전리품 더미에서 가져와야 하고, 다른 하나는 지아타자이, 그리고 나머지 하나는 줄맘웨에서 가져온 전리품이어야 한다.', '그롬골 주둔지에 있는 끓고 있는 가마솥으로 발리아마 전리품 해골과 지아타자이 전리품 해골, 줄맘웨 전리품 해골을 가져가야 합니다.', NULL, '가시덤불 골짜기의 그롬골 주둔지에 있는 끓고 있는 가마솥을 찾아야 합니다.', NULL),
(586, NULL, NULL, NULL, NULL, '가시덤불 골짜기의 그롬골 주둔지에 있는 끓고 있는 가마솥을 찾아야 합니다.', NULL),
(587, NULL, NULL, NULL, NULL, '가시덤불 골짜기의 무법항에 있는 디그에게 가야 합니다.', NULL),
(588, '예니쿠의 생사 확인', '<가마솥에서 들려오는 네즐뤼크의 목소리>$B$B나와 우리 족장의 분노를 달래 주었으니 진실을 알려 주겠다.$B$B예니쿠라는 애송이는 자신의 일족에게조차 잊힌 자이지. 추방자 잔질이라는 의술사가 그를 데려갔지. 이제 잔질이 그의 몸과 영혼을 조종하고 있으니 아주 강력한 마법이 아니면 그를 구할 수 없을 것이다.$B$B$C 따위는 절대 사용할 수 없는 마법이지.$B$B너의 동맹군인 검은창 부족이라면 예니쿠를 구할 수 있을지도 모르겠군. 가능성은 거의 없어 보이지만 말이야.', '킨윌레이와 대화해야 합니다.', NULL, '가시덤불 골짜기의 그롬골 주둔지에 있는 킨윌레이와 대화해야 합니다.', NULL),
(589, '고동치는 푸른 수정', '가시덤불 골짜기 심장부의 깊은 곳에 보물이 숨겨져 있다는 전설이 전해 오고 있소. 우린 그걸 마음의 눈이라 부르는데, 아주 강력한 힘을 지니고 있소. 당신이 마음의 눈을 찾아와 준다면 예니쿠를 어둠에서 구해낼 수 있을 거요.$B$B난 정글의 영혼들에게 마음의 눈에 대해 물어보도록 하겠소. 그동안 당신은 남동쪽의 수정 광산으로 가서 무쇠턱바실리스크들에게서 고동치는 푸른 수정을 구해 오도록 하시오. 그 수정은 매우 희귀하지만 마음의 눈을 우리 의지대로 다루려면 그 수정의 마법이 꼭 필요하오.', '그롬골 주둔지에 있는 킨윌레이에게 고동치는 푸른 수정 3개를 가져가야 합니다.', NULL, '가시덤불 골짜기의 그롬골 주둔지에 있는 킨윌레이에게 가야 합니다.', NULL),
(590, '도적의 거래', '뭐야?$B$B뭐냐고?!$B$B돈을 달라고? 난 당신에게 빚진 게 없다고.$B$B편지? 무슨 편지? 오호, 덤벼 보시겠다? 좋아, 친구. 한판 붙어보자고! 내가 빚을 졌다니…', '죽음의 종소리 마을에 있는 캘빈 몬테규를 쓰러뜨려야 합니다.', '캘빈 몬태규를 꺾으세요', '죽음의 종소리 마을에 있는 캘빈 몬테규에게 가야 합니다.', NULL),
(591, '마음의 눈', '마음의 눈은 동쪽에 있는 모쉬오그 오우거 소굴 안 깊은 곳에 있는 마이조스라는 오우거 마법사가 가지고 있소. 검은창 부족이 가시덤불 골짜기에 살던 시절부터 내가 알고 있던 자이지. 그 오우거는 마법 능력이 강하며 아주 사악한 자라오. 게다가 마음의 눈을 가지고 있다면 지금쯤 마법이 더 강력해졌을 거요.$B$B당신이 마이조스를 상대하고 그에게서 마음의 눈을 빼앗아 와야 하오. 위험한 임무지만 그것이 예니쿠를 구할 수 있는 유일한 희망이오.', '그롬골 주둔지에 있는 킨윌레이에게 마음의 눈을 가져가야 합니다.', NULL, '가시덤불 골짜기의 그롬골 주둔지에 있는 킨윌레이에게 가야 합니다.', NULL),
(592, '예니쿠 구출', '마음의 눈을 영혼의 보석으로 바꾸어 놓았는데 이렇게 한 데에는 두 가지 목적이 있소. 우선 영혼의 보석을 사용해서 예니쿠를 기절시킨 다음 그의 머리 위에 보석을 놓으면 그의 영혼을 가둘 수 있지.$B$B그런 다음 영혼의 보석을 님보야에게 가져가시오.$B$B예니쿠는 여기서 좀 떨어져 있는 가시덤불 곶의 수정 해안을 따라가면 나오는 아보라즈의 폐허에 추방자 잔질과 함께 있소.', '님보야에게 충만한 영혼의 보석을 가져가야 합니다.', NULL, '가시덤불 골짜기의 그롬골 주둔지에 있는 님보야에게 가야 합니다.', NULL),
(593, '영혼의 보석 채우기', NULL, NULL, NULL, '가시덤불 골짜기에 있는 예니쿠에게 가야 합니다.', NULL),
(596, NULL, NULL, NULL, NULL, '가시덤불 골짜기의 그롬골 주둔지에 있는 킨윌레이에게 가야 합니다.', NULL),
(597, '붉은해적단', '지도 상의 무법항에는 정확하게 현재 서 있는 위치에 빨간색으로 ≪X≫ 표시가 되어 있습니다.$B$B휘갈겨 쓰인 글씨의 내용은 다음과 같습니다.$B$B≪모두 현재 위치에 야영지를 확보하고 소리가 새어 나가지 않도록 하라. 남부 전투 사령부에서 공격 신호가 있을 때까지 기다려라. 접근하는 자는 모두 없애도록.≫', '무법항에 있는 일등항해사 크래즈에게 조사 결과를 보고해야 합니다.', NULL, '가시덤불 골짜기의 무법항에 있는 일등항해사 크래즈에게 보고해야 합니다.', NULL),
(598, NULL, NULL, NULL, NULL, '가시덤불 골짜기의 그롬골 주둔지에 있는 킨윌레이에게 가야 합니다.', NULL),
(599, '붉은해적단', '이런 제길! 그래, 붉은해적단 놈들이 무법항을 공격할 모종의 계획을 꾸미고 있다고? 흥! 그 악당 놈들 참 대담하군그래. 무법항은 영원히 우리 검은바다 해적단의 영역인 것을!$B$B이거 생각보다 문제가 심각한 것 같군. 이 사실을 즉시 함장 시혼님께 보고하도록 해 주라고! 저 늙은 바다의 개들이 마을 어딘가에서 기웃거리고 있다니…', '함장 시혼에게 붉은해적단의 공격 계획을 보고해야 합니다.', NULL, '가시덤불 골짜기의 무법항에 있는 함장 시혼에게 보고해야 합니다.', NULL),
(600, NULL, NULL, NULL, NULL, '가시덤불 골짜기의 무법항에 있는 크랭크 피즐버브에게 가야 합니다.', NULL),
(601, NULL, NULL, NULL, NULL, '가시덤불 골짜기의 무법항에 있는 남작 레빌가즈에게 가야 합니다.', NULL),
(602, '마법 분석', '들리는 바에 따르면, 달라란의 마법사들이 도시를 재건해내서는 노스렌드로 옮겨갔다더군. 예전에 도시가 있던 자리엔 커다란 구덩이만 남기고 말일세. 하지만 거기에 여전히 머무르는 마법사도 있다네. 그중 누군가 시간을 내서 족쇄를 봐줄 게야. 내가 마법사에 대해 잘 아는 건 아니지만, 어쨌든 그들이 절대 마법적인 수수께끼를 거부하지 못한단 건 안다네.$B$B물의정령 족쇄가 든 가방을 가지고 가서 그들이 해일의 돌에 걸린 저주를 풀 수 있는 실마리를 찾을 수 있을지 알아봐 주게. 대마법사 앤자이럼 룬위버를 찾아가라고. 전에 내가 그와 거래했었고 그의 지식은 무척 방대하니 도움이 될 걸세.', '달라란 구덩이에 있는 대마법사 앤자이럼 룬위버에게 물의정령 족쇄가 든 가방을 가져가야 합니다.', NULL, '알터랙 산맥의 달라란 구덩이에 있는 대마법사 앤자이럼 룬위버에게 보고해야 합니다.', NULL),
(603, '앤자이럼의 열쇠', '해일의 돌을 소유하고 있는 마법사는 그 돌이 가진 힘을 일종의 제단 같은 곳에 집중되도록 증폭시켜 놓았소. 당신의 힘으로 돌을 깨뜨려 버릴 수 있을 것이오.$B$B내가 아는 바로는 그걸 가능하게 할 수 있는 물건은 고대 트롤 유물 중의 하나인 고대의 단검뿐이오. 그런데 말이오… 내가 가시덤불 골짜기에서 연구하던 시절에 그 단검을 발견했네만 그걸 내 고집 센 딸, 케이틀린에게 줘 버렸소. 그리고 그 애는 해적이 되기 위해 무법항으로 도망쳐 버렸고 말이지.', '무법항에 있는 케이틀린과 대화해야 합니다.', NULL, '가시덤불 골짜기의 무법항에 있는 케이틀린과 대화해야 합니다.', NULL),
(604, NULL, NULL, NULL, NULL, '가시덤불 골짜기의 무법항에 있는 함장 시혼에게 가야 합니다.', NULL),
(605, NULL, NULL, NULL, NULL, '가시덤불 골짜기의 무법항에 있는 크랭크 피즐버브에게 가야 합니다.', NULL),
(606, NULL, NULL, NULL, NULL, '가시덤불 골짜기의 무법항에 있는 겁쟁이 필립에게 가야 합니다.', NULL),
(607, '맥킨리에게 돌아가기', '자, 여기 이 주머니를 맥킨리에게 갖다줘요. 그리고 그에게 돈은 갚을 생각이었다고 말해 주세요!$B$B술이 취해 길을 잃어서… 뭐, 말 안 해도 알잖아요, 어떻게 된 건지… 그도 아마 이해할 거예요. 그러니 그렇게 겁줄 필요 없다고요!', '바다늑대'' 맥킨리에게 겁쟁이 필립의 빚진 돈을 가져가야 합니다.', NULL, '가시덤불 골짜기의 무법항에 있는 ''바다늑대'' 맥킨리에게 보고해야 합니다.', NULL),
(608, NULL, NULL, NULL, NULL, '가시덤불 골짜기의 무법항에 있는 함장 시혼에게 가야 합니다.', NULL),
(609, NULL, NULL, NULL, NULL, '가시덤불 골짜기의 무법항에 있는 ≪바다늑대≫ 맥킨리에게 가야 합니다.', NULL),
(610, NULL, NULL, NULL, NULL, '가시덤불 골짜기의 무법항에 있는 검술의달인 케이틀린에게 가야 합니다.', NULL),
(611, NULL, NULL, NULL, NULL, '가시덤불 골짜기의 무법항에 있는 남작 레빌가즈에게 가야 합니다.', NULL),
(612, '<미사용>', '힘들긴 하겠지만, 단검을 달라고 케이틀린을 한번 설득해 봐 주겠는가? 수집가의 마음을 자네가 이해할 수 있겠나만은…$B$B아마 내가 원하고 있다고 하면 그녀가 팔려고 할 수도 있을 걸세.', '케이틀린의 검을 돌려줘야 합니다.', NULL, '가시덤불 골짜기에 있는 검술의달인 케이틀린에게 가야 합니다.', NULL),
(613, NULL, NULL, NULL, NULL, '가시덤불 골짜기의 무법항에 있는 ≪바다늑대≫ 맥킨리에게 가야 합니다.', NULL),
(614, '선장의 상자', '난 여기에서 칼림도어의 톱니항까지 배로 항해하곤 했다네. 그래도 꽤 유명한 선장이었다고. 그런데…$B$B저주받은 바다 거인들이 내 인생을 망쳐 놓고 말았어! 거인들이 내 배를 박살 내고 부하들을 모두 죽였지. 난 겨우 구명정에 몸을 맡기고 이 무법항까지 흘러 왔다네. 그 거인들 중 고를라쉬라는 놈이 내 상자를 훔쳐 가면서 그걸 코담뱃갑으로 쓸 거라더군. 뻔뻔한 놈 같으니!$B$B들리는 소문에 의하면 고를라쉬는 이곳에서 동쪽에 있는 해안을 어슬렁거린다고 하네. 놈을 찾아서 내 상자를 되찾아 주게! 그렇게 해 준다면 정말 고맙겠군그래.', '무법항에 있는 허클베리 스모츠에게 스모츠의 상자를 가져가야 합니다.', NULL, '가시덤불 골짜기의 무법항에 있는 선장 허클베리 스모츠에게 가야 합니다.', NULL),
(615, '선장의 커틀라스', '그 거인들에게 내 첫 번째 배를 잃은 후, 난 다른 배를 샀고 스모츠의 복수라는 이름을 붙였지. 그리고 선원을 모으고 식량을 싣고는 그 악당 놈들을 찾아 떠났다네. 결국 놈들을 찾긴 했지만 또다시 당하고 말았지. 놈은 스모츠의 복수호를 박살 내고 내 두 번째 선원들을 모두 죽였다네. 그리고 난 또다시 구명정에 의지하는 신세가 되었지.$B$B이번에는 네골라쉬라는 거인 놈이 내 커틀라스를 훔쳐가 버렸네. 네골라쉬를 찾아내 커틀라스를 되찾아 주게나.$B$B스프로거와 얘기해 보게. 저 친구는 스모츠의 복수호의 요리사였는데 마지막 공격에서 살아남았으니까 그가 거인 찾는 걸 도와줄 것이야.', '스프로거와 대화해야 합니다.', NULL, '가시덤불 골짜기의 무법항에 있는 스프로거와 대화해야 합니다.', NULL),
(616, '유령의 섬', '레빌가즈 남작님께서 내게 무법항과 가시덤불 골짜기에 떠도는 이상한 소문을 파악하여 그 진상을 캐내라고 당부하셨어요. 보통 난 유령 이야기는 잘 믿지 않지만, 선술집에서 어떤 선원들이 해안 근처에 있는 유령의 섬에 대해 이야기하는 것을 들었어요. 물의 정령들과 미쳐 날뛰는 고블린 유령이 있다고 말이에요.$B$B레빌가즈 님을 만나면 이 이야기를 좀 전해 주겠어요?', '무법항에 있는 남작 레빌가즈와 대화해야 합니다.', NULL, '가시덤불 골짜기의 무법항에 있는 남작 레빌가즈와 대화해야 합니다.', NULL),
(617, NULL, NULL, NULL, NULL, '가시덤불 골짜기의 무법항에 있는 선원 블로즈에게 가야 합니다.', NULL),
(618, '네골라쉬와의 대적', '네골라쉬는 늘 굶주려 있는 거인이에요.$B$B그 거인들이 우리 배를 파괴했을 때, 네골라쉬는 곧장 제 주방으로 쳐들어왔었죠. 녀석은 다른 거인처럼 선원들로 배를 채우려 하지 않았어요. 네골라쉬는 포도주와… 내가 만든 구이 요리를 원했어요. 그건 제 특별 요리인 데다 재료를 구하려면 황야의 땅까지 가야 하는데 말이죠!$B$B그 거인을 유인하려면 포도주와 대머리수리 날개가 많이 필요할 거예요. 여기에서 해안을 따라 남동쪽에 있는 낡은 구명정에 음식을 실어 놓으세요. 네골라쉬가 그 음식 냄새를 맡으면 반드시 나타날 거예요!', '선장 스모츠의 구명정에 대머리수리 날개 구이 10개와 밀림덩굴 포도주 5병을 가져가야 합니다.네골라쉬를 처치하고 가시덤불 골짜기에 있는 선장 스모츠에게 스모츠의 커틀라스를 가져가십시오.', NULL, '가시덤불 골짜기의 무법항에 있는 선장 허클베리 스모츠에게 가야 합니다.', NULL),
(619, '네골라쉬 유인', NULL, NULL, NULL, '가시덤불 골짜기에 있는 난파된 구명보트로 가야 합니다.', NULL),
(620, '이니셜이 새겨진 머리띠', '이 멋진 머리띠에는 가장자리를 따라 ≪HS≫ 라는 머리글자가 수놓아져 있습니다.', '이니셜이 새겨진 머리띠를 주인에게 돌려줘야 합니다.', NULL, '가시덤불 골짜기의 무법항에 있는 이니셜이 새겨진 머리띠의 주인을 찾아야 합니다.', NULL),
(621, NULL, NULL, NULL, NULL, '가시덤불 골짜기의 무법항에 있는 크랭크 피즐버브에게 가야 합니다.', NULL),
(622, '하사관 칼레브에게 돌아가기', '당신이 혈석을 구하러 간 동안 냄비 수리를 끝냈어요. 그리고 증기 피리도 부착해 놓았고, 여기 보세요! 바닥에는 다리뼈도 자를 수 있는 신형 칼까지 달아 놓았어요!$B$B보시다시피, 내 오래된 냄비는 이제 완벽한 요리 기계가 됐어요. 냄비 주인도 만족할 거예요.', '반란군 야영지에 있는 하사관 칼레브에게 크라젝의 수리된 냄비를 가져가야 합니다.', NULL, '가시덤불 골짜기의 반란군 야영지에 있는 하사관 칼레브에게 보고해야 합니다.', NULL),
(625, '코르텔로의 수수께끼', '칼림도어의 먼 땅 당신을 기다리는 그곳$B$B위험이 희망과 운명을 꺾어 버리는 곳$B$B불모의 땅 동쪽 지독한 날씨$B$B어둡고 위험한 먼지진흙 습지대$B$B그러나 거기엔 기꺼이 시험에 도전하려는 자들을 위한 단서가 있네$B$B남서쪽 동굴에서 누군가 찾아 줄 날을 기다린다네', '수수께끼를 풀어야 합니다.', NULL, '먼지진흙 습지대에 있는 단서를 찾아야 합니다.', NULL),
(626, '코르텔로의 수수께끼', '위대한 혼란의 땅 로데론으로!$B$B용감한 병사들이 죽음에 맞서 싸우는 곳$B$B그 거대한 혼란을 뚫고 당신의 길을 찾으라$B$B거기서 이 수수께끼의 결말을 알게 되리$B$B동부 내륙지의 해안을 따라, 거대한 폭포의 밑바닥$B$B물밑에서 보물이 당신을 부르고 있다!', '수수께끼를 풀어야 합니다.', NULL, '동부 내륙지에 있는 단서를 찾아야 합니다.', NULL),
(627, '크라젝의 부탁', '아라시 고원 북쪽 먼 곳에 있는 마른수염 골짜기에 가면 산 속 동굴이 하나 있어요. 그 동굴에는 혈석이라는 희귀한 광석이 있죠. 그 동굴에 있는 혈석은 일등품은 아니지만, 품질이 좋지 않은 혈석도 그걸 어떻게 사용하는지 아는 이에게는 귀하게 사용될 수 있어요.$B$B나한테 그게 좀 필요해요. 그러니 내가 당신이 가져온 고물 냄비를 수리하고 있을 동안 혈석을 좀 가져다주세요. 충분한 양을 가져다준다면 가격을 맞춰 드리도록 하죠.$B$B아, 그리고 그 광석 채광 방법을 모른다면 채광해 줄 자를 찾아야 할 거예요!', '무법항에 있는 크라젝에게 하급 혈석 광물 4개를 가져가야 합니다.', NULL, '가시덤불 골짜기의 무법항에 있는 크라젝에게 가야 합니다.', NULL),
(628, '엑셀시어', '안감을 완성했으니 이제 겉감만 만들면 됩니다요. 겉감에는 최고의 덩치 큰 악어 껍질만 사용하죠. 악어 껍질이 더 튼튼하면서도 질이 좋기 때문에 저만의 특별한 디자인인 드리즐릭의 엑셀시어류 제품을 만들기에 안성맞춤이에요.$B$B완벽한 껍질을 찾기가 어렵긴 하지만 덩치 큰 바다악어 껍질이라면 제격이죠. 녀석들은 다른 악어를 지켜야 할 경우에만 밖으로 나오기 때문에 바다악어를 몇 마리 처리해야 놈을 볼 수 있을 거예요.', '무법항에 있는 드리즐릭에게 덩치 큰 악어 껍질을 가져가야 합니다.', NULL, '가시덤불 골짜기의 무법항에 있는 드리즐릭에게 가야 합니다.', NULL),
(629, '썩은내 산호초', '오래전, 큰 지진으로 오래된 트롤의 도시가 북서쪽 폭풍 해안 앞바다에 잠기고 말았지. 지금은 멀록들이 도시의 폐허 속에 살면서 접근하는 이들을 공격하고 있기에 우린 그곳을 썩은내 산호초라고 부른다오.$B$B그 폐허 속에는 트롤 전설 속의 영웅 그리렉에 대한 옛 이야기가 적혀 있는 오래된 서판이 있소. 그 이야기는 우리 검은창 부족에게 신성한 것이오. 비록 서판 자체는 너무 커서 옮길 수 없지만, 그 서판 조각 하나쯤은 반드시 우리의 새로운 고향인 오그리마에 모셨으면 하오. 서판 조각을 내게 가져다줄 수 있겠소?', '그롬골 주둔지에 있는 킨윌레이에게 서판 조각을 가져가야 합니다.', NULL, '가시덤불 골짜기의 그롬골 주둔지에 있는 킨윌레이에게 가야 합니다.', NULL),
(630, '쪽지가 든 병', '당신과 저를 구하기 위해 오신 동료를 믿겠습니다. 저는 거대한 밀림의왕 무클라에게 잡혀 있답니다. 무클라가 이 섬의 짐승들에게 명령을 내려 제가 이 사슬을 끊고 탈출하지 못하도록 잡아두게 하고 있어요. 당신이 그 고릴라를 처치하고 이 족쇄의 열쇠를 찾아 주신다면 그 은혜 정말 잊지 않겠습니다.$B$B섬의 남동쪽 가장자리에서 무클라의 목소리가 자주 들리곤 해요. 쉬운 상대가 아니니 제발 조심하세요.', '밀림의왕 무클라를 처치하고 공주 푸바에게 열쇠를 가져가 그녀를 구해야 합니다.', NULL, '가시덤불 골짜기의 자구에로 섬에 있는 공주 푸바에게 가야 합니다.', NULL),
(632, '탄돌 교각', '가여운 러스트로크는 검은무쇠 드워프의 매복지까지 들어갔던 것 같습니다. 꽉 쥐고 있는 그의 주먹 옆에서 양피지 문서가 발견되었습니다.$B$B이 슬픈 소식을 라그 가마슨에게 보고하고 발견한 양피지 문서를 보여 줘야 합니다.', '저습지의 던 모르드에 있는 라그 가마슨에게 돌아가서 러스트로크의 시체에서 발견한 양피지 문서를 보여 줘야 합니다.', NULL, NULL, NULL),
(633, NULL, NULL, NULL, NULL, '저습지의 던 모드르에 있는 라그 가마슨에게 가야 합니다.', NULL),
(634, '얼라이언스에 지원 요청', '작은 부탁 하나만 더 해도 되겠소, $C 친구? 우리는 아이언포지로부터 예비 사단을 기다리고 있소. 그런데 로고의 말에 의하면 북쪽 아라시 고원의 임시 주둔지에 얼라이언스 야영지가 있다고 하오.$B$B그곳으로 가서 부대장 나이얼스 님을 만나보시오. 그리고 그녀에게 우리가 던 모드르와 탄돌 교각을 탈환하도록 지원 병력을 보내줄 수 있는지 물어봐 주시오.', '아라시 고원의 임시 주둔지에 있는 부대장 나이얼스를 찾아야 합니다.', NULL, NULL, NULL),
(636, '대지의 전설', '이 책은 정령 공주 미즈라엘과 그녀가 아라시 고원 아래 깊은 곳에 갇힌 데 대한 일화가 쓰여 있습니다.$B$B이 책은 또한 비밀의 수정에 대해서도 언급하고 있습니다. 미즈라엘의 결정이라 불리는 이 수정들은 공주의 감옥으로 통하는 문이라고 합니다.$B$B만약 이 미즈라엘의 결정이라는 것을 찾으면 미즈라엘과 대화를 해야 할 것 같습니다…', '미즈라엘의 결정을 찾아야 합니다.', NULL, NULL, NULL),
(637, '설리 발루의 편지', '편지 봉투 안에는 공들여 쓰인 편지 몇 장이 들어 있는데, 물에 젖은데다 전쟁의 모진 상처들로 인해 다 낡아 버려서 편지의 몇 장이 손에 쥐자마자 녹아 없어져 버립니다.$B$B편지는 아이언포지의 사라 발루 부인 앞으로 보내진 것이며 ≪사랑하는 사라에게…≫로 시작하고 있습니다.', '설리 발루의 편지를 사라 발루에게 전해야 합니다.', NULL, NULL, NULL),
(638, '트롤베인', '토라스 트롤베인도 죽었고 스트롬가드도 폐허가 되었으니, 볼진께서 이제 인간의 손에서 전설의 검인 트롤칼라를 빼앗아 앞으로 있을 줄구룹의 트롤과의 전투에 사용할 수 있도록 하라고 지시하셨소.$B$B검 탈취 작전을 감독하기 위해 노련한 사냥꾼 중 하나인 젠구가 아라시 고원 북동부 지역의 망치 주둔지로 파견되었으니 그를 만나보도록 하시오.', '아라시 고원의 망치 주둔지로 가서 젠구와 대화해야 합니다.', NULL, NULL, NULL),
(639, NULL, NULL, NULL, NULL, '아라시 고원의 망치 주둔지에 있는 젠구에게 가야 합니다.', NULL),
(640, '깨진 인장', '토라스 트롤베인의 무덤은 세 개의 인장으로 보호되어 있네. 자네가 비밀결사대로부터 빼앗아 온 것은 이 중 첫 번째이고 나머지 두 개는 철통같이 수비하고 있는 스트롬가드 민병대가 가지고 있으니 구하기가 더 어려울 걸세.$B$B세 개의 인장 중 한 개인 소라딘의 인장은 토라스의 아들인 갈렌이 다섯 개 조각으로 나누어 스트롬가드 수호병들에게 나누어 주었지. 그 조각을 찾아내 우리 트롤 주술사인 토건에게 가져다주면 그가 조각을 결합하여 완전한 인장을 만들 걸세.', '스트롬가드의 수호병들에게서 인장 조각 5개를 빼앗아 망치 주둔지에 있는 토건에게 가져가야 합니다.', NULL, '아라시 고원의 망치 주둔지에 있는 토건에게 가야 합니다.', NULL),
(641, '소라딘의 인장', '흠잡을 데 없이 완벽하게 인장을 완성했네. 이제 이 인장을 사용하여 트롤베인의 무덤에 있는 봉인을 깨뜨릴 수 있다네. 젠구에게 가 보게. 분명히 다른 임무가 또 있을 거야.', '망치 주둔지에 있는 젠구에게 소라딘의 인장을 가져가야 합니다.', NULL, NULL, NULL),
(642, NULL, NULL, NULL, NULL, '아라시 고원의 마른수염 골짜기에 있는 오색 결정을 찾아야 합니다.', NULL),
(643, '아라소르의 인장', '아라시 고원 전체는 말할 것도 없고, 스트롬가드 조차도 완벽히 자신의 휘하에 두지 못하는 인간족의 왕자가 자신의 졸개 기병을 데리고 온 지역을 돌아다니고 있네. 도대체 그 이유를 알 수가 없단 말이야. 하기야 인간의 머릿속에 뭐가 들어 있는지 누가 알겠나?$B$B이유야 어쨌든 중요한 건 그가 기병 대장인 부관 밸러콜에게 인장을 맡겼다는 것이야. 부관 밸러콜을 찾아서 처치하고 인장을 내게 가지고 와주게.', '아라소르의 인장을 찾은 후 망치 주둔지에 있는 젠구에게 가져가야 합니다.', NULL, '아라시 고원의 망치 주둔지에 있는 젠구에게 가야 합니다.', NULL),
(644, '트롤베인의 인장', '토라스 트롤베인의 무덤을 여는 데 필요한 마지막 인장은 그의 아들이 가지고 있네. 트롤베인의 아들은 스트롬가드의 깊은 곳, 수호대가 장악하고 있는 지역의 작은 예배당에 숨어 있어. 갈렌 왕자 주위는 경호가 삼엄한 데다가 본인도 막강한 전사이니 이번 임무가 가장 어려울 걸세.', '왕자 갈렌 트롤베인을 처치하고 망치 주둔지에 있는 젠구에게 트롤베인의 인장을 가져가야 합니다.', NULL, '아라시 고원의 망치 주둔지에 있는 젠구에게 가야 합니다.', NULL),
(645, '트롤칼라', '이건 뭐지? 인장 네 개를 한 곳에 모았더니 하나의 인장으로 결합되었네. 분명 이 인장을 사용하면 트롤베인의 무덤에 설치된 봉인을 깨뜨릴 수 있을 거야.$B$B트롤베인의 유골은 스트롬가드 내부 성소 뒤편에 있는 지하 납골당에 묻혀 있네. 가서 트롤칼라를 되찾아 오게.', '스트롬가드에 있는 트롤베인의 무덤에서 트롤칼라를 회수해야 합니다.', NULL, NULL, NULL),
(646, '트롤칼라', '빛이 서서히 사라지며 돌로 된 칼집 안에 들어 있는 트롤칼라를 집었습니다.', '망치 주둔지에 있는 젠구에게 트롤칼라를 가져가야 합니다.', NULL, NULL, NULL),
(647, '맥크릴의 밀주', '어젯밤 오래 묵은 밀주를 좀 마셨지. 보초를 서는 동안 술에 취해 버린 걸 알면 롱브레이드가 날 죽이려 들 거요.$B$B아, 술 좀 마셨더니 지독히 괴롭군. 머리 위로 전차 부대가 하나 요란하게 지나가는 것 같아.$B$B오, 이런! 시간이 이렇게나 됐군! 남녘해안에 있는 양조업자 빌저에게 밀주를 보내 밀린 외상값을 갚기로 했는데…$B$B갚기로 한 시간이 15분밖에 안 남았잖아! 부탁이니 이걸 좀 전해 주시오. 서둘러야 하오!', '남녘해안에 있는 양조업자 빌저에게 맥크릴의 밀주를 가져가야 합니다.', NULL, NULL, NULL),
(649, '리플 회수', '당신이 뭘 좀 찾아와 줬으면 하는데. 당신도 나처럼 리플 애호가라면 이 일이 맘에 쏙 들 거요! 리플이라니까!$B$B술 말이야 술! 이런 바보하고는…$B$B버려진 호드 전초기지에 녀석들이 장사를 할 때부터 숨겨두었던 동부 내륙지 벌꿀 리플이 있소이다. 그런 좋은 리플은 이제 더 이상 찾지도 못하지! 말톤의 멍청한 친구 녀석 중 하나가 어디 있는지 안다니까 가서 포장된 리플을 한 상자 가져다주시오. 아, 내 소장품으로 간직하게 두 개 더 가져오고! 말톤에게 얘기하면 자세히 알려줄 거요.', '오그리마에 있는 말톤 드로퍼스와 대화해야 합니다.', NULL, NULL, NULL),
(651, NULL, NULL, NULL, NULL, '아라시 고원의 내부 봉인의 마법진에 있는 내부 봉인석으로 가야 합니다.', NULL),
(652, NULL, NULL, NULL, NULL, '아라시 고원의 내부 봉인의 마법진에 있는 쐐기돌에 가야 합니다.', NULL),
(653, '미즈라엘의 친구들', '<미즈라엘의 말>$B$B자유다! 이제 자유야! 저를 사로잡은 자들에게서 벗어나 이제서야 힘을 모을 수 있게 됐답니다. 혹시라도 그들과 다시 마주치면 절 힘으로 장악하여 다시 가둬 놓을 겁니다.$B$B하지만 때가 되면 제가 직접 거인들과 싸울 것이고, 저를 가둬 놓은 대가를 치르게 할 겁니다!$B$B당신은 이제부터 제 친구입니다. 때가 되면 저를 다시 한 번 도와 주시기 바랍니다. 제가 준비되면 지상으로 소환해 주시길 부탁 드립니다.$B$B아이언포지의 쓸쓸한 뒷골목에 있는 게릭 본그립과 얘기를 나눠 보시기 바랍니다. 그는 날 소환하는 방법을 알고 있습니다.', '아이언포지의 쓸쓸한 뒷골목에 있는 게릭 본그립과 대화해야 합니다.', NULL, NULL, NULL),
(654, '타나리스 현장 견본 수집', '동력원을 가동하자 휴대용 분석 도구가 빛을 발하며 진동하기 시작하는 것을 보니 계획한 대로 작동하는 것 같습니다.$B$B어서 이걸 가져가도록 해야겠습니다.$B$B선임 기술자 빌지위즐에 의하면 타나리스 사막에서 필요한 자료를 수집하기 위한 시간이 두 시간 남았습니다. 두 시간 안에 다 수집하지 못하면 모든 자료를 잃게 되어 선임기술자 빌지위즐에게서 또 다른 동력원을 구해야 합니다.$B$B임무를 마치면 그에게 돌아가야 합니다.', '타나리스 사막에서 쓸만한 바실리스크 견본, 쓸만한 하이에나 견본, 쓸만한 전갈 견본을 각 8개씩 모아야 합니다. 동력원이 다 떨어지기 전에 가젯잔에 있는 선임기술자 빌지위즐에게 분석 도구를 가져가야 합니다.', NULL, '타나리스의 가젯잔에 있는 선임기술자 빌지위즐에게 가야 합니다.', NULL),
(655, '망치 주둔지', '마치 어제와도 같이 선명하군… 이 끔찍한 곳에 갇혀서 수많은 해를 절망 속에서 지내왔지. 그러던 중 마침내, 마침내! 대족장님께서 나타나셨네. 검은 갑옷을 입고 전쟁망치를 높이 든… 둠해머 님이 말이야.$B$B그러나… 너무나 끔찍한 일이 일어나고 말았네… 비겁한 녀석의 단 한 번의 일격에 가장 위대한 영웅께서 쓰러지시다니… 그 비겁한 놈이 말을 타고 달려와 창으로 뒤에서 둠해머 님의 등을 찔러 버리고 말았지… 난 무릎을 꿇고 말았네. 내 눈앞에서 희망이 사라지는 것을 보았어… 도대체 무슨 희망이 있었겠나? 무슨 희망이…', '망치 주둔지에 있는 토건과 대화해야 합니다.', NULL, NULL, NULL),
(656, NULL, NULL, NULL, NULL, '아라시 고원에 있는 미즈라엘의 결정으로 가야 합니다.', NULL),
(658, '새로운 역병의 징조?', '그러니까 핀이 우리가 잘못되지 않았는지 걱정돼서 당신을 보냈다고요? 하기야 놀라운 일도 아니죠. 핀은 워낙 걱정이 많은 성격이니까요.$B$B우리는 며칠 간 농장을 지켜보고 있었는데, 얼마 전에 키넬로리가 저기 남쪽에 있는 작은 집에서 급사가 빠져나가는 것을 봤다고 하더군요.$B$B키넬로리가 평소에 말이 많긴 하지만 위험한 지역에서는 매우 정확한 감각을 자랑한답니다.$B$B참, 혹시 당신도 실력 있는 수색자인가요? 우리 생각에는 급사가 타렌 제분소로 전갈을 가지고 간 것 같아요. 그 서류를 우리 손에 넣을 수 있으면 언덕마루에서 일어나는 일에 대한 단서를 얻을 수 있을지도 몰라요.', '포세이큰 급사를 찾아서 봉인된 서류를 고셰크 농장 근처에 있는 쿠에에게 가져가야 합니다.', NULL, '아라시 고원에 있는 쿠에에게 가야 합니다.', NULL),
(660, '새로운 역병의 징조?', '좋아요. 난 언제나 준비되어 있답니다.$B$B그럼 시작할까요?', '키넬로리가 쿠에에게 돌아갈 때까지 보호해야 합니다.', '키넬로리를 보호하세요', '아라시 고원에 있는 쿠에에게 가야 합니다.', NULL),
(661, '새로운 역병의 징조?', '키넬로리의 현재 모습이 지난번에 선술집에서 하룻밤 묵고 나서의 모습보단 낫군요. 여기까지 정말 잘 호위해 주셨네요.$B$B그녀가 농장에서 가져온 물건을 핀이 보면 이곳 아라시에서 대충 어떤 일이 벌어지고 있는지 짐작할 수 있을 거예요. 보복 공격이 없는지 확인하기 위해 우리는 이곳에 좀 더 남아 있을게요. 먼저 남녘해안으로 가서 핀에게 얘기해 주겠어요?', '언덕마루 구릉지의 남녘해안에 있는 핀 오델릭을 찾아야 합니다.', NULL, NULL, NULL),
(662, NULL, NULL, NULL, NULL, '아라시 고원의 팔디르의 만에 있는 일등항해사 닐즐릭스에게 가야 합니다.', NULL),
(663, '육지다!', '롤로 눈에 작은 $R|1이;가; 보인다! 롤로 항상 망 보고 있다!$B$B팔디르의 만에 온 걸 환영한다. 오브린 선장이 여기 몇 시간만 있으면 된다고 했다. 보물을 모아서 무법항으로 가져가기만 하면 된다고 했다.$B$B하지만 롤로 생각하기에는 시간이 더 오래 걸릴 것 같다. 우리 함대에서 배 두 개 잃었다. 불쌍한 은빛소나무의 영혼호와 처녀의 망상호… 지금은 저 바다 밑에 자고 있을 거다!$B$B여기서 쉴 거면 오브린 선장과 얘기해 보는 게 좋을 거다.', '아라시 고원의 팔디르의 만에 있는 선장 오브린과 대화해야 합니다.', NULL, NULL, NULL),
(664, NULL, NULL, NULL, NULL, '아라시 고원의 팔디르의 만에 있는 선장 스틸구트에게 가야 합니다.', NULL),
(665, '가라앉은 보물', '자, 이제 우리도 어엿한 검은바다 해적단이니까 오브린 선장이 잃어버린 엘프의 보물을 찾도록 도와 주어야 한다오.$B$B아무런 도움 없이 어두운 바다 속에서 보석을 찾는다는 건 거의 불가능한 일이지. 드랙슬게이지가 고글을 몇 개 만들어 놓았다오. 언덕 바로 위의 동굴 속에 있는 마법의 돌에서 힘을 끌어와 고글에 불어넣어야 한다더군.$B$B그런데 그 동굴에는 저주가 걸려 있다오! 가까이 다가가면 공격을 받을 것이야. 그러니까 당신은 내가 고글에 마법의 돌의 힘을 채울 수 있도록 보호해 주면 된다오.', '학자 피즐솔프가 동굴에 들어갔다 나올 수 있도록 호위해야 합니다.', '피즐소프 교수를 변호하세요', '아라시 고원의 팔디르의 만에 있는 발명가 드랙슬게이지에게 가야 합니다.', NULL),
(666, NULL, NULL, NULL, NULL, '아라시 고원의 팔디르의 만에 있는 발명가 드랙슬게이지에게 가야 합니다.', NULL),
(667, '나가의 공격', '큰일이군. 비수가시 일족 녀석들이 공격을 하려고 모이는 모양이야.$B$B나가는 전투에서 잔악하기로 유명한 녀석들이라 내가 죽을 때까지 계속해서 공격할 것이오.$B$B내가 내 선원들보다 내 목숨을 아끼는 건 아니지만 나만큼 바다에 대해 잘 아는 자가 없으니 내가 없으면 어차피 선원들도 무법항까지 돌아가지 못할 것이야. 그러니 날 꼭 지켜 줘야해.$B$B나가 녀석들은 바다에서 접근해 올 것이오. 나와 함께 이 위에 남아 녀석들의 공격을 막아주시오. 배 위에 있는 대포를 이용해서 녀석들을 몰아내시오.$B$B준비는 됐소?', '나가의 공격으로부터 셰익스 오브린을 보호해야 합니다.', '셰이크스 오브린을 변호하세요', '아라시 고원의 팔디르의 만에 있는 셰익스 오브린에게 가야 합니다.', NULL),
(668, '가라앉은 보물', '오브린 선장이 오래 기다리지 않도록 하라고. 보석을 발견하는 즉시 가져오라고 했단 말이지. 결국은 그것 때문에 우리가 여기 있는 것이지!$B$B그리고 몇 주 동안 해적들과 어울리면서 피즐솔프와 내가 얻은 교훈은 이들의 보물을 오래 가지고 있으면 신상에 절대 이롭지 못하다는 거야.$B$B자, 이 보석들을 오브린 선장에게 가져가라고.', '아라시 고원의 팔디르의 만에 있는 선장 오브린에게 엘프의 보석을 가져가야 합니다.', NULL, NULL, NULL),
(669, '가라앉은 보물', '시혼 함장님께 이 사실을 즉시 보고해야 하오.$B$B그런데 당신도 보다시피 이곳을 빠져나가기가 상당히 곤란하단 말이지. 조수가 낮을 뿐만 아니라, 일단 몰아내기는 했지만 빌어먹을 짐승들이 우리를 계속 노리고 있소.$B$B당신이 무법항에 계신 시혼 함장님께 보물을 발견했다는 사실과 현재 계속 끌어올리는 중이라고 보고해 주면 검은바다 해적단에게 정말 큰 도움을 주는 것이야. 증거로 이 표본을 가져가도록 하시오.', '가시덤불 골짜기의 무법항에 있는 시혼 함장에게 엘프의 보석 표본을 가져가야 합니다.', NULL, NULL, NULL),
(671, '사악한 마법', '지난 밤 뭔가 이상한 기운을 느꼈네. 내 피를 들끓게 하는 기운을… 의심 가는 데가 있긴 하네. 나를 불안하게 하는 기운의 근원을 찾아보았더니 서쪽의 북부습곡 장원에서 악마를 소환한 흔적이 있더군. 좀 더 가까이 다가가자 피가 끓기 시작했고 분노가 치밀어 오르기 시작했네.$B$B악마를 소환하는 데 사용한 혈석 아뮬렛을 바닥에서 주웠지만 내가 발견한 아뮬렛은 이미 그 힘이 고갈되어 있었네. 조사를 계속하려면 다른 아뮬렛이 필요한데, 감히 그곳에 다시 돌아가지는 못하겠군. 자네가 몇 개를 가져다주겠나?', '망치 주둔지에 있는 토건을 위해 혈석 아뮬렛 10개를 모아야 합니다.', NULL, '아라시 고원의 망치 주둔지에 있는 토건에게 가야 합니다.', NULL),
(672, '되살아나는 영혼', '우린 그에게 칼림도어의 오그리마라는 우리의 강력한 도시에 대해 이야기해 주며, 진정시키고 위로하려고 노력했지만 아무것도 그의 마음을 움직이지 못했네.$B$B둠해머 님의 갑옷과 워해머를 이어받은 우리의 젊은 대족장 스랄 님에 대한 이야기도… 하지만 어쩌면… 그래, 그러면 될지도 몰라! 우리가 새로 발견한 주술을 보여 주면 다시 희망을 가지게 될지도 모르겠군. 한 번 시도해 볼만하군그래!$B$B그를 위해 작은 물건을 하나 만들 수 있을 텐데… 그래! 랩터 눈을 몇 개 가져다주게. 그럼 내가 뭔가 할 수 있을 것 같아.', '줄무늬 고원랩터와 외뿔 고원랩터에게서 고원랩터 눈 10개를 모아 망치 주둔지에 있는 토건에게 가져가야 합니다.', NULL, '아라시 고원의 망치 주둔지에 있는 토건에게 가야 합니다.', NULL),
(673, NULL, NULL, NULL, NULL, '아라시 고원의 망치 주둔지에 있는 토건에게 가야 합니다.', NULL),
(674, '되살아나는 영혼', '자, 이 아뮬렛을 고르멀에게 가져다주고 랩터의 힘이 한때 그의 몸 속에 타오르던 용사의 열정을 되살릴 수 있는지 보라고.', '아라시 고원의 망치 주둔지에 있는 고르멀에게 랩터 발톱 아뮬렛을 전달해야 합니다.', NULL, NULL, NULL),
(675, '되살아나는 영혼', '<고르멀이 아뮬렛을 땅에 버리며>$B$B토건이 자네를 보냈나? 그렇지? 흥, 그가 내게 왜 이런 자비를 베푸는지 도저히 이해할 수 없군. 전투에서 대족장님과 함께 죽지 못했다는 것 자체가 이미 신의 자비가 나를 버린 거야. 너무나 잔인한 운명이지…', '아라시 고원의 망치 주둔지에 있는 토건과 대화해야 합니다.', NULL, NULL, NULL),
(676, NULL, NULL, NULL, NULL, '아라시 고원의 망치 주둔지에 있는 드럼 펠에게 가야 합니다.', NULL),
(677, NULL, NULL, NULL, NULL, '아라시 고원의 망치 주둔지에 있는 드럼 펠에게 가야 합니다.', NULL),
(678, '전장으로', '당신의 전투 실력은 탁월하군. 그러면 이번에는 더 강한 녀석들을 한 번 상대해 보겠소?$B$B돌주먹 일족의 소굴은 이곳의 남서쪽, 드워프 다리 방향에 있소. 그리고 그곳에 있는 돌주먹 싸움꾼과 사제는 아주 강력한 상대들이오. 지금까지 우리에게는 그랬었지.$B$B이들을 최대한 많이 쓰러뜨리고 돌아오시오. 살아서 돌아오든가 죽어서 귀신이 되어 돌아오든가… 어떻게 되든 전장에서 벌인 당신의 활약은 칭송을 받을 거요.', '돌주먹 투사 10마리와 돌주먹 사제 4마리를 처치한 다음 망치 주둔지 전초기지에 있는 드럼 펠에게 가야 합니다.', NULL, '아라시 고원의 망치 주둔지에 있는 드럼 펠에게 가야 합니다.', NULL),
(679, NULL, NULL, NULL, NULL, '아라시 고원의 망치 주둔지에 있는 드럼 펠에게 가야 합니다.', NULL),
(680, NULL, NULL, NULL, NULL, '아라시 고원의 망치 주둔지에 있는 코린 펠에게 가야 합니다.', NULL),
(681, NULL, NULL, NULL, NULL, '아라시 고원의 임시 주둔지에 있는 부대장 나이얼스에게 가야 합니다.', NULL),
(682, NULL, NULL, NULL, NULL, '아라시 고원의 임시 주둔지에 있는 부대장 나이얼스에게 가야 합니다.', NULL),
(683, '사라 발루의 탄원서', '제 작은 부탁을 들어주시겠어요?$B$B이 탄원서를 아이언포지의 위대한 마그니 브론즈비어드 국왕 폐하께 전해 주세요. 당신처럼 얼라이언스를 위해 위대한 업적을 쌓은 분께 이렇게 사소한 부탁을 드리는 것이 송구스럽긴 하지만…$B$B지금 제가 이렇게 눈물 젖은 모습으로 국왕 폐하를 알현하면 실수라도 하게 될 것 같아서요. 이해해 주시리라 믿습니다.', '아이언포지에 있는 마그니 브론즈비어드 국왕에게 사라 발루의 탄원서를 전달해야 합니다.', NULL, NULL, NULL),
(684, NULL, NULL, NULL, NULL, '아라시 고원의 임시 주둔지에 있는 부대장 나이얼스에게 가야 합니다.', NULL),
(685, NULL, NULL, NULL, NULL, '아라시 고원의 임시 주둔지에 있는 부대장 나이얼스에게 가야 합니다.', NULL),
(686, '왕의 하사품', '발루 부인과 같은 드워프 평민들이 더 큰 행복과 안전을 위해 전쟁을 불사할 수밖에 없는 이유를 이해해 주기를 바라지는 않았네. 하지만 그녀의 남편을 포함해 얼라이언스의 이름으로 싸우다 목숨을 잃은 모든 드워프를 생각하면 짐의 마음이 무겁기 그지없군.$B$B그녀의 남편을 뒤틀린 황천에서 다시 데려올 수는 없지만 그대신 하사품을 내리겠네. 대석공 마블스텐으로 하여금 설리 발루의 기념비를 세우도록 명하겠네.$B$B당장 그에게 내 말을 전하도록, $C. 어서 가서 짐의 명을 수행하게.', '마그니 브론즈비어드 국왕이 대석공 마블스텐과 대화해 달라고 했습니다.', NULL, NULL, NULL),
(687, '실성한 텔두린', '텔두린은 황혼의 망치단의 일원이었네. 그런데 그가 실성한 후 우리의 가르침을 무시해 버렸지. 그는 우리한테서 도망치면서 미즈라엘의 두루마리를 훔쳐 갔네! 우린 그를 잡지 못했지만, 소문에 따르면 황야의 땅에서 실성한 채로 알 수 없는 말을 지껄이며 숨어 있다고 하네.$B$B공주를 다시 모셔오려면 반드시 텔두린을 찾아 그 두루마리를 찾아야 하네.', '실성한 텔두린을 찾아야 합니다.', NULL, NULL, NULL),
(688, '미즈라엘의 친구들', '<미즈라엘의 말.>$B$B자유다! 이제 자유야! 저를 사로잡은 자들에게서 벗어나 이제서야 힘을 모을 수 있게 됐답니다. 혹시라도 그들과 다시 마주치면 저를 힘으로 장악하여 다시 가둬 놓을 겁니다.$B$B하지만 때가 되면 제가 직접 거인들과 싸울 것이고, 저를 가둬 놓은 대가를 치르게 할 겁니다!$B$B당신은 이제부터 제 친구입니다. 때가 되면 저를 다시 한 번 도와 주기 바랍니다. 제가 준비되면 지상으로 소환해 주시길 부탁 드립니다.$B$B망치 주둔지에 있는 자루크와 얘기를 나눠 보시기 바랍니다. 그는 날 소환하는 방법을 알고 있답니다.', '아라시 고원의 망치 주둔지에 있는 자루크와 대화해야 합니다.', NULL, NULL, NULL),
(689, '왕의 하사품', '그러니까 우리의 위대하신 국왕께서 설리 발루라는 병사를 위해 기념비를 세웠으면 하신단 말이오? 그 불쌍한 젊은이가 탄돌 교각 참사에서 죽었단 말이지?$B$B도대체 이 동부 왕국에는 언제쯤 평화가 찾아올는지…$B$B휴, 왕께서 내리신 명령이니 우선 다른 작업은 뒤로 미뤄야겠군. 후세에까지 길이 남을 진정한 영웅의 기념비를 만들려면 최상급 돌이 필요하오. 언덕마루의 다로우 언덕으로 가서 알터랙 화강암을 좀 가져 오시오.', '아이언포지의 대석공 마블스텐이 알터랙 화강암 5개를 가져다 달라고 했습니다.', NULL, '던 모로에 있는 대석공 마블스텐에게 가야 합니다.', NULL),
(690, '말린의 요청', '안녕하시오. 보아하니 모험가의 분위기가 느껴지는군. 도움이 필요한 일이 있는데 한번 들어 보겠소?$B$B얼마 전에 아라시 고원의 스트롬가드 요새를 떠나신 나의 첫 스승이자 대마법사이신 트렐레인 님께서 두고 오신 몇몇 물건을 찾는 걸 도와 달라고 하셨소.$B$B그 도시는 함락되었고 스승께서는 아라소르의 탑을 방어하려 했으나 성공하지 못했다오. 이미 아라시 고원에 사람을 보냈으나 그들은 도움을 더 요청해 오고 있소. 어떻소, 관심이 있소?', '아라시 고원의 임시 주둔지에서 스쿼토를 찾아야 합니다.', NULL, NULL, NULL),
(691, NULL, NULL, NULL, NULL, '아라시 고원의 임시 주둔지에 있는 수습마법사 크리텐에게 가야 합니다.', NULL),
(692, '잃어버린 조각', '미즈라엘의 두루마리… 미즈라엘의 두루마리?! 설마 그걸 원하는 건 아니겠지! 그 두루마리의 마법을 사용하면 미즈라엘을 지상 세계로 끌어낼 수 있단 말이야. 그러면 모두 다 곤란해진다고!$B$B어쩌면… 벌써 늦은 걸지도 몰라. 벌써 자유의 몸이 되어 힘을 모으고 있는 중일지도 몰라. 그렇다면 그 두루마리가 필요하지!$B$B…하지만 이미 파괴되어 버렸는데 어쩌지? 광포한 바위 정령들이 훔쳐가서 갈기갈기 찢어 버렸어.$B$B하지만 조각을 모두 모아 올 수 있다면 다시 하나로 만들 수 있을지도…', '실성한 텔두린에게 찢어진 두루마리 조각, 구겨진 두루마리 조각, 그을린 두루마리 조각을 가져가야 합니다.', NULL, '황야의 땅에 있는 실성한 텔두린에게 가야 합니다.', NULL),
(693, NULL, NULL, NULL, NULL, '아라시 고원의 임시 주둔지에 있는 스쿼토에게 가야 합니다.', NULL),
(694, NULL, NULL, NULL, NULL, '아라시 고원의 임시 주둔지에 있는 수습마법사 크리텐에게 가야 합니다.', NULL),
(695, '수습생의 마법', '이걸 받으십시오. 탑의 토대 근처에 있는 기둥 중 한 곳에 대고 보석을 누르면 탑의 방어 기능이 작동할 겁니다. 탑에 들어가서 트렐레인의 유품을 찾을 준비가 되면 사용하시기 바랍니다.$B$B행운을 빕니다. 당신이 야영지로 돌아오기를 기다리고 있겠습니다. 참, 떠나기 전에 스쿼토와 얘기를 나눠 보십시오. 나머지 자세한 내용을 알려 줄 겁니다.', '아라시 고원의 임시 주둔지에 있는 스쿼토와 대화해야 합니다.', NULL, NULL, NULL),
(696, '탑 공격', '당신이 찾아야 할 물건은 트렐레인의 부적, 트렐레인의 수정구, 그리고 트렐레인의 잿불 마노라오.$B$B세 가지 모두 탑 안의 상자에 들어 있는데, 상자를 여는 데는 별문제가 없을 테고… 조심해야 할 건 오우거들이오.$B$B탑의 방어 기능으로는 오우거를 직접 처리할 수 있는 게 없기 때문에 무기를 쓸 준비를 하고 있어야 할 것이오. 당신이 물건을 훔치러 왔다는 걸 오우거들이 알면 분명히 공격해 올 것이오.$B$B조심하고 당신에게 행운이 있기를 바라오.', '트렐레인의 부적, 트렐레인의 수정구, 트렐레인의 잿불 마노를 찾아 임시 주둔지에 있는 스쿼토에게 가져가야 합니다.', NULL, '아라시 고원의 임시 주둔지에 있는 스쿼토에게 가야 합니다.', NULL),
(697, '말린의 의뢰', '이 편지를 스톰윈드에 계시는 말린 님께 전해 드리고 크리텐과 내가 곧 돌아갈 것이라고 전해 주시오. 말린 님께서 이곳에서 우리를 도와준 것에 대해서 분명히 큰 보상을 해 주실 것이오.$B$B안전한 여행이 되길…', '스톰윈드의 마법사 지구에 있는 대마법사 말린에게 보내는 봉인된 편지를 전달해야 합니다.', NULL, NULL, NULL),
(698, NULL, NULL, NULL, NULL, '슬픔의 늪의 안개갈대 주둔지에 있는 톡카르에게 가야 합니다.', NULL),
(699, '보급품 보충', '우리는 스토나드로 다가오는 모든 위협을 방어하거나, 적의 규모가 대규모일 경우에 아군에게 경고하는 임무를 띠고 이곳에 배치되었네. 해안에서 멀록의 위협이 끊이지 않고 있다 보니 우린 쉴 틈도 거의 없지. 그래서 말인데, 괜찮다면 자네의 도움을 좀 받았으면 하네.$B$B무쇠턱 톱니악어의 발톱을 잘 다듬으면 좋은 무기를 만들 수 있지. 내게 그 발톱을 몇 개 가져다주면 신선한 고기와 좋은 친구에 대한 답례로 우리 무기 중 하나를 주겠네.', '슬픔의 늪에 있는 톡카르에게 무쇠턱 톱니악어 발톱 6개를 가져가야 합니다.', NULL, '슬픔의 늪의 안개갈대 주둔지에 있는 톡카르에게 가야 합니다.', NULL),
(700, '왕의 하사품', '아, 이렇게 질 좋은 암석들이 나오는 로데론이 폐허로 변해 버리다니 안타까운 일이야.$B$B하지만 기념비는 아주 잘 만들어졌소! 왕께서 아주 기뻐하실 것이오.$B$B자, 그럼 어서 가서 기념비가 완성되었다고 전해 드리도록 하시오.', '마그니 브론즈비어드 국왕에게 보고해야 합니다.', NULL, NULL, NULL),
(701, '랩터의 기민함', '재료가 몇 개 더 있으면 내가 고르멀에게 랩터의 기민함을 불어넣어 주는 물건을 만들어 줄 수 있네! 랩터의 힘이 몸속에 흘러들어가면 고르멀이 우리의 새로운 힘을 알게 되고 잠들어 있는 용사의 기운을 회복할 걸세!$B$B이 물건과 주술을 완성하기 위해서는 남서쪽에 있는 랩터 심장이 필요하네.', '식인 고원랩터에게서 랩터 심장 12개를 모아 토건에게 가져가야 합니다.', NULL, '아라시 고원의 망치 주둔지에 있는 토건에게 가야 합니다.', NULL),
(702, '랩터의 기민함', '고르멀에게 이 수정구를 가져다주어 랩터의 기민함을 사용하게 해 보게. 그럼 분명히 그의 영혼을 고무시키고 새로운 삶의 목표를 찾을 수 있게 해 줄 걸세. 그가 정상으로 돌아오면 그에게 호드의 현재 상황을 설명해 줄 수 있을 테고, 그러면 이 끊임없는 전투에서 노련한 전사의 도움을 받을 수 있게 될 것이야.', '아라시 고원의 망치 주둔지에 있는 고르멀에게 토건의 수정구를 전달해야 합니다.', NULL, NULL, NULL),
(703, '대머리수리 날개 구이', '오, 물론이야. 대머리수리 날개 구이는 내가 제일 좋아하는 요리라고! 음, 풍부한 소스와 감칠맛이 나는 고기! 그리고 그 냄새는 멀리 떨어진 곳에서도 당장 달려올 정도라니까!$B$B대머리수리 날개만 빼고 다른 건 준비 다 됐는데… $B$B당신도 맛을 보고 싶다면 대머리수리 날개를 구해달라고. 요리하기에 충분한 양을 구해다 준다면 당신에게 아예 조리법을 전수해 줄 수도 있다고!', '리글퍼즈에게 대머리수리 날개 4개를 가져가야 합니다.', NULL, '황야의 땅의 송곳니 골짜기에 있는 리글퍼즈에게 가야 합니다.', NULL),
(704, '아그몬드의 운명', '아그몬드에게서 받은 마지막 보고가 마음에 걸리는군. 이제는 그가 죽어서 더욱 그렇소! 그의 보고서에 의하면 인부들이 울다만 외곽의 발굴현장에서 ''고대의 단지''를 발견했다고 되어있소. 그 현장에서 찾은 단지가 트로그 녀석들을 자극한 게 아닌가 걱정이군. 내가 여기서 찾은 조각상처럼 말이오.$B$B조사를 하려면 단지가 필요한데 울다만 발굴현장으로 가서 돌조각 단지를 모아 내게 돌아오시오.', '모단 호수에 있는 발굴조사단장 아이언밴드에게 돌조각 단지 4개를 가져가야 합니다.', NULL, '모단 호수의 아이언밴드의 발굴현장에 있는 발굴조사단장 아이언밴드에게 가야 합니다.', NULL),
(705, '진주잡이', '황야의 땅은 난폭한 포식자들과 썩은 고기를 먹는 지독한 짐승들이 가득 찬 위험한 곳이지. 나같이 키 작은 고블린에게는… 으… 무서운 곳이 아닐 수 없다니까. 내가 여기서 살아남으려면 절대로 방심해선 안 된다고!$B$B그나마 섬광탄 제조법을 알고 있기에, 그걸 만들어 야생동물을 쫓는 데 사용하고 있지. 근데 재료가 하나 거의 다 떨어져 가서 말이야. 바로 부셔서 만든 푸른 진주 가루라오. 푸른 진주를 좀 구해다 주면 당신이 수고한 만큼 값지게 쓰도록 하지.$B$B아, 그리고 방수가 잘 되는 질 좋은 장화를 신고 가는 게 좋을 거요. 내가 필요한 푸른 진주는 썩은내 산호초에 있는 조개에서 나니까 말이지. 그래, 바로 가시덤불 골짜기에 있는 그 썩은내 산호초 말이야!', '황야의 땅에 있는 리글퍼즈에게 푸른 진주 9개를 가져가야 합니다.', NULL, '황야의 땅의 송곳니 골짜기에 있는 리글퍼즈에게 가야 합니다.', NULL),
(706, '이글거리는 불꽃의 부적', '내가 페라노어 스틸토님의 수습생으로 있을 때 무기에 불의 마법을 불어넣는 특수한 기술을 배웠지. 마지막으로 들은 소식에 의하면 그분이 저 위 로데론에서 사냥꾼 무리와 함께 대장간에서 일하고 계시다는 거요.$B$B자세히 설명해 줄 순 없지만 마법을 불어넣는 과정에는 희귀할 뿐만 아니라, 신중을 기해야만 잡을 수 있는 검은 새끼 비룡의 심장에서 얻은 피가 필요하오이다. 아이언포지에서 연락이 오길 기다리는 동안 할 일도 별로 없으니, 레슬로 협곡에서 검은 새끼 비룡의 심장을 구해 내게 가져다주면 무기에 불의 마법을 불어넣는 기술을 보여 주리다!', '시그런 아이언휴가 검은 비룡의 심장을 구해 달라고 했습니다.', NULL, '황야의 땅에 있는 시그런 아이언휴에게 가야 합니다.', NULL),
(708, '블랙박스', '이 검은 금속 상자는 마치 산성 물질에 담가 두었던 것처럼 심하게 부식되어 있습니다. 오랫동안 거대한 대머리수리의 위장 속에 있었던 것이 분명합니다.$B$B상자를 뒤집자 바닥에 도장이 찍혀 있으며 그 도장 아래에 다음과 같이 적혀 있습니다.$B$B''전차 #19 - 아이언포지 증기 전차 부대''', '녹슨 블랙박스를 아이언포지에 있는 전투의 전당으로 가져가야 합니다.', NULL, NULL, NULL),
(709, NULL, NULL, NULL, NULL, '황야의 땅의 아그몬드의 최후에 있는 실성한 텔두린에게 가야 합니다.', NULL),
(710, '바위의 정령 연구', '난 최근에 맡은 정령 봉인의 족쇄 연구를 위해 이곳 황야의 땅에 머물게 되었어요.$B$B이 연구가 완료되면 마법사가 더욱 강력한 정령을 불러내 그 놀라운 능력을 십분 활용할 수 있게 되죠. 하지만 그 전에 먼저 내가 조립한 여러 장치를 사용하여 이번에 만든 최신 공격 주문을 시험해 보기 위해서는 작은 돌조각들을 모아야 해요.$B$B돌조각은 서쪽에 있는 하급 바위 정령들에게서 쉽게 얻을 수 있을 거예요. 날 위해 돌조각을 좀 구해다 주지 않겠어요?', '황야의 땅에 있는 로트윌 베리아투스에게 작은 돌조각 10개를 가져가야 합니다.', NULL, '황야의 땅의 먼지받이에 있는 로트윌 베리아투스에게 가야 합니다.', NULL),
(711, '바위의 정령 연구', '당신이 보여준 실력이 내 수습생 모두를 합친 것보다도 낫군요.$B$B다음으로 부탁할 일은 큰 돌조각을 구해와야 하는 좀 더 힘든 일이에요. 충분히 주의한다면 바위 정령에게서 돌조각을 얻을 수 있을 거예요. 아무래도 바위 정령은 몸이 크고 강하기 때문에 내 실험에 사용할 만큼 큰 돌조각이 있을 가능성이 커요. 이곳에서 서쪽으로 더 가거나 산기슭을 따라 남동쪽으로 가면 바위 정령들을 찾을 수 있을 거예요.$B$B당신이 가져온 작은 돌조각을 시험해 보려면 시간이 좀 걸릴 테니 서두르진 않아도 돼요.', '황야의 땅에 있는 로트윌 베리아투스에게 큰 돌조각 3개를 가져가야 합니다.', NULL, '황야의 땅의 먼지받이에 있는 로트윌 베리아투스에게 가야 합니다.', NULL),
(712, '바위의 정령 연구', '이곳 황야의 땅에 있는 정령에게서 필요한 것이 한 가지 더 있어요. 상급 바위 정령들에게서 바위 결속의 팔보호구를 구해다 주었으면 하거든요. 내 계산에 따르면 그 팔보호구는 내가 만든 족쇄의 힘을 측정하기에 충분해요.$B$B내가 수정점을 쳐 보니 거대한 바위 정령은 여기서 남서쪽에 있는 것으로 나왔어요. 아마 내 기억으론 오우거 근처에 있었던 것 같단 말이죠.$B$B여분까지 해서 팔보호구를 5개만 가져다주세요. 내 조수 세르보가 내 연구 재료와 결과물을 어디 뒀는지 곧잘 잊어버리니… 만일을 대비해서 말이에요.', '황야의 땅에 있는 로트윌 베리아투스에게 바위 결속의 팔보호구 5개를 가져가야 합니다.', NULL, '황야의 땅의 먼지받이에 있는 로트윌 베리아투스에게 가야 합니다.', NULL),
(713, '최고의 냉각제', '냉기 기름에 대해 가르쳐 줄까요? 엔진이나 기어의 가열을 식히는 데는 냉기 기름 만한 게 없어요.$B$B그 냉각 능력은 놀라울 정도고 윤활유로서의 수명은 그 어떤 것도 따라오지 못하죠. 하지만 이게 전부가 아니에요. 마법이 걸린 물건에 마법 능력을 오래 유지시켜주는 기능도 있다니까요.$B$B내가 소환해낸 정령이 우리 모두를 공격하지 못하게 제어할 수 있을 정도의 족쇄 마법 능력을 높이기 위해서는 냉기 기름 한 병이 필요해요. 알터랙에 있는 내 고블린 친구, 브로킨이 냉기 기름 만드는 법을 가르쳐 줄 거예요.', '황야의 땅에 있는 로트윌 베리아투스에게 냉기 기름을 가져가야 합니다.', NULL, '황야의 땅의 먼지받이에 있는 로트윌 베리아투스에게 가야 합니다.', NULL),
(714, '태엽...장치?', '지금까지 정말 잘해 주었어요.$B$B<실험으로 정신없어 보이는 로트윌>$B$B우리가 카라노스에서 만났을 때 일자리가 필요하거든 언제든지 말만 하라고요.$B$B이런! 얼른 이걸 쥐고 있어 주세요. 네, 그렇게… 고마워요.$B$B이제 작지만 결정적인 재료 한 가지만 더 있으면 되는데… 태엽장치 말이에요. 당신이 태엽장치만 구해다 주면 이 실험을 끝낼 수 있을 거예요.', '황야의 땅에 있는 로트윌 베리아투스에게 태엽장치를 가져가야 합니다.', NULL, '황야의 땅의 먼지받이에 있는 로트윌 베리아투스에게 가야 합니다.', NULL),
(715, '액체 돌', '로트윌 선생님을 위해 당신이 구해 온 재료들은 나무랄 데 없는 것 같군요. 단도직입적으로 당신은 로트윌 선생님께서 신성하게 여기시는 과학에 상당한 조예가 있는 듯하니, 저도 좀 도와주시지 않으시겠어요?$B$B로트윌 선생님께서 정령들을 불러내면 곧 투명 물약과 치유 물약 두 가지가 필요하게 될 거예요. 물약을 구해다 주시면 답례로 로트윌 선생님 밑에 있으면서 개발한 이 물약 조제법을 알려 드리지요.$B$B이 조제법은 선생님께서 이곳 황야의 땅에서 하고 계신 연구 중 일부에 기초한 거랍니다.', '황야의 땅에 있는 루시앙 토슬렌치에게 치유 물약과 하급 투명 물약을 가져가야 합니다.', NULL, '황야의 땅의 먼지받이에 있는 루시앙 토슬렌치에게 가야 합니다.', NULL),
(716, NULL, NULL, NULL, NULL, '황야의 땅의 먼지받이에 있는 루시앙 토슬렌치에게 가야 합니다.', NULL),
(717, '대지의 진동', '블랙래쉬와 헤마투스를 계속 레슬로 협곡에 봉인할 수 있을 거라고는 누구도 보장할 수 없는 상황일세. 그 검은용 두 마리는 그곳에 본거지를 마련했고 오우거들은 봉인까지 훔쳤으니 더욱 강력한 조치를 취해야 할 때야.$B$B비룡의 감옥을 유지하고 있는 마법석 세 개는 대지의 봉인을 사용해야만 가져올 수 있네. 그리고 그 마법석들을 사용하면 그들을 가두고 있는 봉인을 깨뜨릴 수 있다네.$B$B그들의 꿈이 영원히 헛된 망상으로 끝나게 해 주게.', '대지의 봉인을 사용하여 자수정, 오팔, 다이아몬드의 기둥을 작동시켜 마법석을 획득해야 합니다.마법석들을 대지의 봉인에 놓아 블랙래쉬와 헤마투스의 봉인을 해제해야 합니다.풀려 난 블랙래쉬와 헤마투스를 처치하고 가렉에게 블랙래쉬의 굴레, 헤마투스의 굴레와 대지의 봉인을 가져가야 합니다.', NULL, '황야의 땅의 해머토의 발굴현장에 있는 가렉에게 가야 합니다.', NULL),
(718, '신기루', '우린 울다만 발굴현장을 빠져나오느라 정신이 없어 보급품 마차와 상자 상당수를 길에 두고 올 수밖에 없었소. 그런데 코쉬 야영지에서 온 고약한 오우거들이 시체에 모여드는 독수리들처럼 버려진 우리 물건들에 손을 대지 뭐요. 고약한 것들…$B$B어쨌든, 녀석들이 우리의 무기와 식료품이 실려 있던 마차를 가져가서… 부끄럽게도 먹을 걸 전혀 구하지 못했다오.$B$B그래서 지금 몹시 난처한 처지인데 당신이 좀 도와주겠소?', '시그런 아이언휴를 위해 보급품 상자를 되찾아야 합니다.', NULL, '황야의 땅에 있는 시그런 아이언휴에게 가야 합니다.', NULL),
(719, '행운의 곡괭이', '안녕하시오, $C. 여기는 검은무쇠 드워프들이 사방에 깔렸으니 조심해야 하오. 아마도 어둠괴철로 드워프 같았소이다.$B$B좀 전에도 내가 작업 중인 발굴현장을 공격해 난 겨우 목숨을 건졌지만 내 상관인 해머토를 비롯해 거기 있던 거의 모든 이들이 목숨을 잃었소.$B$B발굴현장은 여기에서 바로 북쪽에 있는데, 우리 보급품들, 특히 내 행운의 곡괭이를 되찾아올 방법을 궁리하는 중이었소.$B$B당신이 나를 좀 도와주시오. 저 몹쓸 드워프 중 한 명에게 내 곡괭이가 있을 거요! 녀석들 중 누구든 가지고 있을 테니 좀 찾아다 주시겠소?', '라이돌의 행운의 곡괭이를 찾아 해머토의 발굴현장의 남쪽에 있는 발굴조사단장 라이돌에게 가져가야 합니다.', NULL, '황야의 땅에 있는 발굴조사단장 라이돌에게 가야 합니다.', NULL),
(720, '희망의 전조', '<지도에는 분필로 휘갈겨 쓴 쪽지가 적혀 있습니다.>$B$B"라이돌, 놈들은 나를 울다만으로 데려가고 있네… 도와 주게.$B$B-해머토"', '발굴조사단장 라이돌을 찾아 해머토 그레즈가 살아 있다는 사실을 알려야 합니다.', NULL, '황야의 땅에 있는 발굴조사단장 라이돌과 대화해야 합니다.', NULL),
(721, '희망의 전조', '당신이 그를 좀 찾아 주지 않겠소? 울다만에 있는 해머토를 좀 찾아 주시오.$B$B비열한 어둠괴철로 드워프들이 대규모 발굴 작업에 대해 알아내려고 그를 인질로 잡은 거라면 아이언포지 전체가 큰 위험에 빠질 수도 있소.$B$B저 드워프 녀석들은 오래전부터 더 강한 골렘을 만들어내려고 새로운 마법을 손에 넣으려 했다오. 해머토도 그들과 같은 일을 하고 있었지만, 해머토는 그들을 막으려 한 것이지.$B$B녀석들은 아마 그가 아는 사실을 알아낼 때까지 그를 죽이지 않을 거요. 그를 구하려면 서두르시오!', '울다만에서 해머토 그레즈를 찾아야 합니다.', NULL, NULL, NULL),
(722, '비밀의 아뮬렛', '나를 위해… <콜록>…이곳 울다만까지 와 주다니… 정말 용감하군…$B$B이… 늙은 해머토를 도울 생각이라면… <콜록>… 내 아뮬렛을… 좀… 찾아 주시게…$B$B내 아뮬렛을 딥섀도… 마그레간 딥섀도가 가져갔지. 그는 이 근처 어딘가에 있을 게야… 틀림없이 이 폐허 어딘가에… 그를 막지 못하면 아뮬렛이 놈들을… <콜록>… 두루마리가 있는 길로 안내하게 될 것이네. 이제 모든 건 자네에게 달려 있네. 그러니 제발…아뮬렛을 찾아 주게나. $B$B그리고 그 두루마리는 검은무쇠 드워프들이 보다 강력한 골렘을 만드는 데 꼭 필요한 것일 게야. 확실해. 뼛속까지 느껴지는 걸 보면…', '해머토의 아뮬렛을 찾아 울다만에 있는 해머토에게 가져가야 합니다.', NULL, '울다만에 있는 해머토 그레즈에게 가야 합니다.', NULL),
(723, '돈독한 믿음', '<상처 부위를 감싸며 안정을 되찾은 후 다시 이야기를 시작하는 해머토>$B$B라이돌에게 가게… 그리고 그에게 내 아뮬렛을 가져다주게나. <콜록 콜록> 그러면 그 친구는… <콜록> 해야 할 일을 알 수 있을 거야. 내가 우리의 근원을 찾고 있었다는 걸 그는 알고 있고 <콜록> 어둠괴철로 드워프 녀석들을 막는 것 또한 나의 다른 임무였다는 것도 알고 있을걸세. 그들이 그 두루마리를 찾게 해서는 안 될 것이야…<콜록>', '황야의 땅에 있는 발굴조사단장 라이돌에게 해머토의 아뮬렛을 가져가야 합니다.', NULL, NULL, NULL),
(724, '돈독한 믿음', '좋소, 좋아… 그렇다면 우리가 해야 할 일을 알고 있는 게 누굴까?$B$B그렇지! 역사가 카르닉이 있었지!$B$B그는 아이언포지에 있소. 그라면 우리를 도울 수 있을 거요. 그와 해머토는 울다만에서 사라진 유물을 찾기 위해 함께 일했었지.$B$B아마 어둠괴철로 드워프 녀석들도 그 두 명이 실제로 말한 것보다 더 많이 알고 있다는 사실을 눈치챘을 거요.$B$B해머토에게 일어난 일을 카르닉에게 설명하고 해머토의 아뮬렛을 전해 주시오. 그러면 그가 다음에 해야 할 일을 알려 줄 거요.', '아이언포지에 있는 역사가 카르닉에게 해머토의 아뮬렛을 가져가야 합니다.', NULL, NULL, NULL),
(725, '위협의 경고', '우선 최대한 빨리 조언자 벨그룸 님을 찾아가시게. 그리고 그분께 자네가 본 바를 모두 얘기해 준 다음 앞으로 어떻게 해야 할지 물어보아야 할 것이야. 이 쪽지를 보여 주면 그분이 이번 사건에 대해 보다 잘 알 수 있을 걸세.$B$B그동안 나는 해머토의 영혼과 얘기해 보겠네. 그가 가진 정보가 황야의 땅에서 벌이고 있는 어둠괴철로 드워프의 음모를 막는 데 도움이 될 거야. 일이 잘 되기를 빌어 볼 수밖에…', '조언자 벨그룸을 찾아 봉인된 쪽지를 전해야 합니다.', NULL, '아이언포지에 있는 조언자 벨그룸에게 보고해야 합니다.', NULL),
(726, '위협의 경고', '<쪽지를 끝까지 읽는 조언자 벨그룸, 잠시 눈이 휘둥그레지며>$B$B이런…악마들의 세상이 도래했군!$B$B역사가 카르닉에게 돌아가 왕의 이름으로 이 정보에 따라 신속하고 단호하게 조치를 취하라고 전하시오. 그에게 모든 수단과 방법을 동원해 황야의 땅에서 어둠괴철로 드워프들의 활동을 저지하라고 전해야 한다고 하시오.', '역사가 카르닉과 대화해야 합니다.', NULL, '아이언포지에 있는 역사가 카르닉과 대화해야 합니다.', NULL),
(727, '야그인의 법전을 찾아서', '이 서판은 많은 것을 말해 주지. 하지만 아직 부족해! 너무 부족해!$B$B아주 오래전에 야그인이 쓴 법전이 있어. 날… 잡아두었던 자들… 그자들이 그 법전을 여러 장소에 보관해 두고 있어. 그리고 학자들이 연구를 하지. 그 법전에는 방대한 지식이 담겨 있어. 우리를 보호해줄 지식 말이야!$B$B아이언포지의 게릭 본그립을 찾아가. 그는 아이언포지의 쓸쓸한 뒷골목에 있는 상점에 있어. 이 인장을 보여주면 당신이 같은 편이라고 생각할 거야. 야그인의 법전을 달라고 해서… 내게 가져와 줘!', '아이언포지의 쓸쓸한 뒷골목에 있는 게릭 본그립에게 해머의 인장을 가져가야 합니다.', NULL, NULL, NULL),
(728, '야그인의 법전을 찾아서', '이 서판은 많은 것을 말해 주지. 하지만 아직 부족해! 너무 부족해!$B$B아주 오래전에 야그인이 쓴 법전이 있어. 날… 잡아두었던 자들… 그자들이 그 법전을 여러 장소에 보관해 두고 있어. 그리고 학자들이 연구를 하지. 그 법전에는 방대한 지식이 담겨 있어. 우리를 보호해줄 지식 말이야!$B$B로데론의 언더시티에 있는 관리인 벨두거를 찾아가. 이 인장을 보여주면 당신이 같은 편이라고 생각할 거야. 야그인의 법전을 달라고 해서… 내게 가져와 줘!', '언더시티에 있는 관리인 벨두거에게 해머의 인장을 가져가야 합니다.', NULL, NULL, NULL),
(730, '어둠해안에 생긴 문제', '이 세계의 위대한 고고학적 불가사의에 관심을 가진 $C|1을;를; 만나게 되어 정말 기쁘오.$B$B얼라이언스 친구들은 우리 일을 단순한 취미 정도로 치부하는 경우가 종종 있지. 그러나 최근 카즈 모단에서 발견된 것들은 어떤 강력한 세력이 로데론에서 칼림도어에 이르는 아제로스 전역을 위협하고 있음을 증명하고 있소. 얼마나 많은 이들이 이걸 깨닫지 못하고 있는지…$B$B지금 가장 큰 근심은 어둠해안으로 보낸 우리 대원들이오. 벌써 몇 주 동안이나 소식이 끊겼소. 아우버다인으로 가서 그들의 소재에 대한 단서를 찾아봐 주겠소?', '아우버다인으로 가서 드워프 발굴단의 흔적을 찾아야 합니다.', NULL, NULL, NULL),
(732, '대지의 진동', '엘룬께 영광을. 그대가 시그런을 많이 도와 줬다고 들었기에 나도 도움을 좀 청할까 하네. 우리 스승님인 키린 토의 크라서스 님께서 레슬로 협곡에서 발생한 문제를 해결하라고 나를 이곳에 보내셨지.$B$B이곳에서 내가 맡은 임무에 대해서 자세하게 얘기해 줄 수는 없지만, 매우 중요한 임무라는 것만은 확실히 말할 수 있다네.$B$B보프 야영지 근처에서 가끔 보이는 떠돌이 오우거 무리가 대지의 봉인이라는 물건을 훔쳤는데 그걸 되찾아 와야 해. 그대가 날 위해 그걸 찾아와 준다면 자세한 얘기를 해 주겠네.', '가렉을 위해 대지의 봉인을 되찾아야 합니다.', NULL, '황야의 땅 해머토의 발굴현장에 있는 가렉에게 가야 합니다.', NULL),
(733, '자재 모으기', '내가 방어 도구나 기타 다른 필수 장비들을 제작할 자재를 찾아오지 못하면 이곳 상황이 안 좋아질 수도 있소. 이 지역의 오우거들은 금속 조각들을 방어구로 사용하여 단단히 무장하고 있는 것 같소. 그러고 보니 황야의 땅에 증기 전차가 있다는 이야기가 헛소문이 아닐지도 모르겠군.$B$B아무튼, 발굴조사단장은 이 작은 야영지의 상황을 걱정하고 있소. 그래서 가능한 빨리 작업을 시작해야 할 것 같은데…$B$B오우거의 주 야영지는 서쪽으로 멀리 떨어져 있는 먼지목도리 소굴에 있으니 금속 조각을 좀 가져다주시오.', '시그런에게 금속 조각 7개를 가져가야 합니다.', NULL, '황야의 땅에 있는 시그런 아이언휴에게 가야 합니다.', NULL),
(734, '불길한 예감', '훌륭해, 정말 훌륭해…$B$B<다시 족쇄 만들기에 몰두하기 전에 잠시 올려다보는 로트윌>$B$B루시앙에게 가 봐요. 그리고 5번 기어가 필요하다고 말하고 그걸 내게 좀 가져다줄래요?', '황야의 땅에 있는 루시앙 토슬렌치와 대화해야 합니다.', NULL, NULL, NULL),
(735, '별, 손, 그리고 심장', '야그인의 법전? 드워프 역사의 새로운 장이라도 쓸 생각인가? 아니, 그건 내가 물어볼 질문이 아니로군.$B$B내게 여분이 한 권 있으니 자네를 도와 주도록 하지. 서로 도와 가며 사는 게 도리 아닌가? 그래야 발전이 있는 법이지.$B$B하지만 그전에 내가 원하는 3개의 강력한 물건들을 가져와야 하네. 확인 후 법전을 주도록 하지.$B$B쉿! 지금 누가 엿듣고 있을지도 모르니 물건들의 이름을 소리 내어 말하지는 않겠어. 대신 여기 적어 주지.', '아이언포지의 쓸쓸한 뒷골목에 있는 게릭 본그립에게 본그립의 노트에 적힌 물건들을 가져가야 합니다.', NULL, '아이언포지의 쓸쓸한 뒷골목에 있는 게릭 본그립에게 가야 합니다.', NULL),
(736, '별, 손, 그리고 심장', '야그인의 법전이 필요하다고? 그렇다면 당신 계획은 또 다른 무리를 모으는 것인가? 당연히 그럴 테지… 물론, 도와주도록 하겠소. 하지만 당신도 날 도와줘야겠소.$B$B내가 요구하는 세 가지 강력한 물건을 가져오면 법전을 주도록 하지. 이 물건들의 이름은 입에 올리지는 못하니 노트에 적어 주도록 하겠소.$B$B이 목록에 적힌 이름의 물건들을 가져올 수 있을 정도라면 당신은 정말 우리 포세이큰에 새로운 역사를 기록할 만한 자격이 있는 것이오.', '언더시티에 있는 벨두거에게 벨두거의 노트에 적힌 물건들을 가져가야 합니다.', NULL, '언더시티에 있는 관리인 벨두거에게 가야 합니다.', NULL),
(737, '금지된 지식', '자, 받게. 이 법전을 소중히 다루어야 하네. 또한 적의 손에 넘어가지 않도록 하길 바라네.$B$B이 법전에는 많은 진실이 담겨 있지…$B$B…저절로 타버릴 수도 있는 진실 말이야.', '텔두린에게 야그인의 법전을 가져가야 합니다.', NULL, NULL, NULL),
(739, '멀달록', '아그몬드의 자취가 서쪽에서 이어지고 있습니다. 바위와 모래에 피가 묻어 있는 것으로 보아 이 드워프는 죽기 전에 얼마간의 거리를 기어와서 이곳에서 죽은 것으로 보입니다.$B$B자세히 살펴보니 황야의 땅 사암 조각에 ≪멀달록≫이라는 단어가 휘갈겨 쓰여 있습니다. 아마도 아그몬드가 죽기 직전에 쓴 것으로 보입니다.$B$B이 단어가 쓰인 바로 옆에는 죽은 아그몬드의 손이 있습니다.', '아그몬드를 살해한 멀달록을 처치해야 합니다.바위동굴 뼈다귀싸움꾼 12마리를 처치해야 합니다.그 후 모단 호수에 있는 발굴조사단장 아이언밴드에게 보고하십시오.', NULL, '모단 호수의 아이언밴드의 발굴현장에 있는 발굴조사단장 아이언밴드에게 가야 합니다.', NULL),
(740, '[미사용]', NULL, NULL, NULL, NULL, NULL),
(743, NULL, NULL, NULL, NULL, '멀고어의 블러드후프 마을에 있는 루울 이글탈론에게 가야 합니다.', NULL),
(744, NULL, NULL, NULL, NULL, '멀고어의 해넘이 기지에 있는 이얀 이글탈론에게 가야 합니다.', NULL),
(745, NULL, NULL, NULL, NULL, '멀고어의 블러드후프 마을에 있는 바인 블러드후프에게 가야 합니다.', NULL),
(746, NULL, NULL, NULL, NULL, '멀고어의 블러드후프 마을에 있는 바인 블러드후프에게 가야 합니다.', NULL),
(747, NULL, NULL, NULL, NULL, '멀고어의 나라체 야영지에 있는 그룰 호크윈드에게 가야 합니다.', NULL),
(748, NULL, NULL, NULL, NULL, '멀고어의 블러드후프 마을에 있는 멀 썬더혼에게 가야 합니다.', NULL),
(750, NULL, NULL, NULL, NULL, '멀고어의 나라체 야영지에 있는 그룰 호크윈드에게 가야 합니다.', NULL),
(753, '작은 부탁', '내 소싯적에는 여행도 많이 다니곤 했지만 이젠 몸이 예전 같지 않구먼. 그래도 아직은 부족을 위해 내 소임을 다할 정도는 된다네. 나이 든 노파이니 때론 예전보다 시간이 좀 더 걸리는 편이긴 하지만 말이야.$B$B자네는 의욕이 넘치는 $C 같군. 그 젊은 혈기로 부탁 하나만 들어주지 않겠나? 우물에 있는 물병을 내 아들, 나라체 야영지의 족장에게 좀 가져다주게나.$B$B보잘것없는 부탁이지만 잘해내 준다면 마을 장로들의 인정을 받을 수 있다는 사실을 잊지 말게.', '우물에 있는 물병을 집어서 우물에서 북서쪽에 있는 나라체 야영지의 족장 호크윈드에게 가져가야 합니다.', NULL, '멀고어의 나라체 야영지에 있는 족장 호크윈드에게 가야 합니다.', NULL),
(754, '윈터후프 정화', '윈터후프 우물을 정화할 토템이 완성되었소. 이제 이 토템을 우물로 가져가 정화의 의식을 수행하도록 하시오. 윈터후프 우물은 남동쪽에 있는데 괘씸한 고블린 녀석들이 지키고 있소.$B$B쉽지 않은 일이겠지만 우물을 다시 사용하려면 반드시 해야 할 일이오.$B$B행운이 함께하기를 비오.', '윈터후프 우물에서 윈터후프 정화 토템을 사용한 후 멀 썬더혼에게 가야 합니다.', '윈터후프 우물을 청소하세요', '멀고어의 블러드후프 마을에 있는 멀 썬더혼에게 가야 합니다.', NULL),
(756, '썬더혼 토템', '썬더혼 정화 토템을 만들기 위해서는 멀고어 평야에 살고 있는 포식 동물의 발톱을 모아 와야 하오. 긴발톱 초원늑대와 평원퓨마를 잡아 발톱을 구해 돌아오시오.$B$B긴발톱 초원늑대와 평원퓨마는 이곳의 동쪽과 서쪽에서 발견할 수 있을 거요.', '멀 썬더혼에게 긴발톱 초원늑대 발톱 6개와 평원퓨마 발톱 6개를 가져가야 합니다.', NULL, '멀고어의 블러드후프 마을에 있는 멀 썬더혼에게 가야 합니다.', NULL),
(757, '힘의 의식', '대지모신의 의식은 젊은 타우렌이 썬더 블러프에서 인정을 받기 위해 반드시 거쳐야 할 과정이요.$B$B우선 그대는 이번 힘의 의식을 통과해야만 하오. 이 시험을 통해 그대는 부족의 적을 처치하여 자신의 용맹함을 증명해야 하오.$B$B동쪽에 있는 칼날가시 협곡의 뾰족털 일족이 우리 부족의 땅을 침범하고 있소. 그들은 우리 사냥꾼들을 매복하여 공격하고 어둠을 틈타 마을을 약탈하고 있소.$B$B이 악당들을 처치하여 그대의 용맹함을 보이고, 그 증거로 그들의 허리띠를 나라체 야영지의 족장님께 가져가도록 하시오.', '칼날가시 협곡에 있는 뾰족털 일족을 처치하고 나라체 야영지에 있는 족장 호크윈드에게 뾰족털 허리띠 12개를 가져가야 합니다.', NULL, '멀고어의 나라체 야영지에 있는 족장 호크윈드에게 가야 합니다.', NULL),
(758, '썬더혼 정화', '토템이 준비되었소. 다시 한번 말하지만, 정화의 의식을 수행하는 건 $g형제:자매;의 몫이오.$B$B마을 북쪽에 있는 썬더혼 우물로 가서 썬더혼 정화 토템을 사용하여 의식을 수행하시오. 의식을 마친 후에는 내게 돌아와야 하오.$B$B정령들의 가호가 함께하기를…', '썬더혼 우물에서 썬더혼 정화 토템을 사용한 다음 멀 썬더혼에게 가야 합니다.', '썬더혼 우물을 정화하세요', '멀고어의 블러드후프 마을에 있는 멀 썬더혼에게 가야 합니다.', NULL),
(759, NULL, NULL, NULL, NULL, '멀고어의 블러드후프 마을에 있는 멀 썬더혼에게 가야 합니다.', NULL),
(761, NULL, NULL, NULL, NULL, '멀고어의 블러드후프 마을에 있는 하큰 윈드토템에게 가야 합니다.', NULL),
(762, '악의 사자', '라그나로스는 울다만에서 사라진 유물을 찾고 있는 어둠괴철로 드워프들을 보호하기 위해 사자 인페르누스를 고통의 요새로 보냈지.$B$B이미 우리 종족에게 무서운 참사가 일어났지만 그 위력은 우리의 예상보다는 미비한 것이었네. 하지만 놈들이 얼마나 많은 양의 유물을 찾아 아이언포지 공격에 사용할지 생각하기조차 싫군.$B$B우리의 목표는 간단하네, $C. 황야의 땅으로 돌아가 사자 인페르누스를 처치하게. 위협이 제거되면 승리의 증거를 가지고 조언자 벨그룸 님께 돌아가면 되네.$B$B이제 모든 건 자네 손에 달렸어.', '고통의 요새에 있는 사자 인페르누스를 처치하고 아이언포지에 있는 조언자 벨그룸에게 그의 죽음에 대한 증거를 가져가야 합니다.', NULL, '아이언포지에 있는 조언자 벨그룸에게 가야 합니다.', NULL),
(763, '대지모신의 의식', '대지모신의 의식을 계속 수행하려면 두 가지 시험을 더 통과해야 하네. 그대의 경험을 넓힐 때가 된 것이야.$B$B블러드후프 마을로 가서 케른 블러드후프님의 아들이자 족장인, 바인 블러드후프를 찾도록 하게. 거기서 모험을 계속하다 보면 썬더 블러프 장로들의 신임을 얻을 수 있을 걸세.$B$B이 토템을 바인에게 가져가도록 하게. 그 친구가 내 목각품이라는 것을 알아보고 그대를 도와줄 걸세.$B$B서둘러 나라체 야영지 외각의 길을 따라가도록 하게. 한눈팔면 길을 잃을 수도 있으니 조심하게.', '블러드후프 마을에 있는 바인 블러드후프에게 호크윈드의 토템을 가져가야 합니다. 나라체 야영지 외곽의 길을 따라가십시오.', NULL, NULL, NULL),
(764, NULL, NULL, NULL, NULL, '멀고어에 있는 모린 클라우드스토커에게 가야 합니다.', NULL),
(765, NULL, NULL, NULL, NULL, '멀고어에 있는 모린 클라우드스토커에게 가야 합니다.', NULL),
(766, NULL, NULL, NULL, NULL, '멀고어의 블러드후프 마을에 있는 마우르 레인콜러에게 가야 합니다.', NULL),
(767, '예언의 의식', '대지모신의 의식 중 하나인 예언의 의식은 썬더 블러프 장로들의 신임을 얻는 데 도움이 될 걸세.$B$B우리 타우렌들은 대지가 우리의 가장 신성한 부양자라는 사실을 배워 왔지. 의식에서 예언을 직접 얻으려면 마을의 정신적 지도자인 잘만 투문을 만나야 할 게야.', '블러드후프 마을에 있는 잘만 투문과 대화해야 합니다.', NULL, NULL, NULL),
(768, NULL, NULL, NULL, NULL, '썬더 블러프에 있는 베렌 톨스트라이더에게 가야 합니다.', NULL),
(769, NULL, NULL, NULL, NULL, '썬더 블러프에 있는 베렌 톨스트라이더에게 가야 합니다.', NULL),
(771, NULL, NULL, NULL, NULL, '멀고어의 블러드후프 마을에 있는 잘만 투문에게 가야 합니다.', NULL),
(772, '예언의 의식', '자, 현자의 물을 받게.$B$B준비가 되면 부족의 불 근처에서 그 물을 마시게나. 현자의 물을 마신 후 조금 있으면 불 앞에 미래의 예언이 나타날 것이야.$B$B바로 그때, 그것을 운명으로 따를 것인지는 그대에게 달려 있네.', '블러드후프 마을에 있는 부족의 불 앞에서 현자의 물을 마시고 나타나는 예언을 따라가야 합니다.', NULL, NULL, NULL),
(774, '<미사용>', NULL, NULL, NULL, NULL, NULL),
(776, NULL, NULL, NULL, NULL, '썬더 블러프에 있는 케른 블러드후프에게 가야 합니다.', NULL),
(777, '불길한 예감', '자, 여기 있습니다.$B$B전 이 덮개 뒤에 몸을 숨길 거예요.$B$B이리 와서 여기 숨으세요.', '로트윌 베리아투스에게 5번 기어를 가져가야 합니다.', NULL, '황야의 땅에 있는 로트윌 베리아투스에게 가야 합니다.', NULL),
(778, '불길한 예감', '하하! 드디어 다 됐군! 족쇄가 완성되었단 말이야!$B$B루시앙! 세르보! 준비해!$B$B연금술, 공학, 그리고 불가사의의 완벽한 결정체를 직접 볼 준비가 됐나요?$B$B이제 강력한 정령을 불러낼 거예요. 오늘은 우리 모두 새로운 걸음을 내딛는 뜻 깊은 날이 될 거라고요.', '팜레터 수호정령을 물리치고 로트윌 베리아투스에게 로트윌의 정령 봉인 족쇄를 가져가야 합니다.', NULL, '황야의 땅의 먼지받이에 있는 로트윌 베리아투스에게 가야 합니다.', NULL),
(779, '대지의 봉인', NULL, NULL, NULL, '황야의 땅에 있는 대지의 봉인으로 가야 합니다.', NULL),
(780, '전투멧돼지', '동쪽에 있는 칼날가시 협곡의 전투멧돼지들이 우리 부족의 사냥터를 침범하고 있소. 그 전투멧돼지들은 우리와 전쟁 중인 뾰족털 가시멧돼지 놈들이 조련시킨 것이오.$B$B이 괘씸한 짐승들을 처치하고 우리 아이들을 위해 스튜를 만들 수 있도록 주둥이와 갈빗살을 몇 점 가져다주시오.', '나라체 야영지에 있는 그룰 호크윈드가 전투멧돼지를 처치하고 전투멧돼지 주둥이 8개와 전투멧돼지 갈빗살 8점을 가져다 달라고 했습니다.', NULL, '멀고어의 나라체 야영지에 있는 그룰 호크윈드에게 가야 합니다.', NULL),
(781, '나라체 야영지에 대한 공격', '지도를 꼼꼼히 살펴본 당신은 뾰족털 대족장이 나라체 야영지에 대한 대대적인 포위 공격을 계획하고 있음을 알아차립니다.$B$B이는 분명히 족장 호크윈드에게 유용한 정보가 될 것입니다!', '나라체 야영지에 있는 족장 호크윈드에게 뾰족털 작전도를 가져가야 합니다.', NULL, NULL, NULL),
(782, '깨어진 동맹', '2차 대전쟁 때 호드가 용 데스윙과 동맹을 맺었던 경험을 통해, 우리는 데스윙의 부관인 블랙래쉬와 헤마투스가 저 먼 동쪽 레슬로 협곡에 갇혀 있었다는 사실을 익히 알고 있소. 우리는 반드시 타락한 옛 동지를 처단하여 호드라는 이름의 명예를 회복해야 하오!$B$B우리는 토그룬과 그의 오우거 용병 부대를 고용해 비룡의 감옥을 여는 열쇠인 대지의 봉인을 찾고 있었소.$B$B그런데 토그룬이 우리를 배신하고 봉인을 가져가 버렸으니 보프 야영지로 가서 봉인을 되찾아 오시오!', '우두머리 토그룬을 처치하고 카르가스에 있는 고른에게 대지의 봉인을 가져가야 합니다.', NULL, '황야의 땅의 카르가스에 있는 고른에게 가야 합니다.', NULL),
(784, NULL, NULL, NULL, NULL, '듀로타에 있는 가르톡에게 가야 합니다.', NULL),
(785, '전략적 동맹', '스랄 님은 지혜롭고 훌륭한 지도자시지. 뛰어난 외교적 수완만큼이나 전장에서 집념도 대단하시고 말일세.$B$B이제 우리에게 있어 검은창 트롤은 연합군으로서 대단히 중요한 힘이 돼주고 있지. 우리는 충성과 명예를 담아 그들과 보호 협정을 맺었네.$B$B그래서 대족장님께서는 센진 마을에 있는 검은창 연합군에게 직접적으로 가해지는 위협들을 모두 제거하라는 명령을 내리셨네. 검은창 트롤의 가장 믿음직한 정찰병인 라르 프라울터스크가 서쪽 측면 지역을 엄중히 감시하고 있네.$B$B라르를 찾아 도움을 주도록.', '센진 마을 서쪽 측면 지역에서 라르 프라울터스크를 찾아야 합니다.', NULL, NULL, NULL),
(786, NULL, NULL, NULL, NULL, '듀로타의 센진 마을에 있는 라르 프라울터스크에게 가야 합니다.', NULL),
(787, '호드 신병', '트롬카! 난 스랄 님으로부터 신병 훈련 임무를 받은 아이트리그라 하네.$B$B지금의 호드는 예전과 많이 달라졌네. 한 때 권력에 굶주린 불타는 군단과 결탁한 앞잡이들이 세력을 불렸다네. 나는 환멸을 느껴 호드를 떠났던 적이 있네. 그 후 인간 무리에 포로로 잡혔었는데 대족장님께서 나를 구해 주셨다네. 나는 대족장님의 뜻에 공감하여 다시 돌아왔다네. 그분께서는 주술사들의 지도하에 악마의 세력에서 벗어난 자유로운 호드를 꿈꾸셨지.$B$B동굴 막사에 있는 고르넥이 자네에게 앞으로의 훈련 내용을 자세히 알려줄 걸세.', '동굴 막사에 있는 고르넥에게 보고해야 합니다.', NULL, NULL, NULL),
(788, NULL, NULL, NULL, NULL, '듀로타의 시험의 골짜기에 있는 고르넥에게 가야 합니다.', NULL),
(789, NULL, NULL, NULL, NULL, '듀로타의 시험의 골짜기에 있는 고르넥에게 가야 합니다.', NULL),
(790, NULL, NULL, NULL, NULL, '듀로타에 있는 하나주아에게 가야 합니다.', NULL),
(791, NULL, NULL, NULL, NULL, '듀로타의 칼바위 언덕에 있는 펄 스콘브라우에게 가야 합니다.', NULL),
(792, NULL, NULL, NULL, NULL, '듀로타의 시험의 골짜기에 있는 주리타 파게이즈에게 가야 합니다.', NULL),
(793, NULL, NULL, NULL, NULL, '황야의 땅의 아포크리판의 안식처에 있는 고른에게 가야 합니다.', NULL),
(794, '불타는 칼날단 메달', '내가 점을 쳐본 바로는 불타는 칼날단 소굴 깊숙한 곳에 강한 힘을 지닌 무언가가 숨겨져 있는 게 보여요. 짐승들과 흑마법이 그것을 지키고 있지요.$B$B불타는 칼날단 메달이라 불리는 것인데, 당신의 다음 임무는 소굴 안에서 그 물건을 찾아 가져오는 거예요.$B$B하지만 그 물건을 지닌 녀석은 이전에 당신이 상대했던 하수인들보다 훨씬 강할 테니 조심하도록 하세요.$B$B북쪽으로 가서 동굴을 찾으면 동굴 안 북쪽과 서쪽에서 그 무리를 찾을 수 있을 거예요.', '동굴 막사 외부에 있는 주리타 파게이즈에게 불타는 칼날단 메달을 가져가야 합니다.', NULL, '듀로타 시험의 골짜기에 있는 주리타 파게이즈에게 가야 합니다.', NULL),
(795, '대지의 봉인', NULL, NULL, NULL, '황야의 땅에 있는 대지의 봉인으로 가야 합니다.', NULL),
(796, '<미사용>', NULL, NULL, NULL, NULL, NULL),
(797, '<미사용>', NULL, NULL, NULL, NULL, NULL),
