(31118, NULL, NULL, NULL, NULL, '현장의 음영파 동료와 대화하거나 탕랑 평원의 음영파 주둔지에 있는 사부 스노우드리프트에게 돌아가야 합니다.', NULL),
(31119, NULL, NULL, NULL, NULL, '현장의 음영파 동료와 대화하거나 탕랑 평원의 음영파 주둔지에 있는 사부 스노우드리프트에게 돌아가야 합니다.', NULL),
(31120, NULL, NULL, NULL, NULL, '탕랑 평원의 음영파 주둔지에 있는 사부 스노우드리프트와 대화해야 합니다.', NULL);
INSERT INTO `_koKR_stage_quest_template_locale` (`ID`, `LogTitle`, `QuestDescription`, `LogDescription`, `AreaDescription`, `QuestCompletionLog`, `PortraitGiverText`) VALUES
