-- Korean locale additions for `quest_template_locale`.
-- Update existing rows and insert missing rows only when the parent exists.
-- Preserve existing Korean text and other locales.
DROP TEMPORARY TABLE IF EXISTS `_koKR_stage_quest_template_locale`;
CREATE TEMPORARY TABLE `_koKR_stage_quest_template_locale` (
    `ID` INT UNSIGNED NOT NULL,
    `LogTitle` LONGTEXT NULL,
    `QuestDescription` LONGTEXT NULL,
    `LogDescription` LONGTEXT NULL,
    `AreaDescription` LONGTEXT NULL,
    `QuestCompletionLog` LONGTEXT NULL,
    `PortraitGiverText` LONGTEXT NULL,
    PRIMARY KEY (`ID`)
) ENGINE=InnoDB;















UPDATE `quest_template_locale` AS `l`
INNER JOIN `_koKR_stage_quest_template_locale` AS `s` ON `l`.`ID` = `s`.`ID` AND `l`.`locale` = 'koKR'
INNER JOIN `quest_template` AS `p` ON `p`.`ID` = `s`.`ID`
SET `l`.`LogTitle` = IF(`s`.`LogTitle` IS NOT NULL AND (`l`.`LogTitle` IS NULL OR `l`.`LogTitle` NOT REGEXP '[가-힣ㄱ-ㅎㅏ-ㅣ]'), `s`.`LogTitle`, `l`.`LogTitle`),
    `l`.`QuestDescription` = IF(`s`.`QuestDescription` IS NOT NULL AND (`l`.`QuestDescription` IS NULL OR `l`.`QuestDescription` NOT REGEXP '[가-힣ㄱ-ㅎㅏ-ㅣ]'), `s`.`QuestDescription`, `l`.`QuestDescription`),
    `l`.`LogDescription` = IF(`s`.`LogDescription` IS NOT NULL AND (`l`.`LogDescription` IS NULL OR `l`.`LogDescription` NOT REGEXP '[가-힣ㄱ-ㅎㅏ-ㅣ]'), `s`.`LogDescription`, `l`.`LogDescription`),
    `l`.`AreaDescription` = IF(`s`.`AreaDescription` IS NOT NULL AND (`l`.`AreaDescription` IS NULL OR `l`.`AreaDescription` NOT REGEXP '[가-힣ㄱ-ㅎㅏ-ㅣ]'), `s`.`AreaDescription`, `l`.`AreaDescription`),
    `l`.`QuestCompletionLog` = IF(`s`.`QuestCompletionLog` IS NOT NULL AND (`l`.`QuestCompletionLog` IS NULL OR `l`.`QuestCompletionLog` NOT REGEXP '[가-힣ㄱ-ㅎㅏ-ㅣ]'), `s`.`QuestCompletionLog`, `l`.`QuestCompletionLog`),
    `l`.`PortraitGiverText` = IF(`s`.`PortraitGiverText` IS NOT NULL AND (`l`.`PortraitGiverText` IS NULL OR `l`.`PortraitGiverText` NOT REGEXP '[가-힣ㄱ-ㅎㅏ-ㅣ]'), `s`.`PortraitGiverText`, `l`.`PortraitGiverText`);

SELECT `s`.`ID`, 'koKR', `s`.`LogTitle`, `s`.`QuestDescription`, `s`.`LogDescription`, `s`.`AreaDescription`, `s`.`QuestCompletionLog`, `s`.`PortraitGiverText`
FROM `_koKR_stage_quest_template_locale` AS `s`
INNER JOIN `quest_template` AS `p` ON `p`.`ID` = `s`.`ID`
LEFT JOIN `quest_template_locale` AS `l` ON `l`.`ID` = `s`.`ID` AND `l`.`locale` = 'koKR'
WHERE `l`.`ID` IS NULL;

DROP TEMPORARY TABLE `_koKR_stage_quest_template_locale`;
